/* 平成27年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h27.committeeSessions.push(...[{"id":"h27-20150824-9","meetingId":"h27-cm08","date":"2015年8月24日","dateIso":"2015-08-24","committee":"文教委員会","time":"午後 １時００分～午後 ３時２０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件整理しています。","topics":[{"id":"topic-01","title":"平成２８年度品川区立小・中学校使用教科用図書の採択","agenda":"平成２８年度品川区立小・中学校使用教科用図書の採択","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"この中で、前回の４年前と出版社が変わったところがあれば、どの教科なのか説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"変わった教科書といたしましては、書写、数学、理科、保健体育、英語です。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"前々回ですか、公開ができないのだというようなお話を一度ちらっと伺ったのですが、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"検討委員および研究会の検討内容、それぞれ採択の時期が８月中まで、実際には３１日までというふうにお答えをしておりました。実際の来場者数といたしましては、教育総合支援センターと品川図書館の合計になりますが、延べ３２１名の方々が来られました。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味で中身を知りたいということが１つ。どうしたら中身を見ることができるのか教えていただきたいのと、伝わってくるような報告をいただきたいと思うのですが、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"１つの参考ということで、これを参考に一応見ていただいた上で、それぞれ各教科の先生方がつくられた部分を踏まえて検討をさせていただきました。この場で具体的に説明はできないのですが、あくまでも品川区の子どもたちにとって、より適切なというか。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どういうまとめ方をされたかわかりませんが、これは手に入れることはできるのでしょうか。手立てを教えていただきたいのと、中身の議論はお伺いしましたけれども、その点も説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"すみません、もともとこれは公開しますよとか、この場でどういう形であれば見られるかということを今すぐにお答えできないというところです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"どこかで検討する余地があるのかどうか、その点を１点と、公開の議事録は箇条書きにしてあるだけですね。あれ以外はわからないということか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"最初のアンケートの部分につきましては、持ち帰らせていただくということになります。２点目の箇条書きにつきましては、あの形が今まで出している方法ですので、あれ以上のものは出ないということです。","id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"質問","question":"時期で、さらに費用がかかるので、就学援助等の扱いはどうなっているでしょうか。もしわかれば。","respondent":"村尾教育総合支援センター長","answer":"副教材というのは、区で作成している個別のものの……。","id":"exchange-006"}]},{"id":"topic-02","title":"臨時給付金","agenda":"臨時給付金","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"わかれば教えていただきたいのと、あと、改めてまだ申請していませんというふうな送付などはされるということでしょうか。その辺を説明するよう求めました。","respondent":"廣田臨時給付金担当課長","answer":"今回、昨年の児童手当受給者の中で不支給になっている人数が９,０００人ぐらいというところで、そのぐらい人数がいるということで認識しております。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"１つの助けになるということなのですが、寡婦控除とか、そういった方は自分でそこを調べて何とかしなければいけない部分なのでしょうか。こういった控除も差し引いたところでお考えくださいみたいな、そういった周知みたいなものをしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"廣田臨時給付金担当課長","answer":"２割の方は逆に支給を受けていないということになるのですけれども、二、問い合わせを受けてということをやります。今、そのあたりは税務課と連携して、なるべく対象の方が漏れないようにというところでやっていきたいと考えています。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"シルバー人材センターによる申請補助業務、あとケアマネジャー、今までケアマネがこういうことを補助するということはなかったのですか。私は、ここのところを十分生かしていただいて、必要な方全てに支給されるようにしていただきたいと考えています。","respondent":"廣田臨時給付金担当課長","answer":"ケアマネジャーにつきましては、昨年もご協力をいただいておりまして、かなり熱心にやっていただいたところです。いい方法がありましたら、ご提案いただければ、またやっていこうとは思っております。","id":"exchange-009"},{"speaker":"浅野委員","kind":"質問・要望","question":"これはやはりやられるということだと思いますけれども、はっきりした説明ではなかったので、ここを確認したいと思います。そういうものも使えなくはないかと思うのですけれども、多分これもやられるのではないかと思いますが、一応確認させてほしいと求めました。","respondent":"廣田臨時給付金担当課長","answer":"税務課のほうで未申告者の督促のときに、臨時給付金についても入れていただくということは例年どおり行う予定です。比較的お若い方もいらっしゃるということで有効と考えておりまして、ツイッターも全て、昨年やったものは全て一緒に実施するという予定です。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問・要望","question":"２３区との比較は難しいということですけれども、国全体との比較はどうなのでしょうか。これからまたさまざまな媒体も出るでしょうから、そういうものを活用していってもらいたいと思いますので、答弁をお願いします。","respondent":"廣田臨時給付金担当課長","answer":"６割、児童手当の６月分の支給と合致しておりますので、公務員以外はほぼ１００％までいっているようにしようと思ってあります。他区で低いところで５割、６割のところが、序列には出ていないので。","id":"exchange-011"},{"speaker":"伊藤副委員長","kind":"質問","question":"たまたま品川区と同じような人口規模の市役所に行く機会があったときに見てきたのですけれども、受付カウンターは相当数があったのです。イメージとして、５万１,０００件の対象ですから、人材を何名ぐらい用意して対応するのでしょうかということをぜひお伺いしたいです。","respondent":"廣田臨時給付金担当課長","answer":"１３カ所の地域センターで、書き方ですとか、地域センターでもかなり受けてもらえるというふうに考えてあります。ケアマネには、１件幾らでお礼をしているので、比較的確実にサポートした分については上がってくるという形です。","id":"exchange-012"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"参考までに、持参された方は前回のときには何人ぐらいいらっしゃったのですか。もしわかれば教えていただきたいのです。","respondent":"廣田臨時給付金担当課長","answer":"防災センターの３階で窓口を準備してお待ちしたのですけれども、今度、コールセンターと一緒にした経過があります。窓口でないと対応が、最終的には、コールセンターで対応できないものにつきましては子ども家庭支援課で受けるようなつもりです。","id":"exchange-013"}]},{"id":"topic-03","title":"認可保育園等の新規開設","agenda":"認可保育園等の新規開設","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"どんな会社か把握されているのか、どんな会社なのか、わかっていれば教えていただきたいのですが。それと、今回の５園に限ってでいいのですけれども、現在、区内に保育施設を開設している設置者はあるのかどうかを説明するよう求めました。","respondent":"今井待機児童対策担当課長","answer":"なお、1)のキッズコーポレーションは、同じ代表者が、都外ではありますが幼保連携認定こども園を設置しております。2)と4)につきましては、都内でも認可保育園、認証保育所の実績がある事業者です。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"保育士確保が困難な状況にあるとか、そうは言っても、なかなか大変な部分があるという声などは届いているのか。開設はするのだけれども、そういったところは区としは捉えているのか、把握しているのか伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"２３区、小規模の開設をしておりますので、保育士については確かに確保がなかなか難しい現状というふうに設置者からも聞いております。やはり都内または全国で開設する全体の数等をにらみながら、この事業者が適正に保育士を確保できるかも踏まえて検討を進めてきたところです。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと、園庭がある保育園はこの５つの中にあるのでしょうか。なければ、ここに簡単な地図も出ていますけれども、どこに遊びに行く公園があるのかを伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"こちらの５園ですけれども、自分の施設の中で遊戯場ということで屋外のものを持つ予定なのは、屋外遊戯場を予定しております。それぞれ近接の公園で屋外遊戯場を代替する予定の計画です。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"お母さんにとっても不安な問題になってきていると思うので、代替になる公園は、まだ予定検討中ということですか。今、検討されているということか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"こちらは、通例、私ども、認可保育園の新規開設につきましては、本当は認可申請のときに確定いたしますので、その時点でというふうに思っておりますが、計画承認の中では、まだ面積または定員を含めて、屋外遊戯場も含めて、今、計画の段階ですので、検討中です。","id":"exchange-017"},{"speaker":"浅野委員","kind":"質問","question":"例えば1)のなーさりぃ大森駅前園ですけれども、こちらはビルの２階ということで、そういうところについて教えてほしいと求めました。","respondent":"今井待機児童対策担当課長","answer":"いわゆる建物を、更地といいますか、土地から建てていく、一から建てていくに該当いたしますのが、2)のきたしながわさくらさくほいくえん、それから4)のほっぺるランド東五反田、この２園です。","id":"exchange-018"},{"speaker":"浅野委員","kind":"質問","question":"特に増えることに関しましては歓迎です。これからも。","respondent":"今井待機児童対策担当課長","answer":"もう１カ所ございました。5)のポピンズナーサリースクール勝島につきましては、2)と4)、5)の３園です。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"このことによって今後どうなっていくのかという見通しをお伺いしたいと思いますけれども、改めて平成２７年度、平成２８年度で。平成２８年度に向けて、そのあたり、見通しについても説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"今、平成２７年度は今まで報告いたしました数も含めて、全体の受入枠の拡大数は６４５ということで予定しております。やはり２３区全体的な取り組みも今進んでおりますので、２３区を挙げて、引き続きさらに強化して取り組んでいきたいというふうに思っております。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"そういうふうに受けとめていいのですか。前の保育計画、とりあえず計画のところでは認可保育園５園となっていますし、さらに認可保育園も強化をしていくというところでよろしいのか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"私、申し上げましたのは、平成２７年度が今６４５人、保育の受入枠拡大ですので、既に平成２８年度に向けましては、さらに強化していくです。この人口の推計に基づきまして、子ども・子育て支援事業計画につきましても、また一定見直しが必要だというふうに考えております。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１カ所では足りない、周りに今どんどん１,２００戸もマンション計画が立っているから、これでは間に合わないという声も上がったのです。今後の予測もきちんと立てていかないと、本当に間に合わないのではないかと思いますが、その辺はいかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"こちらは国家公務員宿舎のＰＦＩ事業で区のほうから要望して認可保育園を開設するに至ったということがあります。そして認証等、総合的な対策で、さらに考えて開設をしていきたいというふうに思っております。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"まず困難地域をきちんと把握をしているかどうかといったところで、ここのところ、本当に年々困難になっているということがわかっています。ここのところ、まず困難地域をどこと捉えていらっしゃるのか、またそこの解消策をどう考えているのか聞かせてほしいと求めました。","respondent":"今井待機児童対策担当課長","answer":"品川区は、困難地域として今考えておりますのは、いわゆる荏原地区は大変これからも開設が必要な地域というふうに把握しております。４０駅近くある中では、入園の申込みが多い地域、こういう地域に開設できるように開設担当としても取り組んでいるところです。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ期待をしていきたいし、まず、困難地域であるかどうかということをきちんと数字でつかんでいただきたい。四カ月と伺っていたのですが、今回の５園の初めにお話があった段階からというか、それから開設までの期間を具体的に教えていただきたいのですが。","respondent":"今井待機児童対策担当課長","answer":"七カ月としますと、その前に計画承認がありますので、開設の大体８カ月から１年ぐらい前には品川区のほうに企画提案が来ているというのが通常です。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"提案","question":"そういったところで、私たちはまだ足りないので、もっとつくっていただきたいし、区にもつくっていただきたいのですが、現状において、社会福祉法人や株式会社からどういった提案が来ているのか、いや、このごろ来なくなったのか。","respondent":"今井待機児童対策担当課長","answer":"ただし、それが企画提案という形で実りあるものになるのは、なかなか難しい形になっています。今は来年の４月ですけれども、そういう意味では、長期的な視野の中で確実に毎年認可保育園や小規模がきちんと開設できるように進めているところです。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"提案","question":"企画提案はたくさんあるということなので、その辺も力を入れながらやっていただきたいのと、品川区自身が新たにまた決断をしていただきたいとお願いして終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"伊藤副委員長","kind":"質問","question":"全体のことではなく、新規開設について質問します。そのときに品川区なりの説明をしてほしいと思うのですが、いかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"東京都からその書類が出たと同時に、区としても、区として計画協議を進めますということで内諾を出しております。事業者によっては細かく説明をする事業者もありますし、または、今後は事業者と調整する中できちんとご説明をしていくように。","id":"exchange-027"},{"speaker":"伊藤副委員長","kind":"質問","question":"どういう形態で運営していくかということについてぐらいは、これは新しい問題なのかもしれませんし、どんどん新しい業者が入ってくるわけですから。もう１つ踏み越えて、そういうガイドラインと言ったらいいのか、そういうものを検討してみてはいかがか尋ねました。","respondent":"金子子ども未来部長","answer":"新規開設の場合の企業の地元への説明あるいは町会長への説明というお尋ねですけれども、そういう意味では、民間の事業者にお任せしていました。区として政策を進めるためには、私どもとしては検討しているところですので、今回ご説明申し上げた５件。","id":"exchange-028"},{"speaker":"伊藤副委員長","kind":"質問","question":"やっぱりそこについては１つのガイドラインをつくっていただいて、地域に必要最小限、ぜひ内部で検討してくださいということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"すみません、最後に１つだけ。予算のところで伺いたいのですけれども、これの内容を教えていただきたいのと、運営費はどのくらいになっていくのかを伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"それから、１人頭２０万円という形で開設しておりますので、１２名だったら全部で２４０万円という形の開設準備経費が出ているところです。","id":"exchange-030"}]},{"id":"topic-04","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"浅野委員","kind":"質問・要望","question":"ＳＤカードで１週間程度で上書きというのは、それは確認ということで、後で答弁ほしいと求めました。カメラの点検ですけれども、これはどのような業者に保守委託をされるのかということ、こちらのほうを１点説明を求めました。","respondent":"品川庶務課長","answer":"委員のお見込みのとおり、１週間で上書きをしていくというような形になってありますので、１週間までということの考えです。データを見るときですが、どういう業者かということになりますと、基本的には電気関係の業者に委託をするというようなものになってあります。","id":"exchange-031"},{"speaker":"浅野委員","kind":"質問","question":"それなりの区としての判断というのでしょうか、それを行うにあたっての根拠となる条例ですとか、そういうものがあれば教えてほしいと求めました。","respondent":"品川庶務課長","answer":"主に管理責任者につきましては校長先生がなるというような形になってあります。管理者につきましては、学校の者で誰かというような形でやるようになってあります。","id":"exchange-032"},{"speaker":"浅野委員","kind":"質問","question":"年々少しずつ増やしていけるということがわかるのですけれども、既に設置をされているところ、多い少ないというのはさまざまだと思います。それともなかなか困難を極めて、つけたいと思っているところにつけられていないのか、このような概略を教えてほしいと求めました。","respondent":"品川庶務課長","answer":"設置につきましては、基本的には通学路の中で設置をするということになっていますので、その部分につきましてはつけられないというような回答をして。","id":"exchange-033"},{"speaker":"浅野委員","kind":"質問・要望","question":"この点をひとつお伺いしたいのと、私も年をとってきますと、これも全てこの教育の中でやられているのかということについて教えてください。それを継続して子どもたちが認識できるような取り組みというのは、どういうことをされているのか、教えてほしいと求めました。","respondent":"村尾教育総合支援センター長","answer":"海が近いので、この３つの安全については、基本やらなければならない部分ではありますので取り入れているというふうになっております。それぞれ毎年実施をし、より子どもたちの安全について効果的なもの、また効率的なものについて進めているです。","id":"exchange-034"},{"speaker":"浅野委員","kind":"確認","question":"そういうものを検討というのでしょうか、提出してもらって確認するとか、この点について説明を求めました。","respondent":"村尾教育総合支援センター長","answer":"教育課程届という３月に各学校から次年度の計画に基づいてやるときに、一緒に補助資料ということで教育委員会のほうに出していただいております。こちらのほうで一応内容を確認をしているというのが現状です。","id":"exchange-035"},{"speaker":"浅野委員","kind":"質問・要望","question":"私どもから１点だけ。このように思っておりますけれども、無理だというふうに言われるかもしれませんけれども、答弁だけほしいと求めました。","respondent":"村尾教育総合支援センター長","answer":"委員おっしゃるとおり、さまざまな部分で小学校にもヘルメットという声は毎年聞かせていただいているところです。小学校については、実際にやっぱり子どもたちのこれからの安全の部分を考えて、１つの研究材料という部分でご理解いただければと思います。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"防犯カメラシステムのところなのですけれども、Ａ３の資料を見せていただいて、単純に丸の大きさというのは、通学路の大きさの違いなのですか。理由を教えていただきたいのと、この小学校区の中で網羅されているのかどうかということが１点と、その点を説明するよう求めました。","respondent":"品川庶務課長","answer":"丸の大きさですけれども、この点から説明したほうがいいかと思うのですけれども、カメラの位置につきましては、学校で決めて設置をしています。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"コストのところをお伺いしたいのですが、２分の１補助とか、区の負担はどれくらいかかっているのかをわかりやすく教えてください。このシステムが利用されたというか、チェックが必要になったケースがあったかどうかも説明を求めました。","respondent":"品川庶務課長","answer":"そのうちの半分は東京都になりますので、仮に５台設置するとすれば、導入コストとしては１００万円ぐらいというふうになります。使用された経過なのですけれども、ざっと２件ほど、警察のほうから事件関係で見せてほしいというような要望があって見せているような状況があります。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"その２件というのは、責任者の校長先生の判断ということで許可をされたのか尋ねました。","respondent":"品川庶務課長","answer":"運用基準にのっとりまして校長判断という形で公開しているものです。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特別にそういった指導があるのかどうかを１つ教えていただきたいのと、保護者の引き取り訓練というのは、年間に１回ぐらいあるのでしたか。これは幼稚園と保育園のところも教えていただきたいのと、私立関係はどうなっているのか、区がかかわっている部分があるのどうかも説明を求めました。","respondent":"村尾教育総合支援センター長、竹田保育課長","answer":"夏季休業中の生活指導についてということで、事前指導を各教室で行うようにということで、犯罪被害防止等さまざまな部分について指導をしています。２番目の引き渡し訓練につきましては、９月１日に大体基本的には行っているのが現状で… 園児名、園児との関係等を言ってもらうことによって、引き取り訓練として実施しています。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"「３.１１を忘れない」とか、こういうものもぜひ見せていただきたいと思うのですが、どこかでいただけるでしょうか。資料要求になるかもしれないのですが。","respondent":"村尾教育総合支援センター長、竹田保育課長","answer":"センターのほうに１部か２部くらいは予備があるぐらいの話なので、センターに来ていただければ、お見せすることはできると思います。 幼稚園による共通の「震災対策マニュアル」と、それから、各園ごとに設定したものと２種類あります。保育課のほうにありますので、お越しいただければご覧いただける状況です。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そのうちぜひ見せてほしいと求めました。(2)の（ア）のところに、対策とか、大丈夫なのかどうか説明を求めました。","respondent":"竹田保育課長","answer":"津波が想定される園として考えておりますのは、標高の低いところを考えておりまして、最も適切なところに直ちに避難するようにということで考えているところです。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"地域の要望等があってこの場所に増やしてほしいみたいなものが、平成２８年度までで全校終了ですが、その後にも可能なのかということです。お伺いします。","respondent":"品川庶務課長、村尾教育総合支援センター長","answer":"確実にできないというようなわけでもありませんので、教育委員会内部でよく検討して、つける方向も考えられるというようなところです。ただ、もうその年でしっかり決めてやっているものですから… ２点目の浜川小学校、幼稚園の火災での対応につきましては、実際には小学校と幼稚園の対応が違っておりましたけれども。","id":"exchange-043"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この点については確実に確認しなければいけないことは、マニュアルというか、共通認識を持って日常の教育活動を行ってほしいと求めました。ぜひ検討して生かしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"大倉委員","kind":"質問","question":"ここが通学路で、通学路の安全を確保するための防犯カメラを設置していますよという、そういった看板の設置とかというのはあるのか尋ねました。","respondent":"品川庶務課長","answer":"現在のところ、防犯カメラを設置しているというような表記をいたしているということはございません。１つの犯罪の未然防止というか、そういう効果はありますので、そういう周知方法については少し考えていきたいと思います。","id":"exchange-045"},{"speaker":"大倉委員","kind":"意見","question":"少し検討というか、考えていただいて、子どもたちがより安全に通学できる道路の確保をお願いしたいと思います。１週間程度でいいのかとちょっと思ったので、その辺はどういうふうにお考えになっているのかというところを少しお聞かせほしいと求めました。","respondent":"品川庶務課長","answer":"１週間程度というところについては、これもどこまでにすればいいかというのは、考えるときりがないというところがあると思います。コストもかなりかかってくるというあたりも考えると、大体１週間程度だろうというような判断で、このように進めているという状況です。","id":"exchange-046"},{"speaker":"大倉委員","kind":"確認","question":"コストも大変大事なのですが、その期間が１週間であれば、ある程度、子どもたちに何かあったときにもすぐ対応できるという部分では大丈夫だということでいいのかの確認だけお願いします。","respondent":"品川庶務課長","answer":"基本的に防犯カメラを設置するというのは、犯罪の未然防止というところでの効果が非常に高いというところがあると思います。１週間がいいかどうかというのはいろいろ議論があると思いますけれども、保存できるＳＤカードで、１週間程度というようなところです。","id":"exchange-047"},{"speaker":"大倉委員","kind":"質問・要望","question":"月１回、これは避難訓練ですよというような訓練をされているのかどうかと、そういったときの対応はどうなっているのか教えていただきたい。そこまで想定してやっているかどうかということです。","respondent":"竹田保育課長","answer":"園長が不在時ということも十分考えられますので、現在いる職員の中で対応できることというような内容の訓練も実施しています。それから、抜き打ち訓練も実施しています。","id":"exchange-048"},{"speaker":"大倉委員","kind":"質問・要望","question":"さまざまな場面を想定して子どもたちの安全を守っていただいているということで理解しました。これはどういうふうにやっていますかという、どういった連携、防犯とかの部分で何か話がされているのかというところは教えていただきたい。","respondent":"竹田保育課長","answer":"なかなか防災というのは答えがあってないような非常に難しい分野ですので、情報交換しながら準備を高めていきたいと考えています。指導検査などや立ち入りなどの際にも、適宜、情報共有していきたいと考えています。","id":"exchange-049"},{"speaker":"大倉委員","kind":"質問","question":"防犯・防災、品川区のこういうものもいいですよとかということに対するお知らせとかもできればいいのかなと思って質問させていただきました。ぜひ情報交換をうまくやりながら取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"伊藤副委員長","kind":"質問","question":"まとめて聞きますけれども、カメラシステムのほうは、カメラ映像の保存先がモニター画面があって、各学校にあるのでしょうかというのが１点。平成２８年が７校という順番になっていますけれども、この順番の意味づけは何なのでしょうかという、その２つをまず説明を求めました。","respondent":"品川庶務課長","answer":"平成２８年度につきましては、基本的には当初は設置希望を出していなかった学校が平成２８年度に回っているというようなことです。カメラに直接つけているＳＤカード、これのみですので、モニターのほうは基本的には設置してございません。","id":"exchange-051"},{"speaker":"伊藤副委員長","kind":"確認","question":"要は、そうすると、当該のカメラの情報を出すためには、わざわざそこに上って、ＳＤカードを取り出さなければいけないわけなのですか。そうすると、お金がかかるのだろうから簡単に言えないのかもしれないけれども、それを品川区はどうお考えなのですかということを確認したい。","respondent":"品川庶務課長","answer":"モニターを例えば学校に全部設置するとか、そういうところの費用面を考えると、どうなのかという点が一番議論の対象になるかと思います。","id":"exchange-052"},{"speaker":"伊藤副委員長","kind":"質問","question":"２３区全部そうだし、東京都全体もそうなのでしょうから、児童も生徒も。各区が独自に負担していくということよりは、共通の財源を担保していくべきと思うのですが、答えをいただけますか。","respondent":"品川庶務課長","answer":"これ、財調算定になるかどうかという点につきましては、去年から始めている事業というところもありますので、その辺でまだまだ入っていないという状況であると思いますが、機会があるときに東京都には声を上げていこうかと考えております。","id":"exchange-053"},{"speaker":"伊藤副委員長","kind":"質問","question":"ですから、例えば３日分の水・食糧、そんなことのお考えはどうでしょうかということが１点。徹底はどうなんでしょうかということと、中学校にポンプを配備して、震災のときに担い手まで検討しているわけでしょう。","respondent":"竹田保育課長、村尾教育総合支援センター長","answer":"ただ、園もスペースの制約がありますので、その制約の範囲内で十分工夫していきたいと考えています。火の元というのは複数いろいろなところが考えられますので… 年齢また学年に応じて、もちろんさまざまな対応の仕方を教えていかなければいけないということは十分考えているところです。２点目、今、現状の部分かというふうに考えています。","id":"exchange-054"},{"speaker":"伊藤副委員長","kind":"質問","question":"外出のときにはこうだ、外出をした際にはこうするべきですよぐらいのことは、品川区独自の教育でもやってもいいのではないでしょうか。いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"子どもたち一人一人が適切な判断と行動ができるというのは、まさに防災教育の一番中心の部分だというふうに思っています。指導は今以上に進めていこうというふうに思っておりますし、防災というだけではなくて、繰り返し指導はしていきたいと考えているところです。","id":"exchange-055"},{"speaker":"大倉委員","kind":"質問・要望","question":"わかりにくいような、すぐ発見できるようなところに設置しないでいただきたいということだけつけ加えてお願いしたいと思います。まさに表示看板なのかと、先ほど教えていただいて、これはどういうことかと思って、１個だけ説明を求めました。","respondent":"品川庶務課長","answer":"その辺が、すみません、把握できていません。申しわけございません。","id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/184577?Template=document&Id=4862#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":43238,"voices":146}},{"id":"h27-20150824-5","meetingId":"h27-cm08","date":"2015年8月24日","dateIso":"2015-08-24","committee":"総務委員会","time":"午後 １時００分～午後 ４時５１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"品川区総合戦略の策定","agenda":"品川区総合戦略の策定","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"前回伺いましたけれども、今回の策定委員会の諮問文、これらがどういうふうになったのかご報告ほしいと求めました。その辺、議会との関係について、位置づけを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"基本的には長期基本計画から派生するといいますか、長期基本計画と実施計画の間ぐらいといいますか、実施計画に近いような中身になるです。より実施計画に近い内容というところがありますので、そういった形で意見を反映させていければというふうに思っているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"資料No.７の次のページですか、こうした変化を捉えて考えるべき行政需要というのは、どういったものを考えていらっしゃるのか。考え方も含めてなのでしょうか、区の考えを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"平成６７年まで伸び続けるというような推計でございましたので、さらに今後も高齢化に対する対応というのはどんどん必要なのであろうです。これは０歳から１４歳ですので、どういった形で進めていくのかというのは、今後もさらに検討が必要だろうというふうに思ってあります。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう方向で見直しや改定や、また分析をしていこうと考えているのか、そこのお考えを伺いたいと思います。率直に伺いたいのですけれども、５０年後と言われたときに、どういう状況になっているのか。","respondent":"柏原企画調整課長","answer":"基本なデータであることは間違いありませんので、例えば高齢者の施策、検討はさらに深めなくてはいけないだろうというふうに思ってあります。一つ、行政が施策を進める上で、タイミングを見ながら何回も続けてやっていかなくてはいけないだろうというふうには思ってあります。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"ですから、私の言いたいのは意見ということで、今から必要な特養ホームなど社会資本の整備を計画的に進めていくことが必要だと思います。今後、策定委員会で進めていくということなので、それぞれ質問や、また意見を述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"ケーブルテレビ等の活用によりしっかりＰＲを進めていくとあるのですが、ほとんどの人、ケーブルテレビというのは見ていないのではないですか。その辺もどういうことを言われているのか、簡単で結構なので、説明を求めました。","respondent":"柏原企画調整課長","answer":"それを受ける形でこの委員の方がおっしゃったのは、東京の場合は連携が必要なのではないかという意味合いでおっしゃっているのだろうと思います。これは前段のところで言った、例えば商店街であるとか地域との連携というのが、そういったご趣旨であろうかと思います。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"勤労生活圏ですか、さらに住宅環境、これもどんどん供給されていく。方向性として別の方向に持っていったほうがいいのではないかと思いますので、より環境の整備ですか、そういうほうにぜひ努めていただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"本多委員","kind":"意見","question":"１点だけお聞かせください。この資料No.８の２ページ、そういう視点ではどういうふうな見解をお持ちか、そのこと１点だけ説明を求めました。","respondent":"柏原企画調整課長","answer":"特別区の連携プロジェクトというものが動き出しましたので、事業連携をしたりだとかという、いい面があるような形で進めていければと。民民もあるでしょうし、いろいろな形があろうかと思いますので、いろいろな窓口を見ながら進めていくべきだろうというふうに思ってあります。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"８月５日の策定委員会ということで、１２団体ということで絞られているのですけれども、当初どのぐらいの団体数からこれだけ絞り込んでいったのか。本来であれば入るべきではないかとは思うのですけれども、それら３点に対する考え方、後者２つに関しては考え方を説明するよう求めました。","respondent":"柏原企画調整課長","answer":"これは幅広い分野で検討が必要だということで、考え方としては、これくらいの人数ではないかというふうには思ってあります。例えばその分野についても、委員長・副委員長のほうの学識の経験であるとか知見とか、そういったところでご意見をいただければというような形です。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"でも、言いにくいかもしれないですけれども、そんな感じで考えてよろしいのでしょうか。それから、品川区がこれまでつくってきた長期的な計画と今回の総合戦略というものの関係を整理していただいてよろしいか尋ねました。","respondent":"柏原企画調整課長","answer":"品川区の場合、これはでも品川区としても長期基本計画でも入っている内容ですので、取り組まなければいけない重大な課題だというところがあります。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"これを答申の中でまとめていくわけですけれども、どのくらいのボリュームを考えていらっしゃるのでしょうか。どういった分野でどのくらいのボリュームでまとめていくというのは、この段階で言いにくいかもしれませんけれども、イメージがあれば。","respondent":"柏原企画調整課長","answer":"まだ今は検討しているところなので具体的にはあれなのですが、実施計画が今、今はそういった形で検討しているものです。","id":"exchange-010"},{"speaker":"あくつ副委員長","kind":"質問","question":"2)地方への新しいひとの流れをつくる、今、策定中ということですよね。これに対して何か都との調整というか、そういったものの場があるのかどうか、そこだけ尋ねました。","respondent":"柏原企画調整課長","answer":"当然そのエリアに入っている品川区としましては、分野についてその整合を図るということはしていきたいと思います。ただ、東京都のほうから、こうしなさいとかということではありませんので、お互い自主的に調整を図りながらということになると思います。","id":"exchange-011"}]},{"id":"topic-02","title":"平成２７年度都区財政調整交付金当初算定結果","agenda":"平成２７年度都区財政調整交付金当初算定結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"去年も聞いたのですけれども、区の評価を伺いたいということがまず１つです。２ページの前年からすると２４％増えているということですけれども、また特徴となる経費だったり、そういうところをご説明ほしいと求めました。","respondent":"秋山財政課長","answer":"２３区全体でこういうような話ということでございまして、投資的経費であると、改築関係の経費が投資的経費では多いというのがあるかと思います。額は別として、あと通学路の防犯カメラの整備費とか、この辺が今年度から新たに新規の算定となったというものです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"新規の算定はわかったのですけれども、逆になくなってしまったものというのはあるのか尋ねました。","respondent":"秋山財政課長","answer":"見直し全体で１５項目という中でその中でも増減がありますので、その分の算定する金額が下がっていくというような、そういう趣旨で入っているものが幾つかあります。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"聞き落としたのだったら、ごめんなさい。これはどのくらいの減収になったのかという試算が、全体、あるいは品川区分だけでも教えてほしいと求めました。","respondent":"秋山財政課長","answer":"平成３０年度以降が８４０億円で、平成３１年度が１,２００億円というふうに、一応試算をしてはいるところです。２３区全体ですので、品川区ですと、１０％内外ということですね、そのぐらいということになります。","id":"exchange-014"},{"speaker":"あべ委員","kind":"質問","question":"２３区でも、自治体によってはホームページを開くといきなり反対みたいなのが出ていた時期もありましたけれども、今、どうなっているのでしょうか。品川区ないし区長会なり、何か動きがあれば説明を求めました。","respondent":"秋山財政課長、桑村副区長","answer":"そこには同意することはできませんので、これがストレートにかかるというわけではないのですけれども、その辺は見ていきたいです。地方との連携、全国連携とかというところで… ただ、それだけではなかなか難しいので、東京都にはこれだけの需要があって、現実にはお金がなかなか足りないのだという主張。","id":"exchange-015"},{"speaker":"あべ委員","kind":"質問・要望","question":"これはぜひ引き続きやってほしいと求めましたが、関心がないというより、知らないというのが現状だと思います。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-03","title":"品川区シティプロモーション キャッチコピーの選考状況","agenda":"品川区シティプロモーション キャッチコピーの選考状況","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"区内の方が１５％ということは、品川区についてのキャッチコピーを求めて、なぜなのだろうと。これは結果論ではあるものの、区はどんなふうに分析されているのかを伺いたいと思います。","respondent":"中山企画部長","answer":"先ほど見込みという話がありましたけれども、平成２７年度は、この予算に基づいた執行が図られていくものというふうに考えております。訪れてもらい、いずれは住んでもらえればという願いの中でやっていくということを考えると、ある意味では良かったというふうに考えています。","id":"exchange-017"},{"speaker":"あべ委員","kind":"質問","question":"これ、選考基準というのはどんな感じだったのか尋ねました。","respondent":"中山企画部長","answer":"」というのを、短いキーワードでわかりやすくＰＲしていただきたいということで募集をしたものです。最大２０文字以内で、それから活用しやすいものを選んでくださいということで、委員にお願いしたということです。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"先ほどの、多くの地域から関心を寄せていただいたというのは確かにいいことだと思うのですけれども、区内在住の方の９９件というのが、もともとそういう募集をかけたときのもくろみとして結果はどう評価されるのか尋ねました。","respondent":"中山企画部長","answer":"まずは１００件ぐらいは来てもらえればというふうに思っておりまして、区内からの応募が１００件というのは、これを機にやっていきたい。ですから、こうやって応募していただいた方々への何らかの選考を踏まえた対応も考えていきたいと考えています。","id":"exchange-019"},{"speaker":"あくつ副委員長","kind":"質問","question":"周知方法の(4)の公募サイト（ホームページ）への掲載というのは、この辺がやっぱり一番大きかったのかと思い、その点だけ。どのようなサイトだったのか、また、その辺の分析というか、そういうことでよかったのかどうかという点を伺います。","respondent":"中山企画部長","answer":"そこを使ってみようという職員のアイデアから出したところ、確かに大多数はそこからの、ネット経由での応募であったです。","id":"exchange-020"}]},{"id":"topic-04","title":"大井五丁目外下水道管路耐震化工事請負契約","agenda":"大井五丁目外下水道管路耐震化工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"率直なところ、柔軟な構造にすることによって、耐震化というふうに一言で書かれていますけれども、大体どれくらいの震度というか、そこら辺までは耐えられるということを想定した工事なのか、それだけ説明を求めました。","respondent":"立川経理課長","answer":"基本的には地下ですので、地上の揺れとはかなり違うということでございまして、震度７程度には耐えられるというふうに聞いてあります。","id":"exchange-021"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"端的に教えていただきたいのですけれども、ここ２カ所を、これだけ説明を求めました。","respondent":"立川経理課長","answer":"既に２６カ所終わっておりまして、１０番の品川自動車営業所、これは東京都交通局のバスの営業所です。は公共施設等、その辺を選定して実施しているということで、対象になっているというふうに聞いているところです。","id":"exchange-022"}]},{"id":"topic-05","title":"西五反田二丁目付近下水道管路耐震化工事請負契約","agenda":"西五反田二丁目付近下水道管路耐震化工事請負契約","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"この工事の進め方は前のものも含めてお伺いしたいのですけれども、拠点で１カ所１カ所、後半のほうは面的にやっていくわけですよね。あるいは、どういう感じで、点で工事するものと面で工事するものを分けるようにしたのか、説明を求めました。","respondent":"立川経理課長","answer":"面的に全て工事するというような考え方でございまして、先ほどご説明したところは、面的にそこの地域については重要なマンホールについては全て実施するというふうに聞いているところです。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問","question":"面的にやれば、例えば西五反田二丁目のこの斜線エリアであれば、全てのマンホールが耐震化が終了したということになるのでしょうか。あるいは周りができているけれども、ここだけ残ってしまっている、そういうことはないと思うのですけれども、その辺りはどうなんか尋ねました。","respondent":"立川経理課長","answer":"いわゆる地区内残留地区ですと、避難を要しない地域ということになっておりますので、その地域の方々は避難をしなくていいということになります。各拠点施設ですので、ここはいわゆる避難施設になるということで、重点的に先に耐震化を実施していくというものです。","id":"exchange-024"}]},{"id":"topic-06","title":"品川区における「ふるさと納税（寄附金）」の取り組み","agenda":"品川区における「ふるさと納税（寄附金）」の取り組み","exchanges":[{"speaker":"あくつ副委員長","kind":"質問・要望","question":"こういうスキームが可能なのかどうかというところで伺いたいのですが、非常に今、注目を集めているというところもあります。これは一つの意見になりますけれども、こういったことも今後検討課題にしていただけるかどうかというところで伺えればと思います。","respondent":"黒田税務課長","answer":"品川区に対する応援としてご案内したいというふうに考えてありますので、その中で、そういったような進め方もあるのかというふうに考えてあります。","id":"exchange-025"},{"speaker":"あべ委員","kind":"質問・要望","question":"そこら辺は、品川区としてはどのように対応されるのでしょうか。領収書だけか尋ねました。","respondent":"黒田税務課長","answer":"まず寄附の募集の出発点にしたいというふうに考えておりまして、その中で、また様々な展開があろうかというふうに考えてあります。寄附いただいた方に、ワンストップ特例制度、なるだけ応援される方に負担のかからない方法を考えてまいりたいというふうに考えてあります。","id":"exchange-026"},{"speaker":"あべ委員","kind":"意見","question":"だから、人の思いが具体的に形になるような方向というのは、私はむしろ寄附する方の思いに沿っているのではないかと思います。今後も検討してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"もう少し品川区のここを応援してほしいというのを具体的に示さないと、そもそものふるさと納税の発端の、そこを考えていただきたい。意見ですけれども、それに対して何かお考えがあれば伺いたいと思います。","respondent":"黒田税務課長","answer":"品川区、こういうことをやっているということを案内パンフレットの中でご紹介しようと思っているのですが、品川区をぜひ応援していただきたいというところをＰＲしていきたいというふうに考えてあります。","id":"exchange-028"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"ちょっと時間も押しているところ、あれですけれども、１点だけ伺いたいと思います。伺いたいことは、どういう基準なのか伺いたいのと、判断を伺いたいと思います。","respondent":"江部総務課長","answer":"１つは、申請団体と区との関係、どのようなこれまでの関係があったかという点。今、安全保障ということでまさに議論をされていることを地域の方にお伝えいただけるという報告会という認識で、後援を出したというものです。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"基準は何かということなので、名義申請というのですか、名義貸し付けというのでしょうか、区が判断する基準は何か。区がこれを応援する、いわゆる後援をするということはなぜなのか、その理由を改めて伺いたいと思います。","respondent":"江部総務課長","answer":"ルールにつきましては、特に要綱等で決めているものではございませんで、庁内で総務課からの通知ということで、全庁に指示をしているものです。公益性があるか、あくまでも国政で議論されている安全保障の講演会ですので… お手元の最後の大井競馬場視察資料に基づきまして、簡単にご説明いたします。それから、平成１５年に、我々がよく使いますＬ－ＷＩＮＧという１号スタンドが運営を開始したものです。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858739?Template=document&Id=2024#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":40672,"voices":96}},{"id":"h27-20150825-14","meetingId":"h27-cm08","date":"2015年8月25日","dateIso":"2015-08-25","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"国家戦略特区に関すること","agenda":"国家戦略特区に関すること","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"まず認可保育園の件で、これは国に対する国家戦略特区ということで、認可保育園のほうの基準の緩和を求めていってはどうかというのがあります。とりあえずその４点です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"沢田委員","kind":"提案","question":"これは他区の提案でも出ていましたけれども、これもぜひ品川区もこれから水辺の開発を進めていく中で、必ずやっていけたらなということです。すみません、一つ言い忘れましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"新妻委員","kind":"提案","question":"水辺の観光ルートの開拓という追加提案事業にも入っておりますが、人が集まったときに休憩場所として提供できるような、この運河の中にそういう場所をつくっていくような提案をさせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"松永委員","kind":"提案","question":"今、大井町近辺においてもホテルがなかなかとれないということで、空き家を活用してショートステイ型のホテルにしてみてはいかがかなということを提案させてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"安藤委員","kind":"提案","question":"２つ目のやめるべきという提案なのですけれども、グローバル企業等に対する雇用条件の整備という項目があります。それと、これまでの議論も最低基準をどう上げるかということの議論の積み重ねで、その二方向の緩和というのも出てきたわけですからとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"のだて委員","kind":"提案","question":"古くなった商店街のアーケードが、これを使って何とかこのアーケードの建替えができるのではないかと思いますので、提案したいと思います。容積率の緩和や働くルールの破壊は、安藤委員が言ったとおりやるべきではないと思いますので、これも提案しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"例えば１,０００万円あったら、もうそれを５０で簡単に割っても１０年分といったらたかが知れているから、その分を返さなくてはならないですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"大倉委員","kind":"質問","question":"ちょっと質問でもいいですか。今、品川区内にもかなり民泊施設というのが紹介されていたりするのですが、区としては何かそれを把握されているのか尋ねました。","respondent":"柏原企画調整課長","answer":"そういう意味では、専門の部隊ではないので詳細な情報はちょっとわからないのですが、詳細なところまで多分押さえていないのではないかと思います。そういった中で個人でというところまでは、細かい数字までは押さえていないのではというような気がします。","id":"exchange-008"},{"speaker":"大倉委員","kind":"提案","question":"そういうのができるような、制度なのか条例なのかわからないですけれども、そういったところも少し考えるのはどうかという提案、それが１点です。私たちもぜひ進めていっていただきたいと思っていますので、その３点、お願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"たけうち委員","kind":"意見","question":"保育士までいくかどうかわからないですけれども、既に品川区の社会福祉法人でも独自に法人で外国人の研修等をやっているらしいですけれども、それが今後どういう形でできるのかというのを勉強してみたいですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]},{"id":"topic-02","title":"羽田空港の機能強化に関すること","agenda":"羽田空港の機能強化に関すること","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"つまり、影響があるかということを、これが果たして今の品川区の現況の中では正しいかどうかということについてはわからないわけじゃないですか。品川区としてとるべきものというのは、やはりこういう来るべきことが、改めてお答えをお願いいたします。","respondent":"三ツ橋環境課長","answer":"委員のおっしゃるように、まずは環境の騒音や振動を測定するという騒音コンターにつきまして、検討をしなければならないと考えています。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問・要望","question":"けれども、３６万人の多くの方々に影響を及ぼすこの事業について、様々な対応をしていくべきだと思うのです。だから、そのことについてはもう少しお話をほしいと求めました。","respondent":"三ツ橋環境課長","answer":"この南風案２で参りますと、区民の皆様の声も、このオープンハウスの説明会におきましてもいろいろな様々な不安の声などいろいろあります。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、できるかできないかは別問題として、客観的にデータを把握していくぐらいを品川区としてはやはりお願いするべきではないでしょうか。やはりそういうふうに話を深めていかないと、地方自治体としては非常に頑張ってほしいと思いますので、改めてお答えをお願いいたします。","respondent":"三ツ橋環境課長","answer":"実際に品川区といたしましても、非常に気をつけなければ、本当に慎重にいかなければならない問題だと考えています。区民にとって騒音の影響が非常に及ぼされることが考えられますので、要望はしていくことなどの検討を踏まえ、いろいろ考えていきたいと思います。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問","question":"品川区の例えば八潮三丁目あたりがＷ値７０ぐらいになると推測をされるのですけれども、やはりこれはもっとわかりやすいものが欲しいです。それからＷ値６５等々のデータがあると、そういう資料の要請をお願いしたいのですが、いかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"私どももこの図しかもらっておりませんで、実際に国土交通省に対してはもっと詳細な部分を、実際に南風案２が採用される場合の詳細な図につきまして要望をしてまいります。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"提案","question":"提案させていただいたこの騒音の影響の表でも、これだけ見ると、何らかの意図があるのではないかと推測もしてしまうわけじゃないですか。でも、やはりそれについては、大田区とも連携をとった上でしっかりと要望してくださいということを最後にお願いしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"塚本委員","kind":"確認","question":"３ページに緑の線と青の線ということで引かれていますけれども、緑の線が概ねＷ値７０以上というのは、これはいわゆるデシベルとは違うのですか。大井町で７６から８０デシベルとなっていて、これと単純に比較してはいけないものなのかどうか、ちょっと確認したいのですけれども。","respondent":"三ツ橋環境課長","answer":"こちらのＷ値につきましては、デシベルです。これは１日２４時間を平均し、単発の値がたとえ一瞬で８０デシベル出てしまったからといって、こちらのエリアになるということではございません。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問・要望","question":"我々議会としてこれまでいろいろと検討してきたというところでは、やはりしっかりとお伝えしていただきたいと思うところがありますが、どうか尋ねました。","respondent":"三ツ橋環境課長","answer":"実際に今、品川区の上空をこの状態で、飛んでいない状態ですので、これが実際にこの南風案２になってしまうと飛ぶわけです。たとえ４時間の間だとしても、騒音影響はかなり受けるということが考えられますので、確認はずっとしてまいりたいと考えています。","id":"exchange-017"},{"speaker":"塚本委員","kind":"意見","question":"それだからという話ではなかなかやはりちょっと難しいのかなという思いが非常にいたしますので、こういう考え方で説明するというのはちょっとやはり無理があるかなと思いますので、その辺はよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"安藤委員","kind":"確認","question":"事実関係の確認として、緑の範囲と青の範囲それぞれで、学校、病院、保育園、幼稚園などが存在するのか、あと住宅はどれぐらいあるのか、お伺いします。","respondent":"三ツ橋環境課長","answer":"実際、こちらの緑の部分、また青の部分につきましては、ご覧いただきますとわかりますように商業地域でございまして、品川区の部分につきましては住宅等はございません。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"それは昭和４０年代の、そうしたかつての住民の方から伺う補償というのは、どのような枠組みによるどのような内容のものだったのか。もう少し具体的に言いますと、誰がどのような財源で行っている補償なのか、それを教えていただけますか尋ねました。","respondent":"三ツ橋環境課長","answer":"こちら巡回検診や学校へのものですけれども、まずは今現在のところにおきましては、巡回検診は実際に空港環境整備協会の助成でやっております。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"現在大井第一地区管内で、年齢を問わず、お子さんまで受けられる健康診断制度が継続しているという話も聞いたのですね。地域の活性化ということでお祭りなどへの資金援助などもあると伺ったのですが、そこら辺、もう少し区内の現状をお伺いしたいのですけれども。","respondent":"三ツ橋環境課長","answer":"品川区内に限らせてお答えしますけれども、今実際に委員がおっしゃられたように、巡回検診につきましては大井の地区を対象としております。こちらは空港環境整備協会が範囲を決めておりますので、区が要望とか、そういう部分ではございません。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"ご説明をいただきましたけれども、こうした補償制度を十分だと考えているのか、お伺いしたいと思います。これはどういうことなのか、国に求めているところがあるのか、お答えほしいと求めました。","respondent":"三ツ橋環境課長、中村都市計画課長","answer":"こちらの補償につきましては、実際いろいろなことが考えられると思いますので、今現在のところはこの補償は空港環境整備協会の補償。実際に近隣区と連携をしながらという部分につきましては、４区で連携をしながら… オープンハウスの説明会も行いまして、区民に対する説明を求めてきたものに対して、そうやって説明会を行っていただいたということもあります。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"ですから、現在、これはその後どうなったのかというのをお伺いしたかったのです。そこら辺はどうか尋ねました。","respondent":"三ツ橋環境課長","answer":"今のところ補償につきましては特に、実際には今の空港環境整備協会の部分ですけれども、それ以外は今のところはございません。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"落下物による事故の場合ですとか、万が一の墜落事故の際の補償というのは現状どうなっているのか。誰が行ってどのような規模の補償が行われたかなど、過去の実績があれば教えてほしいと求めました。","respondent":"三ツ橋環境課長","answer":"落下物に関しましては、まずは航空事業者が対応しなければならないことになっております。国は管制官などもきちんと点検し、整備などもしていくです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"品川区としては、この騒音対策という点で、この南風案１についてどのように評価しているのでしょうか。もっと言えば、国が今進めようという南風案２と、南風案１、どちらがよいと品川区としては認識しているのか、お伺いします。","respondent":"中村都市計画課長","answer":"この南風案１では品川区上空を通過しないですけれども、ただ、他の自治体のほうに今度は影響が出てくるというような案だと認識しております。この南風案１では十分に満たされないという見解があって、南風案２を進めたいと、国が言っているです。","id":"exchange-025"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"それはゼロが１になるというのは必ずそういうことがあるわけで、だから議会としてお願いをしてその対策を練ってほしいと言っているわけで。区民の方々に変な不安を余計に与えてしまうようなことにもなりかねないから、そこら辺は整理をしてもう一回答弁してほしいとの意見を述べました。","respondent":"中山企画部長","answer":"環境課長がお答えしたのは、国の法に基づくものについては、今、この表に基づいてやれば、品川区には対象となる地域がありません。説明も丁寧にやってもらう、制度的なものはそういう認識の上で、できる限りのことはまた区としてやっていくという意味で答えたものです。","id":"exchange-026"},{"speaker":"のだて委員","kind":"確認","question":"確認なのですけれども、もう一度その７０デシベルでいいということなのかという確認と、形でやられたのか説明を求めました。","respondent":"三ツ橋環境課長、中村都市計画課長","answer":"Ｗ値につきましてはデシベルです。二重サッシにつきましては、昔、小学校などに対して、国が補助を出していたことを指しております。 ただ、このＬｄｅｎの場合は１日のうちの平均ということで、単位は同じデシベルでも計算の上で算出した数値です。","id":"exchange-027"},{"speaker":"のだて委員","kind":"意見","question":"単純に比較して７０デシベルで同じものにならないということだと思います。今回は法内の国による補償はないということでよいか、改めてお答えほしいと求めました。","respondent":"三ツ橋環境課長","answer":"実際、こちらの３ページでご覧いただけますように、概ねＷ値７０のところに対しましても品川区の部分には入っていないですので、法律に関しまして規制対象外となっております。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"２ページの基準についてなのですけれども、人の健康の保護に資する」とありますが、区はどのように捉えているのでしょうか。今回のこの計画で、品川区民の生活環境が崩されるという認識はあるのか尋ねました。","respondent":"三ツ橋環境課長","answer":"騒音がない状態で、実際に騒音がある可能性が出てくるですので、影響はあると考えております。しかしながら、国のこの基準の規制値がありますので、先ほどの騒音コンターに基づきますと規制値の対象外となると考えております。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"今回のこの計画では午後３時から午後７時までの４時間に品川区の上空を飛ぶということで、やはり当然数値は下がってしまうということになります。この数値を利用することは実態を反映していないと思っているのですけれども、お考えはどうか尋ねました。","respondent":"三ツ橋環境課長","answer":"１年間のことを勘案されましてこの騒音予測コンターが出され、実際問題として４時間は影響を受けるというこの騒音につきましては、実際問題としてこの騒音コンターには当たらないという現状があるという認識はしております。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほども、やはり住民の生活を守っていくために、以前は二重サッシとか国の補償が出ていたということなので、しっかりと区も重大な問題だと認識しているというお話でしたので、国に対して対策を求めていく、あるいは区として対策できるように考えていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"たけうち委員","kind":"質問","question":"先ほどは１回モデルで飛ばせられればと言っていましたけれども、ちょっとできないと言っていましたね。じゃあそうはいっても、大体３００ｍとか４５０ｍで真上を飛ぶのが、そういうのを調べてそこで測るというのは考えたりされているのか尋ねました。","respondent":"三ツ橋環境課長","answer":"今回のオープンハウス説明会におきましては、要望しますと、また映像なども小さいものでしたけれども実際に見られました。９月５日も同様のものだと思いますので、一応そのような状況の疑似的体験はできるとは思います。","id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問・要望","question":"シミュレーションだけで出すのか、何かどういうふうに考えているのかと思ったので、今後しっかりそれを有効に活用してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"全て環境課長にこういう要望ですとか、要望を全部上げてくださいというのはちょっとという思いが私はあるのですけれども。どういう態度というか、いわゆる国の国土交通省のお役人というのは、いわゆる一つの地方自治体の役人に対してどういう態度なのか尋ねました。","respondent":"中村都市計画課長","answer":"私たちは直接対応していただいている職員の皆さん方ですけれども、やはり国の事業として進めるに当たって、私どもが説明会を要望したり。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"区民の不安ということを少しでもということで意見書等を上げているわけですから、国策という意味で言うなら自民党の国会議員が出ているわけですね。せっかく副委員長等がいらっしゃるわけですから、私は無所属の議員ですからその辺はよくわかりませんけれども、その辺についてはどう思われますか。","respondent":"中村都市計画課長","answer":"説明会等も開催していただいているところですので、地域といいますのは地方自治体あるいはそこに住む区民の皆様に対して丁寧に進めていきたい。","id":"exchange-035"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"ここの中の３時間飛ばす中で、どうしたって区民の方々にどうやって説明をして、国土交通省にもやってくださいということです。やはりこういう話はこの委員会としてもやるべきだと思っていまして、それは後で委員長からしっかり話があると思いますが、今の現状だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"新妻委員","kind":"質問","question":"第１回約４６０名見えたということですが、この参加者の中の声、この声はまとめていただいておりますでしょうか。もしそれをまた教えていただければと思うのですが、いかがか尋ねました。","respondent":"三ツ橋環境課長","answer":"この声につきましては、今、集計中ということで、まだこちらの手元には届いておりませんけれども、いろいろ細かく集計はされているようですので、わかり次第、またお伝えしていきたいと考えています。","id":"exchange-037"},{"speaker":"伊藤委員","kind":"質問","question":"けれども、うまく調整をとっていただいて、実際に飛んでいるところの騒音を測定するということは非常にいい意味になるのではないでしょうか。様々な形での交渉事なり、次のステップにつなげていけると思うのだけれども、品川区のお考えを説明するよう求めました。","respondent":"三ツ橋環境課長","answer":"実際に測定して、例えば品川区の騒音コンターを測定するという考え方は非常にすばらしいと思います。実際、それを現状として国に挙げていく一つの要素ということは非常に大事だと思いますので、そちらに関しましては検討させていただきたいと思います。","id":"exchange-038"},{"speaker":"伊藤委員","kind":"質問","question":"例えば７７７とか、それから着陸なのかということも含めて、全部事前にわかるわけじゃないですか。それならば実際に飛んでいるところを測ったほうがいいのではないでしょうかということを検討を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/842551?Template=document&Id=5992#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":27758,"voices":82}},{"id":"h27-20150826-18","meetingId":"h27-cm08","date":"2015年8月26日","dateIso":"2015-08-26","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ３時０３分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"学校名は、その学校が主になって横断幕を作製したというふうに理解していいのでしょうか。括弧書きで卒業生となっているのは、学校主体というよりも学校の卒業生が主体というふうに読み取ってよろしいか尋ねました。","respondent":"池田スポーツ推進課長","answer":"今のご質問ですけれども、この表のところで、まず学校名と書いてあるところは、横断幕を掲示した学校ということで書かれてあります。内容につきましては委員のおっしゃったとおり、この学校が中心になっているチーム、もしくはこの学校を卒業した生徒ということになってあります。","id":"exchange-001"},{"speaker":"吉田委員","kind":"質問","question":"横断幕を作製した主体といいますか、そういう方たちがどこなのかと伺ったのですけど。","respondent":"池田スポーツ推進課長","answer":"失礼いたしました。こちらの顕彰につきましては、私ども区が作製いたしまして、学校に掲示しています。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"今の３ページの横断幕作製のところの資料なのですけれども、そのあたりのことの確認をしたいのと、それも教えてほしいと求めました。まちの１人として応援をしたいという気持ちになって、そのとおりだなと思って伺っていたのですけれども、ちょっと改めて伺いたいと思います。","respondent":"間部文化観光課長、池田スポーツ推進課長","answer":"私からはかがやき顕彰、横断幕の件で、私どもが所管している関係で私のほうから説明します。先ほど委員からご指摘もありましたけれども、皆さんから応援したりですとか… 多くの方が使う部分については大方進めさせていただいているところですけれども、近いうちにあそこの部分について改修をするということで、その部分についてもバリアフリーを進めていくということを担当の課長から話は聞いてあります。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"現役のところではどうなのかというのは、同じスポーツ振興という点で、もしわかったら教えていただきたいというのが一つです。どこまで手が届いて推進されているのかというのをこの際教えていただきたいと思って質問をした。","respondent":"間部文化観光課長、池田スポーツ推進課長","answer":"このかがやき顕彰に関する支援の関係ですけれども、よくある例で、やはり個人的な部分の参加費の公的な支援というのは。現状では私たち、将来的には検討課題だと思いますが、今現状では現行のまま行ってまいりたいと考えているところで… 次の学校についてですけれども、学校についても改修にあわせて、バリアフリーということで改修工事を行っているところです。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"いろいろな形でそういう施策が前進できるようにしていただきたいということを、この際要望しておきたいと思います。改めてその点について、ちょっと漠然としてしまっているのですけれども、考え方を伺っておきたいなと思います。","respondent":"池田スポーツ推進課長","answer":"障害者交流会につきましても、今回につきましては昨年１回しかやっていませんが、今年は２回やろうというふうなことも考えてあります。","id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"まず１点目が横断幕、そこを１点教えていただきたいのと、その辺区としてどのように把握をされているのか説明を求めました。","respondent":"間部文化観光課長、池田スポーツ推進課長","answer":"この制度自体は個人の申し出で申請があるものではありませんで、五年ぐらいまでは追っているのかなということで、余り大人になった方についての掲出というのは見られないというような状況です。 今年５月に大井ふ頭でデフサッカーリーグということで、そちらの際にろう者サッカー、耳の不自由な方ですね。ですから今後そういった障害をお持ちの方等とのつながりをつくるような努力はしていきたいと考えています。","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いないも含めて確認をしていただいて、ぜひそれは残り５年しかないですので、これをいい機会と捉えて進めていただければなと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"というのは、２点目の質問になりますが、まず区民スポーツ大会というくくりで参加人数の多い少ない、この傾向だとかはどう捉えているのか。この辺の状況を尋ねました。","respondent":"池田スポーツ推進課長、安藤文化スポーツ振興部長","answer":"大会の定員の考え方ですけれども、例えば春季大会の軟式野球が１２０となっていますが、これは明らかに定員があります。申し訳ございませんけれども、正しいものは把握しておりません。大会に出て１回戦で負けてしまう、私がいたころから、継続していかに大会に出て楽しんでもらうかということ自体を考えていることは考えているです。","id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問・要望","question":"これはぜひ要望があれば、要望に沿っていただけるのかどうかを知っていただきたいので、その辺コメントをいただきたいのが一つです。やはり準備段階、調査があって、実際直前３年でこうだとか、あるいはオリンピック過ぎてからも大事ですから、区の施策としては。","respondent":"池田スポーツ推進課長","answer":"こちらの三者が共同していろいろな事業を行っていこうというふうな考えを持ってありますので、今のところは考えてございません。健康で明るく長く住んでいける、いつでもどこでも楽しめるスポーツをつくるということが目標値であると思ってあります。","id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今この場で言わせていただいていて、その事務量ぐらいは何らかの支援が、行政主導でやったらどうですかという意味です。定員のところ、今答弁がなかったので、定員は設けないという中で、要望に沿っていくのだという確認したいと求めました。","respondent":"安藤文化スポーツ振興部長、池田スポーツ推進課長","answer":"区と大会開催をしていますので、また各連盟とか協会のほうにお話をさせていただきながら登録をして、しっかり把握に努めていきたいと考えています。私ども捉えていますので… 一つ漏れてございました。こちらについてはスポーツ協会と検討していきたいと思いますので、今後定員のあるものについてはまたいろいろと検討させていただいて。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問","question":"２８連盟、それ以外の多くの区民がどういうふうに日ごろスポーツに親しんでいる、どこかでわかるのでしょうか。そこを伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"そういったものが実際年何回あるかということと、それから何人参加したということでは、私どものほうで把握はさせていただいてあります。その結果をどこまでできるかなという、本当の競技についてやっている方たちの成績についてを状況としてご報告させていただいた次第です。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、この品川区民のスポーツ振興というのは、他区と比べてだったり、全国的に見たりする中で、どういう状況にあるのでしょうか。はこういった連盟数も多いとか、競技人口は多いんだというようなのは、他区との比較などはされていないのか尋ねました。","respondent":"池田スポーツ推進課長","answer":"各地区にスポレク推進委員会を設置いたしまして、スポーツを楽しめる環境づくりというものは、他区に比べて進めてやらせていただいてあります。ということで、区民のスポーツに対する関心というのは高く、そして実際にやっていると考えています。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私の周りではなかなかスポーツをしたくても、時間も場所も、そしてお金もないという状況があるということを伺ってきたので。増やしていっていただきたいなと思うのですけれども、そういったもっともっと親しんでいける場所をつくるという目標は、区にはあるのか尋ねました。","respondent":"安藤文化スポーツ振興部長","answer":"ですから、他地区との比較というのは何をもって比較するかというのは非常に難しいと考えます。実施率ですけれども、平成２２年の、皆さんでつくっていただきました品川区文化芸術・スポーツのまちづくり条例の折に調査をかけました。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひさらなる可能性を、一人ひとりが秘めている可能性をさらに出すためにも、多くの方がいつでもどこでも誰でもスポーツに親しめる場を、やはりこのオリンピック・パラリンピックを機会に拡大していっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問","question":"各競技の連盟にオリンピック・パラリンピックの強化とかの働きかけを行っていくのかということを３点目としてお聞きします。以上３点お願いいたします。","respondent":"間部文化観光課長、池田スポーツ推進課長","answer":"横断幕以外の顕彰ですけれども、例えば横断幕以外といいますと、区のホームページにおいてもあわせて顕彰を載せさせていただいているところです。それ以外はございません。スポーツ協会の下にあります各連盟、この三者でもって、これからのオリンピック・パラリンピックの気運醸成に向かってやっていきたいと考えています。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問・要望","question":"横断幕以外にもオリンピック・パラリンピックを盛り上げるような表彰制度とかあったらいいなと思います。これは要望として、ぜひよろしくお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"木村委員","kind":"質問","question":"パラリンピックの競技に携わる、携わるというのでしょうか、接するスタートという年齢ですね。中学生の子どもたちでも、大体幾つぐらいからこのようなパラリンピックを目指すような、そういう子どもたちが出てくるのかお聞きしたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そういった競技に取り組むことができるような環境にあるということもあるとは思いますので、いろいろなパターンがあるかと捉えてあります。たまたま品川区には、お子様から大人まで障害者スポーツへの理解を促進してまいりたいと考えています。","id":"exchange-017"},{"speaker":"木村委員","kind":"質問","question":"子どもたちに対するスポーツというものの触れ合いというのですか、触れる機会というのか、その点を教えてください。この違いというものは単純にどういうところから出てきているのか、もしそれがわかれば教えてほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長、池田スポーツ推進課長","answer":"今後パラリンピックについてはオリンピック・パラリンピック準備課としても重きを置いて普及活動に努めてまいりたいと思いますので、これからますますそういった環境づくりに努めて連携をして進めてまいりたいと考えています。盛り上がっているところですけれども、そういった景気の動向によっての企業のチームとかの形で、選手の質がちょっと変わった部分もあります。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問","question":"区民とスポーツ、そういったまとまった形で区民に紹介をする、また区外の方に発信をしていくということをやったことがあるのかどうか。この辺についての、今までやったことがあるのかということと、この辺のお考えについてお聞きしたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"そういう方々をお呼びして講演会をやったりだとか、また地元の方々と協力して呼んだりとか、そういう試みは今もやってあります。今後、そういう活動をたくさん捉えて、区民の皆さんにご紹介をさせていただきたいと考えています。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"意見","question":"特にオリンピック・パラリンピックというのはすごくいい機会だと思いますので、そういったものを今後発信をしていただく。ぜひまた工夫、検討のほうを私も考えていきたいと思いますし、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"渡部委員","kind":"質問・要望","question":"１点は、それはしっかりした団体がいらっしゃるわけですから、これはもう本当にくれぐれも要望しますというところなのですけれども。基本的に登録をされているでしょうから、粗々というか、しっかりと区のほうではこれを把握はできているわけですよね。","respondent":"池田スポーツ推進課長","answer":"いろいろなサークル紹介というようなページでは、いろいろな団体で掲載はさせていただいているところです。今後こういったサークルについて、どこで紹介できるかどうかということについては、研究のほうをさせていただきたいと思います。","id":"exchange-021"},{"speaker":"渡部委員","kind":"質問・要望","question":"今ご答弁でいただいた冊子なのですね。配布ができるようにしていただきたいなというのが１点、ホームページですとか、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/515238?Template=document&Id=6478#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":29003,"voices":58}},{"id":"h27-20150827-10","meetingId":"h27-cm08","date":"2015年8月27日","dateIso":"2015-08-27","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件整理しています。","topics":[{"id":"topic-01","title":"平成２８年度予算（議会費）","agenda":"平成２８年度予算（議会費）","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"議会開催中は、夏場はあの状態だと大変暑いということで、しっかりとエアコンを設置していただきたいという経費です。以上の６項目です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"つる委員","kind":"意見","question":"２点目が、控室電話機のナンバーディスプレイ化の拡充です。非常に大事な視点かなと思っているので、ぜひそれはお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"共産党としては７項目、要望をさせてほしいと求めました。それから７つ目として、当然それに求められる体制強化ということもありますし、体制強化をすることが必要ではないかと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問・要望","question":"これを、検討会での議論がスムーズにできるようにということで、予算要求を申しております。研修費をあらかじめ増額しておくことによって、スムーズに研修を進めていきたいという思いから、この２点を要望しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"世界各国の風習、風土、考え方も違うにあたって、我々地方議員が海外まで行って学ぶべきことではないのではないか。区議会では、海外調査費はなくすべきだというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]},{"id":"topic-02","title":"では、予定表の次にいきまして、(2)東京都後期高齢者医療広域連合議会の報告","agenda":"では、予定表の次にいきまして、(2)東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"本多委員","kind":"意見","question":"２７年度補正予算につきましては、補正額５１億７,２８５万２,０００円の議案が可決されたということで、結果が届いております。詳しくは、資料は事務局のほうにお預けしておりますので、ぜひ供覧してくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この保険料の具体的に案というふうなところが、いつごろ、広域連合のほうで出されるのかということがわかったら、１つ教えていただきたいのと。つかまれていてわかるとしたら、わかられているとしたら、どの程度の影響になるのかということがわかったら教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"本多委員","kind":"質問","question":"２つ目のほうのことなのですけれども。よろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"きちんと議員として把握をして、そこの区民の実態というのもつかんで、議会の中にぜひ反映をしていただきたいということを要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"沢田委員","kind":"提案","question":"条例提案を１点、考えております。事前に連絡しますので、ご賛同をお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993740?Template=document&Id=5152#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":11889,"voices":33}},{"id":"h27-20150916-10","meetingId":"h27-cm09","date":"2015年9月16日","dateIso":"2015-09-16","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時００分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件整理しています。","topics":[{"id":"topic-01","title":"平成２７年第３回定例会","agenda":"平成２７年第３回定例会","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"平成２０年から教育センターで就学相談員をされているということですけれども、理由、そこら辺のところを説明するよう求めました。","respondent":"濱野区長","answer":"私も存じ上げておりませんけれども、子どものことでいろいろと、特に品川区の教育委員会の人間と若干の接触があったとお聞きしております。それ以上のことは、私も存じ上げておりませんけれども、そういうことを理由にしたです。","id":"exchange-001"}]},{"id":"topic-02","title":"平成２８年度予算（議会費）","agenda":"平成２８年度予算（議会費）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"提案","question":"ちょっと質問なのですけれども、３番目の旧記者室の応接室ですが、本会議のときの保育室などに使うという提案もありますよね。そのときに、議場のインターネット中継のテレビなどは設置されているのか尋ねました。","respondent":"原区議会事務局長","answer":"まさにそのとおりです。見られるような形になっています。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、決算特別委員会の総括質疑なども、もちろん、そういう形で見られるということか尋ねました。","respondent":"原区議会事務局長","answer":"決算特別委員会は、ケーブルテレビは総括質疑のところだけカメラを入れておりまして、それを録画にしてやるという形になってございまして、本会議の中継とは少し違っておりますので、それは放送できないという形になっております。","id":"exchange-003"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"第３回定例会に向けて条例を提出する予定だったのですけれども、若干の調整が必要なので、第４回定例会以降に提出させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993740?Template=document&Id=5154#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":9610,"voices":72}},{"id":"h27-20150918-4","meetingId":"h27-c-settlement","date":"2015年9月18日","dateIso":"2015-09-18","committee":"決算特別委員会","time":"午後 ２時４７分～午後 ２時５３分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/550610?Template=document&Id=1402#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":2117,"voices":17}},{"id":"h27-20150924-6","meetingId":"h27-cm09","date":"2015年9月24日","dateIso":"2015-09-24","committee":"区民委員会","time":"午前１０時００分～午後 ２時５５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を76件整理しています。","topics":[{"id":"topic-01","title":"第６７号議案 平成２７年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第６７号議案 平成２７年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"済みません、違ったら大変なので、その確認と。準備課としては、どういう姿勢で向かっていくか、教えていただけますか。","respondent":"間部文化観光課長、小川オリンピック・パラリンピック準備課長","answer":"伸び率が非常に高いということで、２０１３年度と比べまして、観光客としては５２％増と。経済発展が著しく、観光客が増えている点と、文化的にも近いということで、タイに今回、力を入れてみるというものです。こうした障害者スポーツですとか、毎年実施してまいりたいという思いがございまして、アンバサダーの北澤豪氏のほうに交渉をしているという状況です。","id":"exchange-001"},{"speaker":"藤原委員","kind":"質問・要望","question":"要望と、どのような感じに思っていらっしゃるのかというのを、もう１回、いただきたいのと。区長もそういうお考えがあると思うのですけれども、その辺も含めて、もう１回答弁していただけますか。","respondent":"間部文化観光課長、小川オリンピック・パラリンピック準備課長","answer":"意外と日本の観光というのは、１カ所に１、２時間ということで、非常に短時間だと。そういった、来訪者の方が満足していただけるような内容にするべく、趣向を凝らしてまいりたいと、このように考えております。区内の開催競技というものが３競技ありますので、気運醸成を図ってまいりたいということと、ブラインドサッカーを取り上げさせていただきました。","id":"exchange-002"},{"speaker":"南委員","kind":"意見","question":"補正でこれだけ組んでということで、タイから来る観光客のためのマップ中心にという話なのですけれども。大体、先ほどおっしゃって数字を挙げられたこれ、タイは６５万人という、これは、品川区を訪れているということで理解……との意見を述べました。","respondent":"間部文化観光課長","answer":"日本ですね。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"オリンピック・パラリンピック推進特別委員会でも伺ったのですが、音を聞く競技ですから、ちょっとそのあたりが非常に気になるので。どういうふうに働きかけをしようと思っているのか、そのあたりをちょっと伺いたいなと思います。","respondent":"間部文化観光課長、小川オリンピック・パラリンピック準備課長","answer":"３番目がまち歩きということで、ちょっと待ち時間も含めて１、２時間。京都のように神社仏閣が充実しているわけではありませんので、そういう部分を狙っていきたいと、このように考えてあります。現在、オリンピックの競技、２８競技中２６競技の会場が決定しているところでございまして、あと２競技についてはまだ未定です。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、ぜひ、その辺もちょっと研究もしていただきながら、つくるのであれば、そういう内容でつくっていただきたいなと思います。それは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問","question":"この話をした後に、やはりサッカーを、区民の方も一緒にとか、子どもに教えてほしいという意見がすごく、区民の方からはいただきました。そういう面も、やはり区民の方の意見も聞いて、こういう事業をどんどんしていってほしいということです。","respondent":"間部文化観光課長、小川オリンピック・パラリンピック準備課長、山崎商業・ものづくり課長","answer":"やはり団体活動だとなかなか難しいけれども、個人だったらそういうチャンスもやってくるだろうということで考えています。そういった観点から… １部に用意しておりますが、実際に北澤選手がブラインドサッカーを体験する姿も、お子さんたちにぜひ見ていただきたいというふうに考えてあります。今… そうすると、タイの方が、日本に研修で常時５、６人来たりとかということをやっております。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"確認","question":"地域団体の独自マップとのバランス、支援のところを強調されたいと思ったので、確認を含めて伺います。先ほどの説明で、月１０万円程度の見込みで委託をされると思うのですが、その相手先というのですかね。","respondent":"間部文化観光課長、小川オリンピック・パラリンピック準備課長","answer":"はフェイスブックの運営経費ということで、翻訳配信料として月１０万円を、今のところは見込んでいるというものです。なので、丁寧なパンフレットだとか、ガイドの配置だとか、こういったのも含めて、今後は考えていきたいと… 実はブラインドサッカーフェスタを実施させていただいて、あさって、９月２６日にホッケーフェスタを開催する予定です。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"観光アクションプランのところ、最後に伺いたいのが、効果検証という、ちょっと言い方をしてしまったのですが、これもほんとうに検証が難しいものと。これぞまさに国際交流なので、そこのやはり旗振り役、リーダーとして、他の自治体との競争という点から、決意を伺えればと思います。","respondent":"間部文化観光課長","answer":"お風呂も入りに行くとかいうことも考えますと、地域に、経済的な貢献も図られるわけでありますので、そういった部分も含めて、新宿に負けるなと。","id":"exchange-008"},{"speaker":"松永委員","kind":"質問","question":"現地代理店とありますけれども、具体的にどういったところというのは、会社等がもしわかれば。この費用に関して、デザイン料ももちろん含まれているのでしょうかということです。","respondent":"間部文化観光課長","answer":"２、３時間という、ちょっとしたすき間時間で行かれるところというコンセプトでつくっていきたいというふうに思っております。この経費につきましては、当然デザイン料も込みで作成してもらえるです。","id":"exchange-009"},{"speaker":"松永委員","kind":"質問・要望","question":"要望になりますけれども、タイ語版の観光マップを載せてみてはいかがと、そう思っております。６種類３万部というのですけれども、大体１年間にどれくらいはけているのか、伺いたいと思います。","respondent":"間部文化観光課長","answer":"観光協会にお願いしている部分もありますので、ＰＤＦファイルになろうかと思いますけれども、できれば載せてまいりたいというふうに考えております。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"確認","question":"それから、ブラインドサッカーのほうは、これはちょっと確認なのですけれども。第１部のほうの体験会について、補正予算を組んでいただいていることでよろしいかどうか、その確認です。","respondent":"間部文化観光課長、小川オリンピック・パラリンピック準備課長","answer":"一つのお店を支援する形というのは、装飾灯の補助はするけれども、個店の支援はしていないのと同じ考えで。再委託になりますので、一定の手数料的な部分はとられると思いますけれども、数％なのかというふうに認識をしています。 北澤選手に関しましては、第１部の体験会も含めて、ほぼ確定ということで、話を進めているところです。トークセッションをしていただきたいですが、そちらのほうが、まだ調整が十分にできていないです。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。それ以外のところとの内訳みたいのが、もしあれば、教えていただければと。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"北澤選手の講師謝礼は、一応５０万円ということで予定しております。その他、協会関係者が来ていただければ１０万円、あと選手の方々、今のところ３人を予定しておりまして、１人５万円。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"マップの配布が１カ月後ということは、ほぼほぼできている状況なのですか。ああ、違う。","respondent":"間部文化観光課長","answer":"今、当然、見積もりをとっている段階ですので、その中で、一定のやりとりをしていますので、予算が配当になれば、補正議決をいただいて配当になれば、すぐ印刷にかかれるという状況になっていますので、１カ月ほどで、現地にも配れるだろうという見込みを持っているものです。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"そのマップみたいな感じなのですか。そのお店とかは、どうやって選んでいるのか尋ねました。","respondent":"間部文化観光課長","answer":"観光協会が中に入りますので、観光協会のほうで情報を収集して、人気があるもの、特徴のあるものということで選ばれているというものです。そういった、こういうお店が人気があるというようなものも調査した上で、また載せていくということになるかと思います。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問","question":"ほかのお店とかからは、ほかのマップか何かのときとかにも、声は上がってこなかったのですか。何か、平等ではなくなってしまうではないですか、多少。","respondent":"間部文化観光課長","answer":"テレビにも出たり、雑誌も出ると。どうして観光協会がそこを使ったのだというような類のクレームは、私どもには入っていないというのが現実です。","id":"exchange-015"},{"speaker":"渡部委員","kind":"質問・要望","question":"そのタイ語のマップが実際、よそにあるかどうかが１点。冊子代とか、いいのかとか、いろいろ考えられてどういうふうになったのかというところを教えていただきたいのと。","respondent":"間部文化観光課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問","question":"ほかの１位から５位の国のものも、一つつくるのであれば、要はそれの翻訳だけでいいわけですから。リニューアルというのを、この際、立派なものができるようであれば、逆にお金のつかいどころですから、考えては。","respondent":"間部文化観光課長","answer":"アップデートされるのが大事だと思っていますので、この点については、そのような考えで実施をしてまいりたいと思います。この点については観光協会と話をしていきたいと、このように考えています。","id":"exchange-017"},{"speaker":"渡部委員","kind":"質問","question":"中国の方に受け入れられるかどうか、でもせっかくですから、ずどんとやってしまったほうがという思いもありましたので。観光協会としてでも結構です。","respondent":"間部文化観光課長","answer":"そのような統計は持ち合わせてございません。","id":"exchange-018"},{"speaker":"渡部委員","kind":"質問・要望","question":"メモの端書きでいいですから、どこどこホテルに１００枚出したというのが、何か台帳管理ができていれば、羽田空港１００枚いった、そのあと何枚追加。できればやっていただきたいというご要望をしまして、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-02","title":"被災地応援ツアー商品券の不正受給","agenda":"被災地応援ツアー商品券の不正受給","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"これはずっと何年か、４年目ですか、続いている事業ですよね。そういう１つ１つの内訳ですかね。","respondent":"間部文化観光課長","answer":"ツアーの数だとかなり５倍ぐらい多いし、被害金額も１００万円以上多いということで、非常に被害が多くなったのかと認識をしています。は、警察当局の捜査を見守った中で、どういうふうに対応されるのかということを見守ってまいりたいと考えています。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"だから、再発防止をどういうふうに考えるかというところなのだと思うのですけれども。それを最後に伺って終わりたいと思います。","respondent":"間部文化観光課長","answer":"区としましても８月２５日以降は、確実に添付を義務付けていますので、再発はないというふうに確信はしています。引き続き実施をしていきたいと思っていますので、ご理解、ご協力のほどよろしくお願いいたします。","id":"exchange-021"},{"speaker":"田中委員","kind":"意見","question":"この応援ツアーそのものを、ちょっと根本からやはり考えてみるべきだと思います。というのを聞いていたので、ちゃんと、しっかりと管理してほしいと求めました。","respondent":"間部文化観光課長","answer":"日常生活で浮いた１,０００円、被災地応援というのが主眼とした事業ではありますけれども、このような事業のフレームになったというものです。今後も、この枠組みについては継続していきたいと考えています。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"そうしたら、被災地応援ツアーという名前があれじゃないですかね。被災地でやはりお金を使ってもらわないと、被災地の応援にはつながらないのではないかというのを思いますし、そこら辺は考えていただけるのか。","respondent":"間部文化観光課長","answer":"２億円を上回る寄附が集まったりだとか、何とかして区として取り組むことはできないかということで、この事業が始まったところであります。基本的なこのフレームについては、このままで継続していきたいと、このように考えてあります。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"本当に継続していってほしいというのは、すごくありますし。そこら辺を本当に、再発が絶対に起きないように、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"渡辺委員","kind":"質問","question":"他の業者も、今回の当事者も含めて、高齢者クラブ等の比率も地域から伺っています。この辺の、今、庁内の連絡体制等どうなっているのか説明を求めました。","respondent":"間部文化観光課長","answer":"民生委員協議会だったら福祉計画課等、綿密に連絡をとりながら調査も進めましたし、その調査の回答も戻してきたと。今後も、もし同じような不正が見つかれば、同じフレームで対応していくと、こういうものです。","id":"exchange-025"},{"speaker":"渡辺委員","kind":"意見","question":"そのほかで、まず区民の方って、所管がどうこうという話ではなくて、品川区行政は一つと考えると思うのですねとの意見を述べました。","respondent":"間部文化観光課長","answer":"区として毅然とした対応ということですけれども、先ほどもご説明させていただいたとおり、いまだに１面トップのところに載せてありまして。司直の捜査が進んでいるところというふうに認識をしていますので、一定の結論が出たときに、また次の段階があるかと。","id":"exchange-026"},{"speaker":"たけうち委員","kind":"意見","question":"立ち会われたかどうかわからないですけれども、どんな反省具合というか。どういう感じだったのかというのを、ちょっとお知らせほしいと求めました。","respondent":"間部文化観光課長","answer":"当事者がどういう対応をしたかですけれども。直接、今はアポイントはとれない状況になってあります。","id":"exchange-027"},{"speaker":"たけうち委員","kind":"意見","question":"でも、とはいえ、お詫びしたいという気持ちをとめるわけにはいかないと思うのですが。免許自体も、場合によっては、失うということもあり得るという見方で見てもいいのかとの意見を述べました。","respondent":"間部文化観光課長","answer":"何かの罪状で裁判にかけられて、禁錮以上が確定すれば、旅行業の免許は剥奪をされる。それまでは、免許については剥奪をされないのだというような見解でございました。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"領収書を出させていなくても、このツアーのことを思い、被災地を思い、やるのが普通の会社ではないですか。その辺について、どう思いますか。","respondent":"間部文化観光課長","answer":"委員ご指摘のとおり、当然、会社が不正を働く意思があって、故意に虚偽の報告等を行ったという点では、まさにそのとおりだというふうに思います。そういう抜け道があったというのは事実でありまして、この点については、区も含めて反省をしているというようなところです。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"それと、生活安全担当課長にお伺いしたいのですけれども。こういう質疑だとか案件を見ていて、これは、難しいことをお伺いするのではなくて、生活安全の課長でもあるし、前職というか、流れもあって。","respondent":"間部文化観光課長、濱田生活安全担当課長","answer":"他社については５０人のところを４５人とか４８人とかとずれるのが多い中で、そういうチェックについては、できた可能性はあったかと。これは観光協会を含めて、被害に遭わないように、事故のない、再発防止については… 共犯として、先ほど言った有印私文書偽造、詐欺罪ということで立件されると思います。それで、旅行業の登録については、いわゆる主管であるところと連携して、行政処分ということで進めていくということです。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"最後の質問で、品川区とこことは、どういう関係なのですか。それも含めてちょっと、最後に教えてくれますか。","respondent":"間部文化観光課長、久保田地域活動課長","answer":"これはなかなか難しいご質問なのですが、区と特別な関係にある会社でないということは事実であります。あくまで２１社のうちの１社ということで、取扱いをしてきたというものですので、それ以上でもそれ以下でもございません。区政協力委員会としての研修会ではなくて、大井第二地区の町会連合会としての研修会ですので、その意味でも区とのかかわりはございません。","id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"何割ぐらいが６８ツアーなのか。全体のツアーの中で、ちょっとそれを伺いたいと思います。","respondent":"間部文化観光課長","answer":"申請の６０％が不正ということで、ツアーの数だと８０％が不正で、申請の６０％が不正。さくらツーリストの取扱いは、ツアーで見ると２７％、人的に見ると４２％ということで、かなり取扱いが多い事業者であったことは間違いございません。","id":"exchange-032"},{"speaker":"南委員","kind":"意見","question":"そうすると、先ほど、例えば町会とか自治会とか、いわゆるそういう団体の皆さんも利用されていたという話がありましたよね。それは、その不正をした６８ツアーの中のどれくらいを占めているのか、その辺をちょっと知りたいのですけれども、わかりますかとの意見を述べました。","respondent":"間部文化観光課長","answer":"今度は６８ツアーの内訳ですけれども、先ほども委員のご質問にお答えしましたけれども、大体４割が町会、４割が高齢者クラブ、その他の消防団等、民生委員等が２割というような状況です。","id":"exchange-033"},{"speaker":"南委員","kind":"意見","question":"そういういわゆる民間団体、地域の団体の皆さんが利用していたツアーというのは、６８ツアーの中の何割を占めているのか。〔「１００％ですよ」の声あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"南委員","kind":"意見","question":"１００％。何か、その辺がどうなったのかというのが、わかってと思うけれども、ちょっとどういうふうに見たらいいのかというのを知りたいとの意見を述べました。","respondent":"間部文化観光課長","answer":"そうではなければ、空のツアーの申請ができないわけですね。そういう点では、個人情報的な部分も含めて、やはりよろしくない対応があったのだと、このように認識しております。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"だから、そういう点での、やはり、きちんとした厳正な対処、そういうものをやはり求めていかないといけないなと。その辺どうなのかというのを、ちょっと最後に聞いて終わります。","respondent":"間部文化観光課長","answer":"とれる対応については、説明させていただきました領収書添付になったとしても、このように考えていますので。区としては、その点をもって、そういう気概をもって、きちんと事業を執行していきたいと思います。","id":"exchange-036"},{"speaker":"南委員","kind":"質問・要望","question":"最後に要望で。委託というのは、ちょっと厳しい教訓にしていかなければいけないなと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"渡部副委員長","kind":"確認","question":"品川区が被害に遭ったのでしたというところ、この申し込みですね。それとも名簿の提出義務まで、これはあったのかどうか、ちょっと確認を。","respondent":"間部文化観光課長","answer":"名簿提出につきましては、人数確認のため、必ず添付をお願いしておりました。","id":"exchange-038"},{"speaker":"渡部副委員長","kind":"意見","question":"それはしっかり、品川区、守っていくべきだと思いますけれども。どなたかしかるべき人の答弁との意見を述べました。","respondent":"安藤文化スポーツ振興部長","answer":"今回、本当に、２３年の３.１１から、区民からの応援したいだとか、また区を挙げても応援する。何ができるか、私どもちょっと研究させていただきまして、今後対応させていただきたいというふうに思っています。","id":"exchange-039"}]},{"id":"topic-03","title":"「品川区地域安全のつどい」の開催","agenda":"「品川区地域安全のつどい」の開催","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"初めに、課長、今年の４月からですから、去年の、去年もやりましたよね、これ。その辺で、去年もやったのですけれども、やはりこうやってお金をかけてやるわけですから、まず投資対効果がどういう形で出ているのかというのを。","respondent":"濱田生活安全担当課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"藤原委員","kind":"質問","question":"そのときに、すごい効果ですよというご答弁をいただいたではないですか。これ、まずは、何で歌謡ショーが必要なのか尋ねました。","respondent":"濱田生活安全担当課長","answer":"１点目の罪種、これが８月末現在３４件、昨年度比マイナス１８件。今回は、山川豊さんのご厚意で、協力しますということで、５０万円ということです。","id":"exchange-041"},{"speaker":"藤原委員","kind":"質問・要望","question":"そのときまで、改めて品川区の安全を守っていっていただきたいと思うので、よろしくお願いします。その辺はどんなふうに感じられますか。","respondent":"濱田生活安全担当課長","answer":"山川豊さんのを初めのほうに行いますと、一つの考え方として、こういうふうに考えて後のほうにやっております。","id":"exchange-042"},{"speaker":"藤原委員","kind":"質問","question":"来てくださる１,０００名の方が、地域を思ってやってくださっていくことを願って、質問を終わりたいと思います。どうもありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"たけうち委員","kind":"質問・要望","question":"品川のこの地域安全のつどいが何回目になるのかというのが、ちょっとわかれば教えていただきたいのと。これと連動して、何か地域でのそういう安全のための取組みみたいのは、やられるのかどうかというのを教えていただけないか尋ねました。","respondent":"濱田生活安全担当課長","answer":"各警察署でそれぞれ、振り込め詐欺に関する広報等、行います。１０月１５日に「こども１１０ばんの家」を周知させるために、ＤＶＤを作成したということで、そのつどいを大々的にやるということも聞いております。","id":"exchange-044"}]},{"id":"topic-04","title":"マイナンバーに係る通知カードの配送等","agenda":"マイナンバーに係る通知カードの配送等","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そうなったときに、３カ月の保管期間を過ぎてしまったらどうなるのかというのを、ちょっと一つ教えてほしいと求めました。それからネット関係の、ネットというかシステムの関係でもいいのですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"システムの関係ですから、聞けるかなと思うので。そのあたりを教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"南委員","kind":"質問・要望","question":"その先が来年１月、来年の１月から使用が開始されるという、そういうことですけれども。もう一度、どのくらい想定していらっしゃるのかを、ちょっとその数値だけ教えてほしいと求めました。","respondent":"井浦戸籍住民課長","answer":"年が明けまして、マイナンバーの交付が始まりますが、初めの３カ月間で、想定しているのが２万件程度という数字で想定しています。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問","question":"ＤＶでシェルターを転々となさっている方とかがすごく多くて、そういう方たちは受け取れないではないですか。そういう方に対しての対応はどうしていくのかということを聞きたいです。","respondent":"井浦戸籍住民課長","answer":"こちらにつきましては、カードの送り先を申請していただいておりますので、まずそちらのほうにお送りするということで考えてあります。転々とされている方については、個別にご相談をしまして、受け取る方法、最善の方法で取り組んでまいります。","id":"exchange-048"},{"speaker":"田中委員","kind":"意見","question":"人の本当に小さなミスだったりするみたいなので、本当にそういうことがないように、慎重にしていってほしいと思います。お願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"南委員","kind":"確認","question":"一つだけ確認したいことがあって。さっき忘れてしまったのでいいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"南委員","kind":"意見","question":"今でも２割ぐらいあるというふうな、そういう情報を、ちょっと手に入れたので。品川区の場合は、それはどうなっているのかを聞きたいと思いますとの意見を述べました。","respondent":"井浦戸籍住民課長","answer":"国からの確認の通知がございまして、品川区としては、ネットと切断しているシステム環境で用意しているということで回答しています。","id":"exchange-051"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"田中委員","kind":"質問","question":"この前の一般質問で、非核宣言自治体協議会に加入しているのですけれども、品川区がなぜか入っていなかったので。そんな感じです。","respondent":"石田（し）委員長","answer":"本日は、「都市型観光の推進と来訪者獲得の取組み」というテーマで、議論を進めていくものなので。基本的には、その件に関してお答えすることはできないと思います。","id":"exchange-052"},{"speaker":"田中委員","kind":"質問","question":"では、その交流に関して、広島・長崎との交流が深くなるように検討してみて、その話を持ち帰っていただいてもいいかというところで、よいでしょうか。そういう話もあるということで、では、持っていっていただければ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"たけうち委員","kind":"提案","question":"どちらかというと関東とか東日本で主になっていた中で、西日本とか九州のほうと、ぜひやるべきだということを提案させていただいて。品川区からのアプローチというか、何かそういうのをお考えになっているかどうか、もしあれば教えてほしいと求めました。","respondent":"間部文化観光課長","answer":"そこが、浜川砲台の復元ということで、たまたまここにチラシがあるのですが、１１月１日にお披露目会をするということで進めているようです。観光の面でも、そこの花街道も含めた観光ルートについて考えていこうということで、検討を進めているところです。","id":"exchange-054"},{"speaker":"たけうち委員","kind":"提案","question":"今回、うちの新妻議員のほうからも、ちょっと制度を提案させていただいて。一応お聞きしたいと思いますとの意見を述べました。","respondent":"間部文化観光課長","answer":"歴史的な部分では、資料館とか、そういう部分には難しいかもしれないのですが、ちょっとした夢とロマンの方面から。大政奉還１５０年というところに引っかけて、観光協会と一緒に、ちょっと考えていきたいと思っています。","id":"exchange-055"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ちょっと所管が違うかもしれませんけれども、一緒に考えていくのがいいのかと思いますので、よろしくお願いします。それは要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"渡辺委員","kind":"提案","question":"見直しというのをキーワードにされるべきではないかという、提案というか意見です。この点、いかがか尋ねました。","respondent":"久保田地域活動課長","answer":"そちらの宿泊施設を使いますので、安く、確か１０％ぐらいの割引で泊まれると。他の自治体とどういうお付き合いをしていくかといった議論の中で、今後、調査研究が必要な内容かというふうに思っております。","id":"exchange-057"},{"speaker":"渡辺委員","kind":"質問","question":"その辺、どう把握されているか、もう一度伺いたいと思います。その辺を、文化スポーツというくくりで見解を伺えればと思います。","respondent":"久保田地域活動課長、池田スポーツ推進課長","answer":"双方で２分の１ずつ負担しようということで、また引き続き、効率的な交流を図っていきたいというふうに考えているところです。よりよい交流が進められるようにとは考えてありますが、それぞれ課題等も踏まえながら… どこか違う場所でできないかという検討を行いまして、山北町のほうでもしできればということで、検討させていただいているところです。","id":"exchange-058"},{"speaker":"渡辺委員","kind":"質問・要望","question":"する・見る・支えるの３要素で言えば、あとは企業の協力だとか、研修の位置付けに来ていただいたときには宿泊をしていただくと。分類の中で、改めて文化スポーツの枠組みで検討されたいと思いますが、いかがでしょうかで終わります。","respondent":"池田スポーツ推進課長","answer":"委員からご意見のございましたスポーツの交流ですけれども、私どもとしましても、こういったご意見とかを、十分に認知いたしまして、今後、研究させていただきたいと思います。","id":"exchange-059"},{"speaker":"松永委員","kind":"意見","question":"これは、２４市町で行われているということですが、役割分担というのは。この自治体が集うというところで、どこに集まって、年に何回ぐらいのペースで行われているのかを聞きたいと思いますとの意見を述べました。","respondent":"立木産業活性化担当課長","answer":"年に３回ほど持っておりまして、それから首都圏開催の定例会ということで、年３回ほど実施をしています。定例会のほうも、事例紹介等を含めまして、いろいろ産業の活性化という部分で、定期的な会合をしているようなことです。","id":"exchange-060"},{"speaker":"松永委員","kind":"質問","question":"２５区市町で行われているのですけれども、今後、増えていくというのはあるのかと。運営費負担金で１０万円というのは、これは全部の、２５区市町で払われているのか、それだけ伺って終わります。","respondent":"立木産業活性化担当課長","answer":"実際、当初は、もう少し少ないところから始まっておりまして、徐々に増えて、今現在２５ということになっておりますので。事務局都市が多くなっておりまして、事務局負担金が１０万円となっておりまして、それ以外のところは３万円ということになっております。","id":"exchange-061"},{"speaker":"たけうち委員","kind":"質問","question":"そういう中で、まだ行政とは、そんなにかちっとしたのはやっていないのですけれども、何かあれですか。飯田市のほうからの、アプローチがかなり、行政のほうにはあるのか尋ねました。","respondent":"山崎商業・ものづくり課長、間部文化観光課長","answer":"それで、１７番のとごしぎんざまつりと、それから５ページのほうの２１番のほうの商店街での出店。行政レベルのお付き合いをしたときの、今現在は… あれのシェアが全国で８割方あるということで、特にリニアのつながりということで、品川区と何かを結びたいと。","id":"exchange-062"},{"speaker":"たけうち委員","kind":"質問・要望","question":"どこというのは言えませんけれども、そういう意味で、活発につながっていくようなところを積極的に取り組んでいただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"田中委員","kind":"確認","question":"確認なのですけれども。飯田市が先につながって、その後、青木村がつながった、でよろしいのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"そういったところの関係がそれぞれにあって。飯田市と青木村は、特に連携して品川区とというような関係ではございません。","id":"exchange-064"},{"speaker":"渡部副委員長","kind":"確認","question":"ある程度、そのときどきに合ったこともやっていかなければならない反面、しかしやはり区民のニーズにどう応えていくか。資料の確認をさせていただいて思ったのですが、どなたかお答えいただける方は、お答えもらえますか尋ねました。","respondent":"久保田地域活動課長","answer":"盛んに民民レベルでも行われているということで、これらを、私どもも大切にしていきたいという気持ちはあります。これらを今後どうやって進めていくかということは、いろいろな事業のあり方とか、その時代のニーズに合わせた検討が必要というふうに考えてあります。","id":"exchange-065"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"群馬県と、健康村というような名前で、今も３０年ぐらい付き合っているのでしょうか。当時ですから３０年前ですね。","respondent":"山崎商業・ものづくり課長","answer":"チャイナ・プラスワン、タイの次はベトナムではないかという意味では、そうした客観的なところは認識をしてまいりました。しっかり、当面はそうした方向で、ちょっと区としては考えようということになってあります。","id":"exchange-066"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"さまざまなアンテナを張った中で、ここら辺の交流というのは、これからも続けていっていただきたい。地元の地場産業を支えていくという部分では、すごく目玉になる政策でもあると思いますので、交流を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"南委員","kind":"質問","question":"あれこれ伺いたいけれども、ここには２４と書いてあるけれども、ものづくりで交流があるということを改めて知ったのですよね。どんなかというのを、ちょっとその点を伺いたいと。","respondent":"立木産業活性化担当課長","answer":"クラスターフェアというのが２月に開催される予定ですけれども、それで将来につなげていくというような取組みというのも、一つ今後計画をしています。技術の貢献、そういったことができるような形で、連携をとっているというようなところの事業です。","id":"exchange-068"},{"speaker":"松永委員","kind":"意見","question":"先ほども、活発な議論をしながら、また私たちも頑張っていきたいです。以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"たけうち委員","kind":"提案","question":"行政がどうそこに絡んでいくかというのは、できる限り、やはり支援をしていただきながら。民民の活力をどう、しっかりやっていっていただきたいというのと、何かあったら提案させていただきたいと思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"渡辺委員","kind":"質問","question":"先ほど、午前の質疑にもありましたけれども、やはり目標設定という中で、少しおかたい面ではなくて、やわらかい取組みというのですかね。それをさらに掘り下げていくとなると、おもしろみもより一層出てくるかという思いを持っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"田中委員","kind":"意見","question":"子どもたちも、次、大人になったときにでも、ずっと品川区のことを思っていられるような、そういう、つながっていけばいいというのを思うので。済みませんとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"},{"speaker":"南委員","kind":"質問・要望","question":"本当に区民が求めているもの、区のあり方というか、そういうものも大事だろうというふうに思うし。で、私の意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"藤原委員","kind":"質問","question":"路地のところに井戸があって猫がいてとかって、いいなと言うけれども、違う委員会に行くと、火が出ちゃったらどうするんですかって。いろいろ質問していくと思いますが、品川区の特徴は何ですかと聞いたら、もう一言ですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"田中委員","kind":"質問","question":"追加してもいいですか。住民の方の自慢したいポイントなどを、もっと聞いてほしいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"渡部副委員長","kind":"意見","question":"品川区に来てほしいなと。当然、いろいろ、渋谷、新宿とかもありますけれども、品川区にも来てほしいなというとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/878133?Template=document&Id=2732#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":80531,"voices":213}},{"id":"h27-20150924-7","meetingId":"h27-cm09","date":"2015年9月24日","dateIso":"2015-09-24","committee":"厚生委員会","time":"午前１０時００分～午後 ３時０６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を80件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)、第７２号議案 品川区立地域密着型多機能ホームおよび品川区立認知症高齢者グループホーム条例の一部を改正する条例","agenda":"はじめに、(1)、第７２号議案 品川区立地域密着型多機能ホームおよび品川区立認知症高齢者グループホーム条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"２の方は対象から外れていますけれども、どうなってしまうのか、追い出されてしまうことがないのかということです。小規模多機能型居宅介護の介護報酬が、今どういった仕組みになっているのかということも、教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"事業所のほうでも認識しておりまして、常勤換算２.５人が確保できるということで、変更をするものです。要支援１、要支援の方は今、要介護が出るような見込みになっています。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、今後、全ての人が必要になってくると考えていらっしゃるということで、よろしいのかということ。それから、今回の変更によって、利用者で看護を受ける人と受けない人で、利用料は変わってくるのかということを説明するよう求めました。","respondent":"永尾高齢者福祉課長","answer":"今、看護が必要か、必要ではないかということで、利用料自体の差はつけていません。歩行訓練とか、そういう意味で、より安心したサービスを受けられるところに違いがあるかと思っています。","id":"exchange-002"},{"speaker":"のだて委員","kind":"意見","question":"利用料は変わらないということでしたけれども、これまで受けてきたサービスと全く同じではなくて、少し安心したサービスが受けられるということですけれども、看護を受けている方と少しサービスが違う中で、同じ利用料というのは、区としてはどのように考えているのか、説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"実際のサービスがきめ細やかになるというところで、本人も、ご家族もより安心感があるかと思います。これまでもかかりつけ医との連携はとっているかとは思うのですけれども、薬の面でより綿密な連携をとり、安心感は強くなるかと思っています。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回のように介護予防まで行っているグループホームというのが、これまで、品川区で他にあったのかという確認です。待機者も何人いるのか、介護度別にわかれば教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"認知症対応型と、介護予防型、これの併設という形になっております。待機の状況ですけれども、特にないと聞いております。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"そうしますと、個別で申請していただいて、検討しているということですけれども、この間、検討してきた中で、グループホームが必要だと思うけれども、入れないという方はいらっしゃらないということか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"ケアマネージャーと、あまり困難なケースであれば、うちのケースワーカーもつきながら選んでいるという状況です。今、正確な数字は持ってきていないのですけれども、区全体で言えば、やはり待機している方はいらっしゃいます。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"それから、今回の改正で、要支援２の方が対象の範囲になりますけれども、入所の対象にもなるのかということです。ケアによって、介護度が変わったときに、位置づけられるということですけれども、入所の対象にもなるのか、説明を求めました。","respondent":"大串福祉計画課長","answer":"グループホームの必要性を考えておりまして、この東五反田で１４カ所目ということで、検討は重ねていきたいと考えているところです。要支援の方の入居についても、そのまま入居が続けられるということで、入所を保障するという意味合いです。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"要支援の方も入所対象になるということですけれども、そうすると、介護度の重い方が入れないということになってしまうのかどうか、そういったところの考え方も教えていただけたらと思います。","respondent":"永尾高齢者福祉課長","answer":"要介護２くらいから上ですけれども、集団の中で落ち着かなくなってしまうとか、そういう方は入居が難しくなるという条件になるかと思います。ですので、一概に要介護度が重いから、軽いからということが基準にはならないです。","id":"exchange-007"},{"speaker":"いながわ委員","kind":"質問・要望","question":"少し教えていただきたいのですが、１、杜松地域密着型多機能ホームのところで、サービス向上のために、訪問看護サービスを一体的に提供ということですが、常勤換算２.５人という根拠というか、通常、法令で定められた人員の配置は何名なのか、その辺を詳しく教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"その基準が、常勤換算で２.５人以上となっております。その換算どおりに配置する予定になっております。","id":"exchange-008"},{"speaker":"いながわ委員","kind":"質問・要望","question":"例えば３人になったらどうなのか、多分多様化していると思うので、その辺の考え方を教えていただきたい。少しそれてしまっていますけれども、その辺を説明するよう求めました。","respondent":"永尾高齢者福祉課長、大串福祉計画課長","answer":"国のほうの換算の２.５人で開始をして、より大変になってくれば、そのときの検討となります。それだけ人件費がかかってしまうので、そのあたりの運営の仕方とか、そういうところも一緒に検討していかなければいけないと思っています。昨年１２月オープンでしたが、その前にも校庭を使って、同じように実施をしましたし、また、今年もやる予定と聞いております。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それから、これは私も一般質問でやったので、もう一度お伺いしたいのは、ショートステイの位置づけを、どうされていこうとしているのか。せっかくここで看護とかいう問題もやっていくのであれば、そこら辺はどうお考えなのかということを、もう１回改めて伺いたい。","respondent":"永尾高齢者福祉課長","answer":"今、うちのほうでやっている期間をもう少し延ばしたらどうかということも、ケアマネージャーを中心に検討している最中です。その中で、皆さんの意見も聞きながら、どういう支援ができるかということを一緒に考えていきたいと思います。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２０人、２.６人だと採算ベースかなという意識が変わるのかどうか、一つ教えていただきたい。救急車で運ぶということなのか、そこら辺がよくわからないのだけれども、そこら辺の考え方を教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"今回の４月１日の制度改正の中で、他の訪問看護事業所との連携について、緩和がされています。やはり流れとしては、地域包括ケアということで、だんだんと緩和されてきている流れはあるのかなと感じているところです。","id":"exchange-011"},{"speaker":"石田（秀）委員","kind":"質問","question":"最後に１点だけお聞きします。行財政改革みたいな話になってしまって、すみません。","respondent":"永尾高齢者福祉課長","answer":"それから現実、そういうことも特区申請にあたっては、相手からのヒアリングでお尋ねがあるかと思います。だから、そういうことも全て固めたうえでの申請でないと、なかなか通らないかと思います。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"去年１２月に杜松地域密着型多機能ホームはオープンしたわけですけれども、はじめからなぜできなかったのかなという思いがしているのです。はじめから、小規模多機能型居宅介護を利用してもらうことにもなったのではないかと思うのですけれども、その点はいかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"横浜から初めて品川区にきたというところで、介護職員の採用のことから、地域へのご説明のことまでいろいろとご苦労があったと聞いています。大体順調に進んできたというところもあって、新しいものに挑戦したいというような意向があると聞いています。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それから仕組みのところで教えていただきたいのですけれども、訪問看護が必要になった場合は、両方とも利用するということは可能なのでしょうか。その仕組みもちょっと説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"需要のお話になりますけれども、やはりこれからどうしても高齢者の数が増える中で、重度の方はどんどん増えていく見込みがあります。２３区でもなかなか進まない理由になっていますので、その中で、ほかのところにもできるかどうか検討していきたいと思っています。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"通い１５人、現在の職員態勢にプラス看護師１.５人ということで、丸々１.５人の看護師がプラスという体制になるのか。全体がどうなっているのか、説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"ただ、一体的に一つの計画に基づいてできるかできないかというところと、主治医との連携の部分がもっと濃密になるというところが違うということです。すぐに答えられないのですけれども、今度、看護職員を常勤換算で増やすということは聞いているところです。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"では、丸々１.５人の看護師が増えるということで、介護福祉士に置きかえられるとかということではなくて、登録の数とか、通いとか、そういうことは全部同じであるにもかかわらず、看護師が１.５人増えるということで考えていいのか、その確認だけお願いします。","respondent":"永尾高齢者福祉課長","answer":"今の状態に看護師が増えるということになります。","id":"exchange-016"},{"speaker":"若林委員","kind":"質問・要望","question":"参加していなければ、どういう考え方になっていくのか、確認をさせてほしいと求めました。これからどう取り組まれようとしているのか、方向性くらいになるのか、考え方などをお聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"ただ、実際問題、２４時間そういう医療が必要な方全てに、そういう対応はなかなか難しいのが現状なのかと思います。現在の医療との連携の会議とか、いろいろな分野の多職種のご意見と協力が必要になりますので、そこをまず構築していこうかと考えています。","id":"exchange-017"},{"speaker":"若林委員","kind":"質問","question":"ご家族の負担にとっては、やはり小規模多機能型居宅介護、そういう施設で看取ったほうがいいのではないか。できれば、そういう小規模多機能型居宅介護の施設の中での看取りが負担がないのかと思うのですけれども、これは考え方だけ説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"本当に理想的なのは、やはりご本人も、家族も、本当に身近な地域の中が理想的なことだと思っています。そういうことがないと、ご家族がまた不安になってしまうということもありますので、まず基盤をきちんと整えていかなければいけないと思っています。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ、今お話が出たので確認だけさせてください。何でもかんでも見れないから有料老人ホームへどうぞと、どうなのかというところだけ、お話を説明するよう求めました。","respondent":"永尾高齢者福祉課長","answer":"在宅で最後まで看取るというお話になりますけれども、それが本当に全ての人かというと、確かに全ての人ではないかと思います。その子どもなり、そこら辺はやはりニーズを確認しながら、どの程度広げていくべきかということも検討しなければいけないと思っています。","id":"exchange-019"},{"speaker":"のだて委員","kind":"意見","question":"特にグループホームは、身体能力が改善されて追い出されることになっては安心してサービスを受けることはできないので良いと思います。賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"}]},{"id":"topic-02","title":"第７３号議案 品川区立特別養護老人ホーム条例の一部を改正する条例","agenda":"第７３号議案 品川区立特別養護老人ホーム条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それとあわせて、候補者が決まった経緯を、以前の委員会で報告されているのかもしれませんが、教えていただけたらと思います。それから、指定管理者の申請書が既に出されているのか、出されていなければ、いつ出されるのかということも説明を求めました。","respondent":"大串福祉計画課長","answer":"指定管理候補者として、品川区の社会福祉法人三徳会にお願いをする予定です。本日こちらで設置条例をご決定いただいて、次回の第４回定例会に指定管理者の議決ということでご審議をいただければと考えているところです。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"今の見通し、５月に１００人を受け入れできそうかどうかということがわかれば、教えてほしいと求めました。これから第４回定例会に指定管理者の条例が出るということですけれども、既に、教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"１点目、１００人の受け入れということに関しては、そこに向けて、今、努力をしています。先ほど申し上げましたように、第４回定例会で、こちらの件に関しましてはご審議をいただければと考えているところです。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今の質問の続きですけれども、指定管理者の条例が第４回定例会に出るということですけれども、指定管理者から区に対して申請書というのが出ますよね。いろいろあるではないですか、もう既に出ているのか、出るとしたらいつごろなのかということをお聞かせいただきたい。","respondent":"大串福祉計画課長","answer":"こちらの設置条例を認めていただいた後に、三徳会のほうからは、指定管理に関しての収支の関係や職員体制といったものをいただきます。本日、認めていただいた後ということになります。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"どういう手順で来るのか、またそれがどういうものなのかということをチェックすることも必要だと思っていますのでお聞きしたのです。行政のほうでそれを審査して、そして第４回定例会に、三徳会ということでの指定管理者の決定を求める条例が出されるという手順ということですよね。","respondent":"大串福祉計画課長","answer":"おっしゃるとおりです。そういった流れを踏まえて、第４回定例会でまたお示しするという形になります。","id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"わかりました。もう一つお聞かせいただきたいのが、全体の複合施設になるわけですけれども、もしわかったら教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"平塚橋特別養護老人ホームについては１.４ということで、１１２床×５００万円×１.４ということで、７億８,４００万円が補助金になります。補助金が７億８,４００万円入ってきますので、施設の事業費としては、特別養護老人ホーム部分については２８億円という形です。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、７億４,８００万円も含めて２８億円だから、それを引いて２０億円ちょっとということでいいわけですね。整備率が１％以下のところは１.５と思っていたのですけれども、なぜ１.４なのか、説明を求めました。","respondent":"大串福祉計画課長","answer":"これまでは１.５くれていたものが、１.４になったという形です。その辺の配分につきましては、東京都のほうから示されるという流れになっています。","id":"exchange-026"}]},{"id":"topic-03","title":"第７４号議案 品川区立高齢者多世代交流支援施設条例","agenda":"第７４号議案 品川区立高齢者多世代交流支援施設条例","exchanges":[{"speaker":"横山委員","kind":"質問","question":"調理台があるコミュニティ室３は、調理台のほかにどういったものがあるのか、もう少し詳しく教えていただけたらと思います。２点目ですけれども、どういった形になっているのか、この施設について教えていただけたらと思います。","respondent":"松山高齢者地域支援課長","answer":"男性のほうにつきましては、そこら辺は整備計画の中にないのですが、あとは誰でもトイレというのは大崎と平塚橋にも設置しています。そういったことで、配慮をしていこうと考えております。","id":"exchange-027"},{"speaker":"いながわ委員","kind":"質問","question":"１点だけ、どこにあるのか、あえて設置をしないのかどうかということを教えてください。その辺、双方、どういう感じになっているのか説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"改築の際に合わせまして、対象者を限定した施設ではなくて、多世代交流施設への検討の可能性を図っていこうと考えております。４点目が、ちょっと左のほうですけれども、飲物程度はこちらで提供できるかなと考えております。","id":"exchange-028"},{"speaker":"いながわ委員","kind":"質問","question":"やろうという話にもなって、もちろん持ち込みになってくると思うのですが、そういうことが可能かどうかということをお伺いしたのです。わかる範囲で構いませんので、お願いします。","respondent":"松山高齢者地域支援課長","answer":"交流ということを進めるうえでも、飲食というのは一つ、それを通じたつながりが必要になってくると思います。まだこれから検討してまいりますけれども、こちらのほうは多世代交流を進めるうえで、考えてまいりたいと考えています。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私の周りには、６０歳で高齢者と言うのはやめてほしいという人が結構いる。６０歳で高齢者はひどいというような話があって、何か方法があるのどうか、考え方を説明するよう求めました。","respondent":"松山高齢者地域支援課長","answer":"確かに６０歳以上の方を高齢者と呼ぶのは、こちらの高齢者多世代交流支援施設のほうも、国の要綱で決まっているものです。シルバーセンターもやはり老人福祉法で決まっているものでございまして、そちらも６０歳というのが定義ですので、そのようにさせていただきました。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこの見直しは必ずやるべきだろうと、これは違うところでやりますが、確認だけしておきます。そう書いてあるので、そうだと思うのですけれども、それだけ一つ確認をしておきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"若林委員","kind":"質問・要望","question":"先ほど、前の議案でありましたけれども、この指定管理の話はまだこれからですかね。大崎ゆうゆうプラザのほうの２階の平面図でいくと、この間は何でしょうか、私は理解するのです。","respondent":"松山高齢者地域支援課長","answer":"前月の１０日から予約を承っておりますので、受付方法を規則で定め、利用者説明会にて説明したいと考えています。大崎高齢者多世代交流支援施設につきましては、これから公募を行う予定です。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"あるいは、ほかのどういったイベントをイメージしているのか、教えてほしいと求めました。施設の変更制限などが規定されていますけれども、これもどういった考えでこうなっているのかということを教えてほしいと求めました。","respondent":"松山高齢者地域支援課長","answer":"こちらの施設、多世代交流支援施設の目的を達成するために効果的な事業を入れていこうと考えております。３点目の地域交流スペースですけれども、そこで読み聞かせ等を行っていただくとか、そういったものもあるかと考えています。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"それとも、やはりそういったしっかりとした企画を立ててやっていくのかというところを確認させてほしいと求めました。それから、なぜ指定管理にしたのかという考え方を教えてほしいと求めました。","respondent":"松山高齢者地域支援課長","answer":"平塚橋高齢者多世代交流支援施設につきましては、例えば嚥下障害の方の相談などに応じていくといった部屋も、１階部分に２部屋あります。指定管理者にすることで、効果的、効率的な、行政ではできないような発想のものも取り入れていただきながら運営したいと考えております。","id":"exchange-034"},{"speaker":"のだて委員","kind":"確認","question":"確認ですが、今回、平塚橋のほうは、指定管理候補者としては、特別養護老人ホームと同じ三徳会でいいのかということです。その職員体制ですね、コーディネーターなどを配置するということがあるのか、説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"それから、体制ですが、特にこの多世代交流施設のほうは、コーディネーターという名前では配置は予定しておりません。今のところ、９時から２１時半までの受付業務になるので、どういったような体制がいいかは、三徳会と協議をしています。","id":"exchange-035"},{"speaker":"のだて委員","kind":"確認","question":"２番目が、この団体は、高齢者が一人でもいればこの団体ということになるのか、その確認です。週２回ということですが、私は考えるのですけれども、２日にした考え方を説明するよう求めました。","respondent":"松山高齢者地域支援課長","answer":"目的外使用の2)、例えばＮＰＯの中でも、三徳会と連携を図って交流事業をやっていこうというような企画をしている団体もあります。これまでも週に２回ということでございまして、これまでもお風呂の回数や場所につきましては、公衆浴場組合と協議を重ねてまいりました。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"入浴サービスのほうですけれども、浴場組合と話したということですけれども、もう少しどういった話し合いがあったか教えてほしいと求めました。これから規則で考えていくということだと思いますが、考え方が、これまでと同じなのかどうかというところも教えてほしいと求めました。","respondent":"松山高齢者地域支援課長","answer":"できれば、これは継続していただけたらと考えています。３点目、あとは高齢者との交流というもう一つの目的がありますので、そちらがプラスされるというようなイメージです。","id":"exchange-037"},{"speaker":"のだて委員","kind":"確認","question":"最後に確認ですけれども、高齢者の交流事業を行う団体というのは、不特定多数の方がいる団体が望ましいということでしたけれども、基本的には高齢者が使える施設ですし、最初に言いましたけれども、一人でも高齢者がいれば使えるということでよろしいのか、確認です。","respondent":"松山高齢者地域支援課長","answer":"ただ、貸し施設になりますと、お一人で７０人のところを予約できるかというと、ちょっと難しいと考えています。ただ、これから、地域の団体から企画が出てくる場合もありますので、それはこちらのほうで今後つくっていくものだと考えております。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"すみません、私の聞き方が悪かったのかもしれませんが、一人でも、というのは、団体にいる高齢者が一人でも目的内使用になるのか、それとも何人かいなければ目的外使用になるのか、それをお聞きしたいと思います。","respondent":"松山高齢者地域支援課長","answer":"〔「違う」と呼ぶ者あり〕2)の高齢者の交流事業を行う団体ですけれども、この目的に合っていれば、特に高齢者ということではございません。高齢者の方がいらっしゃらなくても、高齢者との交流事業を行う団体ですので、交流事業を企画運営する団体です。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"条例の第９条に、「交流事業を行うことを目的として高齢者その他区民で構成される団体」とあるのですけれども、これは違うということでしょうか。聞き方が悪いかもしれませんが、一人も高齢者がいなくても、この団体は目的内使用になるのか、改めてお伺いしたいと思います。","respondent":"松山高齢者地域支援課長","answer":"申しわけありません、正しく説明します。それ以外の方は区民で構成される団体です。","id":"exchange-040"},{"speaker":"新妻委員","kind":"質問・要望","question":"そうなりますと、お金が発生するわけで、今ご説明があったとおり、例えば一人高齢者を責任者につけて、ここに該当させるのか。目的内使用として施設料を取らないで活用していただけるのか、そこはご相談できるのか、ちょっと確認をさせてほしいと求めました。","respondent":"松山高齢者地域支援課長","answer":"今のご質問の、子育て世代に関して目的外使用なのか、ですけれども、例えば、高齢者との交流事業を行うという目的で、高齢者がお一人以上中に入っていれば、それは目的内になりますけれども、単に子育て世代ということであれば、目的外になります。","id":"exchange-041"},{"speaker":"新妻委員","kind":"質問","question":"目的外なわけですね。この多世代交流という施設の中において、今後、子育て世代へ使用料なしにするというお考えはされていかれるのか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"今後、子育て世代への使用料の免除に関してですけれども、施設の位置づけが、まずは高齢者福祉施設という位置づけですので、今のところは、それは考えておりません。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それから大崎ですけれども、そこの利用率はどの程度だったのか、一つ教えていただきたい。そういうことも入ってくるのか、そこの点について、教えてほしいと求めました。","respondent":"松山高齢者地域支援課長","answer":"多世代にしてどうかということで、今、三徳会と協議を進めております。三徳会が安全に円滑に運営できる範囲内の体制を考えてくださいということでお願いをしております。","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"職員体制の変化はあるのか、どうなのか、説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"かなり仕事の幅は広がりますし、新しいところなので、配慮事項も広がると考えております。そういった中で、どういった人数が適正なのかというところでは、こちらのほうも三徳会と協議を重ねているところです。","id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"指定管理者になることよって、対象が高齢者だけだったのが多世代というで、対象者が広がるということはわかります。仕事の中身そのものが、交流ができるような企画やいろいろな働きかけ、そういうことまで指定管理者がやるのかどうなのかとの意見を述べました。","respondent":"松山高齢者地域支援課長","answer":"委員ご指摘のとおり、交流、働きかけというのも三徳会にお願いしています。交流事業といったことで、企画を、今、三徳会のほうで練っている最中です。","id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは全体で使える分の例えば３分の２くらいで、あと３分の１はあいているとか、そういうことがわかったら、教えていただきたい。3)に福祉避難所機能と書かれているのですけれども、先ほどご説明がなかったので、あるのかも含めてお聞かせほしいと求めました。","respondent":"松山高齢者地域支援課長","answer":"もちろん防災の備蓄倉庫という形できちんと設置をし、平塚橋高齢者多世代交流支援施設につきましては、かまどベンチの設置を予定しております。２階以上の特別養護老人ホームも含めまして、シルバーセンターの避難所と合わせて避難所機能を充実させたいと考えております。","id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"一応、福祉避難所という位置づけということなので、そこら辺のところはきちんと位置づけて充実できるような形で整えていってほしいと求めました。そういうところでは、なおかつ、この新しい施設によって使い勝手が悪くなるようなことがないようにということだけお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"石田（秀）委員","kind":"提案","question":"あわせてプロポーザル提案があって、候補者として決めたのだと思っている。では、何で議案提案がここにあるのかとの意見を述べました。","respondent":"松山高齢者地域支援課長","answer":"ただ、答弁のほうにかなり細かい具体的なところがございましたので、申しわけございません。指定管理者候補者として、今後、第４回定例会に議案を提出する予定です。","id":"exchange-048"},{"speaker":"石田（秀）委員","kind":"提案","question":"そういうことも含めて、プロポーザルで業者選定をしているわけですから。これは要望だけにしておきます、答弁は要りませんとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"}]},{"id":"topic-04","title":"第７５号議案 品川区立児童学園条例の一部を改正する条例","agenda":"第７５号議案 品川区立児童学園条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今、ご説明のありました新施設の条例というのが、今後出てくると思うのですけれども、いつ出されるのか、スケジュール等を教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"新施設は平成３０年度以降の運営となりますので、早くても平成２９年度、あるいは平成３０年度の早い段階と考えているところです。","id":"exchange-050"}]},{"id":"topic-05","title":"第６７号議案 平成２７年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第６７号議案 平成２７年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"はじめに、ネウボラネットワークというのは、初めての事業だと思いますので、委員会資料としても、しっかりこの資料を出してほしいと求めました。第２段階以降があると思うのですけれども、そのスケジュールと、大まかな内容について教えてほしいと求めました。","respondent":"太田品川保健センター所長","answer":"そして出産直後の支援を行うということになっておりまして、ネウボラネットワークの検討委員会のところで、子ども育成課を中心に検討しています。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"１１月からカタログギフトを配る方も３,４００人いるわけですけれども、しっかりとした体制が必要だと思いますが、どういうふうになっているか。これまでも、これまでの事業との関係、どういったことになっていくのかということを教えてほしいと求めました。","respondent":"太田品川保健センター所長","answer":"そして支援が必要な方、ご家庭の支援が得にくいなどの対象者に対しては、詳細な支援計画をつくりまして支援を継続していく。支援がつながりまして、全戸訪問して全産婦にお会いするという形で、この事業がつながっていくものです。","id":"exchange-052"},{"speaker":"のだて委員","kind":"確認","question":"１１月から３,４００人いるということになりますから、一人当たり３００人とか、その考え方を教えていただきいと思います。それから、産後の子育て訪問とか、継続してやっていくということですけれども、それも含めて、ネウボラネットワークということになるのか、確認です。","respondent":"太田品川保健センター所長","answer":"もちろん一遍に生れるわけではありませんので、順次やっていく体制を考えると、６名で対応可能と考えております。まだネウボラネットワークの中で検討中ですが、生後４カ月くらいになりましたら、一緒に継続的に支援していくということになります。","id":"exchange-053"},{"speaker":"のだて委員","kind":"確認","question":"確認になってしまいますが、生後４カ月以降は、その確認です。毎回、相談するたびに、相談員が変わってしまったら、結局意味がないと思いますので、そこの確認です。","respondent":"太田品川保健センター所長","answer":"ただ、それでも、きちんと情報の支援シート等を整備いたしまして、それを専門職種で共有しながら支援していくという方向で考えております。子ども育成課とも従来以上に連携を密にして、継続的に支援していくように検討を進めているところです。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問","question":"非常勤なので、ずっとというのは難しいかもしれないというお話でしたけれども、そうなると、常勤で配置していったほうが、そこでずっとできていくのかと思うのですが、その辺の考え方を説明するよう求めました。","respondent":"太田品川保健センター所長","answer":"今後、いろいろ事業をスクラップしていく中で、そちらのほうにかかわっていきたいと考えています。あるいは支援の計画については、常勤がこのようなかかわり方でもやっていけるという支援体制を構築しましたので、非常勤でやっていく方針ですが。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"非常勤でもしっかりとした支援をしていく体制ができたということですけれども、その体制というのも具体的に、なぜ支援がしっかりできるのか、もし、先ほどの説明に加えてあれば、教えてほしいと求めました。","respondent":"太田品川保健センター所長","answer":"資料を新たに作成しまして、それを使って説明するように、事細かく決めております。非常勤、あるいは常勤にかかわらず、全てのことにつきましては、子ども育成課ときめ細かく連携をして、支援を行う体制をとっていく予定です。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、そういったことも検討に加えてほしいと求めましたので、これは要望だけにしておきます。区が４分の１負担することになっていると思うのですけれども、東京都の返還金とはどういうものか、教えてほしいと求めました。","respondent":"伊東生活福祉課長","answer":"市区町村が４分の１というようなことになってありますけれども、生活保護法の第７３条のところに、都道府県の負担というものがあります。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"聞き忘れていましたので、もともと予算で何人見込んでいて、何人になったのかということを教えてほしいと求めました。住宅扶助等の引き下げによる改修だと思いますけれども、幾ら下がるのか、そしてその対象人数を教えていただけたらと思います。","respondent":"伊東生活福祉課長","answer":"２人世帯が追加されまして、３人から５人世帯、そしてもう一つ６人世帯が追加されたというものです。それから、影響を受けるだろうと思われる２人世帯ですけれども、少し数字的に古いのですけれども、２月の段階で１７１世帯ほどあったです。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"住宅扶助費の引き下げは、ただでさえ借りるところを探すのが大変な中で、引き下げられるということで、この金額で本当に探せると思っているのか、区の考え方を教えてほしいと求めました。","respondent":"伊東生活福祉課長","answer":"全国的に国のほうがさまざまな調査をしまして、それに基づきまして、住宅を借りられるだろうというような想定の中で決められたものと思ってありますので、区としましても、この基準に沿って進めていかなければいけないと思っているところです。","id":"exchange-059"},{"speaker":"横山委員","kind":"質問・要望","question":"ほかの委員からも質問があったのですけれども、３点追加で、詳しく教えていただきたいことがあります。３点目ですが、１１月から始まる部分は、妊娠届から始めて、生後３カ月まで保健センターのほうで支援をしていくということでよろしいのか尋ねました。","respondent":"太田品川保健センター所長","answer":"子育てまでの支援を行いまして、４カ月以降は、お近くの児童センターをご案内するということになります。一緒に支援をするけれども、子育てネウボラ相談員なのかという、その変化だけです。","id":"exchange-060"},{"speaker":"新妻委員","kind":"質問・要望","question":"打ち合わせの場が持たれていくのか、どのような形で情報が伝えられて、即対応ができる体制をとっていられるのか教えてほしいと求めました。妊娠期のこの大事なときに、どのようなフォローをされていくのかというところも確認をさせてほしいと求めました、お願いいたします。","respondent":"太田品川保健センター所長","answer":"今の体制でも、定期的に障害者福祉課ということになりますが、連携して支援は行っております。ですから、ケース会議ということになりますが、その中で対応をしていくことになります。","id":"exchange-061"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"３番の支援計画の作成というのは、非常勤のネウボラ相談員の方が、この３,４００人全ての面接をするわけですよね。それから、おおよそ何人くらいというか、何％くらいの方が支援計画を立てることが必要になるのかということについても、説明を求めました。","respondent":"太田品川保健センター所長","answer":"考えておりますが、休暇は産前６週・産後８週ですので、まずはやっていただきたいと考えています。産後鬱になる方が８から９％くらいいますので、大体１０％くらいの方に対して支援計画を立てることになると考えています。","id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"出産後、妊産婦ネウボラ相談員が全妊婦に電話してアドバイスをするということですが、２週間後にすくすく赤ちゃん訪問がありますよね。うちの娘がお産したときに２週間後に助産師がきてくれて、そしてまたその２週間後にきてくれたのですけれども、そういう制度がありますよねとの意見を述べました。","respondent":"太田品川保健センター所長","answer":"２週間でご連絡をいただければ訪問ということも可能ではありますが、今のところは、産後２カ月くらいの訪問になっているところです。大体生後２週間から１カ月の間には産後の電話相談を行いますので、その時点で、訪問がかなり早く行けるようになるのではないか期待しています。","id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"割り返すと一人当たり１４３万円くらいですけれども、そうすると、１カ月１１万円くらいで、こんな人件費だととても安いという思いがしています。ここのところを人件費の考え方を教えてほしいと求めました。","respondent":"太田品川保健センター所長","answer":"人件費につきましては、一月２１万９,０００円になります。これは５カ月分になります。","id":"exchange-064"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"この事業は大事な事業だと思うのですけれども、もともとの品川区の保健師の数は、２３区の中でも一番少ないと思うのです。品川区の保健師の数の少なさと、こういうところに対してしっかりと常勤対応していくという点については、いかがか尋ねました。","respondent":"太田品川保健センター所長","answer":"先ほども申し上げましたように、後方支援として常に支援計画、あるいはその事業の進行については目配りができる体制はとってあります。これでもう少し余裕ある体制がとれるかどうかについては、今後、検討を進めてまいりたいと思います。","id":"exchange-065"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"改めてこの事業を開始するにあたっての増員ということも、ぜひ、検討してほしいと求めました。今、こちらのほうからずっと継続してやってもらうというような体制は考えられていないのか、説明を求めました。","respondent":"太田品川保健センター所長","answer":"産後の健康電話につきましてはご協力いただいて、電話をした人に訪問するという形での継続性は持とうと考えています。産後電話をして、すくすく赤ちゃん訪問までは同じ人でつながるという、その２種類のつながりが生れるかとは思っております。","id":"exchange-066"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"初めて行う事業ということですので、本来こうあるべきだというところにいくまでには何段階かあるとは思いますけれども、今後に向けていろいろと充実をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは、私も一般質問でも取り上げさせていただいて、必ず前へ向かってやっていただきたいと考えています。３,４００人くらい見ているのかなと思うのですけれども、１年間を通して考えたときに、そこをまずお聞きしたい。","respondent":"太田品川保健センター所長","answer":"１１月以降は、妊娠届の場所でこの事業について周知いたしますので、９５％を見込んだ方がほとんどきてくださるのではないかと考えております。１１月以前の妊娠届１,７００人、１１月以降に妊娠届１,７００人の合計３,４００人を見込んでおります。","id":"exchange-068"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"９０％の部分はそこでフォローできるというような考え方で取り組まれているところもあるということなので、ぜひ、そういうことも考えていただきたい。ですから、ぜひ成功させてほしいと求めました。","respondent":"太田品川保健センター所長","answer":"研修等も行い、面接に関しての資料も非常に豊富に取り揃えて、面接にいらした方が満足して帰っていただけるように備えていくつもりです。","id":"exchange-069"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"４４４事業の中で五十幾つはやっていこうといっても、今は一つもやれてないわけですから、こういうことがやれるということをやっていく。答弁はあれば、どうぞお願いします。","respondent":"中川原副区長","answer":"今、品川区としては、これまでの保健所の妊娠期から子育て支援まで、個々の施策については、全国に先駆けていっぱいやってきているのです。","id":"exchange-070"}]},{"id":"topic-06","title":"平成２７年請願第２４号 骨髄移植ドナーに対する支援制度導入に関する請願","agenda":"平成２７年請願第２４号 骨髄移植ドナーに対する支援制度導入に関する請願","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"東京都が平成２７年度からやって、品川区がなぜこれをやらなかったのか、やる予定があるのか。そこら辺のところの兼ね合いというか、今後の予定というか、どういうふうにお考えなのか説明を求めました。","respondent":"舟木保健予防課長","answer":"この制度につきましては、東京都のほうでは、今までは稲城市が実施しているほか、やっているような状況ではありませんでした。このような制度があるということで、品川区においての支援事業についても、今後、検討していきたいと考えています。","id":"exchange-071"},{"speaker":"石田（秀）委員","kind":"質問","question":"東京都が支援事業を平成２７年度から追加したわけですから、なぜ稲城市だけはすぐにやったのか、あとほかどこかやったのか。検討してやらないということもあるし、前向きに検討するという話と大分違うと思うのですけれども、そこら辺の考えを説明するよう求めました。","respondent":"舟木保健予防課長","answer":"ほかの自治体において、都の包括事業の中にあるような制度を既に実施している自治体があることについては、区も認識しております。区のほうでは、今までは啓発事業のみで、特にこのような支援事業等は実施しておりませんでした。","id":"exchange-072"},{"speaker":"石田（秀）委員","kind":"質問","question":"特別区長会でも出していて、これをやることのデメリットって何かあるのですか、逆に。どうしてなのかなという感じなのですけれども、悪いですけれども、もう一度お願いします。","respondent":"舟木保健予防課長","answer":"予算編成の時期でもありますので、この支援事業につきましては前向きに検討してまいりたいと思います。","id":"exchange-073"},{"speaker":"いながわ委員","kind":"質問","question":"１点お伺いしたいのですけれども、あえて品川区では違う補助事業を展開しようと思っているのか、どうなのか。今、品川区はそれに対して進めているのか、どうなのか、お聞きしたいと思います。","respondent":"川島健康課長","answer":"今回、この事業で手を挙げたとしても、ほかの補助が減るということはないだろうという見込みを立てております。都のメニューと同額の仕組みにすれば、１０分の１０歳入があるということだと思いますので、しっかりその辺も踏まえて準備を進めたいと考えています。","id":"exchange-074"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまでに、品川区でこの対象になるような手術というか、そういった人がいたのか、わかれば教えてほしいと求めました。","respondent":"舟木保健予防課長","answer":"保健所としては把握しておりませんが、ただ、ドナー登録の数とか、また移植の件数、東京都内に暮らしている方とかから推定しますと、年間三、四件くらいは、そういう方がいたのではないかと予想しております。","id":"exchange-075"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"結論を出してほしいと求めました。採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"いながわ委員","kind":"質問・要望","question":"結論を出すで、採択です。こういった包括事業に関してはアンテナを張っていただいて、ぜひ、俊敏に動いてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"}]},{"id":"topic-07","title":"はじめに、(1)、専決処分の報告","agenda":"はじめに、(1)、専決処分の報告","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今、借りている方の状況を、区としてどのように把握しているのかということ。この間の返済状況、再三にわたる督促にも応じないとありますが、何回くらいやり取りをしているのか説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"払うときには、もちろんそこでお話もしておりますけれども、払われないときには、区からは１０回程度催告をしております。３回程度催告をして、今回、訴えを起こしたということになっております。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"それとも、どういう状況で払わないのかということも、つかんでいたら教えてほしいと求めました。この払えない中で、少しずつ払っていくという形がとれなかったのか、その辺の区の考え方も説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"ただ、最終的に、支払いが平成２２年月分まででとまっておりまして、その後、払われていないということです。最後にコンタクトがとれているのが平成２６年１０月１５日ということになっております。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問","question":"少しずつ払うような対応ができなかったのかということもお聞きしたので、それもどういった検討をされたのか、あるいは、していないのかということも説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"月２万円で６０カ月の分割払いということで、最初のお約束をしておりまして、途中で月２万円は難しいというお話で、１万円にしたりということで、相談は随時行っているところです。","id":"exchange-080"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/841532?Template=document&Id=3426#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":65670,"voices":239}},{"id":"h27-20150924-8","meetingId":"h27-cm09","date":"2015年9月24日","dateIso":"2015-09-24","committee":"建設委員会","time":"午前１０時００分～午前１１時５７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"の第７６号議案 品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"の第７６号議案 品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"６月の都市計画決定に伴う具体化ということですけれども、Ｃ街区での施設概要といいますか、開発計画の内容を教えていただきたいのですけれども。あわせまして、再開発に投入される税金があれば教えていただきたいのと、もともとこの地区の容積率と建ぺい率は幾らだったのか尋ねました。","respondent":"溝口都市開発課長","answer":"約８００戸ほどの住宅を建設する予定になっているものです。施設の高さといたしましては、ＧＬ（グランドライン）から約９０メートルほどの建築物を建設する予定になっています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは改めてお伺いしたいのですが、３者ということで複数の地権者ではあると思うのですが、基本的な違いというのを教えてほしいと求めました。資料２ページの表の中で、最高限度５９０％というのがここに入らないのはなぜなのかということも、あわせてお伺いしたいと思います。","respondent":"溝口都市開発課長","answer":"基本的に補助を出すのは組合施工の再開発事業に対しての補助金という形で考えておりますので、補助金等の導入というのは考えておりません。ただ一方で、地区計画または今回の条例の両方をあわせて、今回の事業が成り立つような形になるという仕組みになっているものです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"あるいは風害などの周辺の影響など、事前の環境調査などといった調査は行っているのでしょうかということを一つお伺いしたいと思います。お伺いしたいのは、今回のような８１４戸のマンションを新たに誘導するという計画が持ち上がった際、お伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"そういったことであるならばお伺いしたいのは、それで８１４戸のマンションの保育需要を満たそうという思いでそういう人数なのか、それとも……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"所管と都市開発課としては、そこら辺をどういうふうに考えて６０人規模なのか、都市開発課の考えを聞きたいということが一つあります。具体的にどういった調査を行って、どんな結果が出たのか、もう少し詳しく教えてほしいと求めました。","respondent":"溝口都市開発課長","answer":"風環境につきましては、実際に風洞実験を行いまして、影響評価をしています。対策を講じることによって、従前の周辺環境と変わらないような風環境を確保するという形で、指導を行っているところです。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"私もつぶさに見ていないものですからあれなのですが、住んでいる方の実感としまして、大きな風が出現する日が多くなっているというのは事実なのです。開発ビルの中で解消してもらうという考え方で動いていると、そういったふうに私は聞こえたのですが、それでいいのかどうかお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"周辺にさらに大きいものをつくる、再開発をやるという意味なのかどうか、そこら辺がわからなかったのでお伺いしたいのが一つです。どういうふうにボールを投げているのか、そこら辺をもう一度だけお伺いします。","respondent":"溝口都市開発課長","answer":"そのときにまた検討して、自分たちの中でどういった形で建替えができるのかという検討をしていくことになりますので、または単独なのかというのは。","id":"exchange-007"},{"speaker":"西本委員","kind":"確認","question":"資料の２ページのところにある主な概要の中に、こういうものは平仮名なのでしょうかという、簡単な質問をさせてください。具体的な形でどういうメリットがあるのか、何か不利益を被るようなものが出てくるのか、その辺はいかがか尋ねました。","respondent":"鈴木（和）建築課長、溝口都市開発課長","answer":"この法律の中でこういう表記が、平仮名で表現されているので、そのまま条例でも合わせて平仮名で表記しているというものです。 都市計画だけでは、建築確認のときにそのとおり合わせなくても勧告の罰則しかありません。その都市計画に合わせて事業計画を立てておりますので、今回条例が制定することによって、事業者のほうへの不利益というのはないものです。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"これは全体的にお聞きしたいのですが、こういった形で条例化していくという流れになっていくのでしょうか。それとも何か条件があって、条例になるものとならないものがあるということがあるのか尋ねました。","respondent":"溝口都市開発課長","answer":"今回、都市計画の変更に合わせての条例制定となっています。そういったものも勘案しながら事業を進めてきておりますので、今後も同じような形で再開発事業には取り組んでいきたいと考えております。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"今回は３社の事業者が計画を立てていくということなのですが、例えば初めに事業ありきということで、ずれが出てきてしまわないかと思うのです。合わせたような形で計画していけると思うのですけれど、途中からとかになってしまうと、その関係性というのはどういうふうになっているのか尋ねました。","respondent":"溝口都市開発課長","answer":"ですから、もともと計画的に進めていく地区に指定されているところでありますので、採算を含めて計画を立てているというのが実情になっております。そういった中でどういったものができるのか、都市計画が必要なのか、そういったものを含めて調整しながら進めているのが現状です。","id":"exchange-010"},{"speaker":"安藤委員","kind":"意見","question":"大もとの都市計画決定、３月２３日の都計審の計画案件も反対したのですけれども、これは大もとの再開発計画の条例による具体化です。さらなる再開発、超高層のまちづくりをどんどん進めるということにつながりますので、反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"}]},{"id":"topic-02","title":"の第６７号議案 平成２７年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"の第６７号議案 平成２７年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"質疑に入る前に、もし可能であれば委員長に要望したいのですけれど、次回以降補正予算についての資料提出もしていただくようにならないかと。自分で資料調べるよ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"私はもっと、委員会としての補正予算を審議するのであれば、資料があったほうがいいのではないかということで、要望させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"それぞれの施設で供用が開始される時期はいつと見込んでいらっしゃるのか、お伺いしたいと思います。今回の拡充幹線とこれまでの施設との機能的な違いを教えていただきたいのと、長さで、そこら辺もあわせてお伺いしたいと思います。","respondent":"和田河川下水道課長","answer":"最初の供用開始時期ですけれども、平成２９年度に稼働することを予定に、鋭意工事を進めているところです。それから規模につきましては、先ほど申しましたとおり、規模的には区内の整備水準である時間５０ミリ対応の排水能力が発揮されるものです。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。漏れていたのでお伺いしたいのと、この間は５０ミリ対応の雨がなかったからそうだったのか、そこら辺をお伺いしたいと思います。","respondent":"和田河川下水道課長","answer":"先ほどの質問で申し忘れましたけれども、戸越拡充幹線の径ですけれども、現在のところ３.５メートルの径を予定しています。延長ですが、２.５キロを予定しています。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"この１１１件のうち、その内訳、マンション管理組合あるいは賃貸住宅のオーナーのケースは何件だったのかという内訳をお伺いしたいと思います。この１１１件、幾らぐらいかというふうに区としては認識しているのか、あわせてお伺いします。","respondent":"松代防災まちづくり部長、矢木住宅担当課長","answer":"しかしながら先ほども担当課長が申し上げましたように、５０ミリ対応は、１時間当たりに降る雨ということです。そういったところに対応すべく、将来の豪雨に対して対応すべくやっているというのが現実ですので… 先ほどの件数１１１件の内訳ですが、９月１８日現在、直近のデータで回答します。今の時点での経済効果ですが、２億８,０００万円ほどになっておりますので、これが直接の経済効果と思われます。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"それとも区の予想を超えて反響が大きかったのか、広報が成功したのか、そこら辺はどのように考えているのかお伺いしたいと思います。下はシールド工法でやるというふうに伺っているのですが、具体的な工事の内容について、そこら辺も含めてご説明ほしいと求めました。","respondent":"矢木住宅担当課長、和田河川下水道課長","answer":"２６年度は年度途中で終了しましたが、まず平成２６年度終了した時点での積み残しと申しましょうか、増額補正をしたものです。 実施設計はこれからですので、計画が変更になる可能性はありますけれども、約１０メートルぐらいの深さで掘り進める予定です。シールド工法で行う予定ですので、その上の住宅等に対する影響はほとんどないということで考えてあります。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"この事業をさらに多くの方に知っていただくための広報の工夫を要望したいのですが、どういったことを今、いかがでしょうか。あるいは渋谷区のような２０％を上限に助成額を上げたりとか、そこら辺を求めたいのですが、いかがか尋ねました。","respondent":"矢木住宅担当課長、藤田都市環境部長","answer":"２点目のより大きな広報のＰＲ方法ですが、高齢者の団体における制度説明ですとか、あらゆる機会を捉えてＰＲを増やしてまいりたいと思います。３点目の使いやすい制度についての工夫ですが、それらの制度を研究しながら… １点目の来年度の部分ですけれども、今回改めて補正予算として提案させていただいている段階ですので、その辺の状況等も見守りながら、確認することがまず一番大切かと思ってあります。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、あらゆる機会を捉えて周知していただきたいと思っているのですが、この制度のご案内のチラシなどが置いていないところもあると思うのです。これは要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"２７ページにあります財源更正というところで、「職員給与費に対する諸収入増額に伴い」とあります。これは何の収入と諸収入と、直接そういう、どういうところでどうなっているのか、仕組みを説明するよう求めました。","respondent":"安井土木管理課長","answer":"そちらの関係で職員に充当するもの、工事費に充当するものを調整して、そういう形になってあります。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"五反田界隈だったか昭和の終わりか平成の頭ですか、この戸越幹線も一日も早く完成していただくように、よろしくお願いします。それから住宅改善資金融資あっせん、これは自民党としても前から期の途中で予算が足りなくなったときの対応ということは要望していました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"切実な早期の完成が求められる事業ですし、住宅改善の工事助成のほうも、区民の住環境の改善とともに区内の経済活性化にもつながります。どちらとも早期に予算をつけるべき事業なので、賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問・要望","question":"今年は見ていただいて、それで増額するにしてもまた必要になってくる部分が出てくるのかと思いますので、動向を注視していただきたいと思っています。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-03","title":"の専決処分の報告について（報告第３０号）","agenda":"の専決処分の報告について（報告第３０号）","exchanges":[{"speaker":"つる委員","kind":"確認","question":"ご答弁で確認できました。若干の修理で、それ以外のいわゆる損害賠償という部分が大きいのかと思ったのですが、そういうご事情だったとわかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"今後やはりこういったことはあってはならないと思うのですけれども、再発防止策として具体的にどのようなことを行っていくのか、行っているのかお伺いします。","respondent":"小林品川区清掃事務所長","answer":"今回の場合も移動する者が移動しているときに、複数で移動時等の場合には、慎重に作業を進めるという手順に変更をしたところです。今後、この新しい手順で作業の進捗を徹底してまいりたいと思います。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"賠償額ですが６１万円、これはどこから出るのでしょうか。それは区から出るという認識でよろしいのか尋ねました。","respondent":"小林品川区清掃事務所長","answer":"一般的に車両の事故の場合は自動車損害時の保険になりますが、これは作業中ですので、自治体損害賠償責任保険にあらかじめ加入しております。基本的には全額その保険対応ということで弁済しています。","id":"exchange-026"}]},{"id":"topic-04","title":"の専決処分の報告について（報告第３１号）","agenda":"の専決処分の報告について（報告第３１号）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺どうなのか、戸越一丁目地区での経験とも比べて、感じているところがあればご説明いただきたいというのが一つです。具体的にはどのような形でこの地区計画策定において反映されるのか、意見書と同じ扱いになるのか、そこら辺をちょっとご説明ほしいと求めました。","respondent":"寺嶋木密整備推進課長","answer":"説明会での意見ということですけれども、当然意見は取り入れるということでの説明会であり意見書ですので、その辺の内容を踏まえて対応していきます。対応が若干違っておりますけれども、意見としてお伺いするということに関しては、一切変わりございません。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"この説明会は３回行われますけれども、何か考えていることがあるか、一つお伺いしたいのと。先ほどちょっと説明がありましたが、委員が判断するのに大事になってくると思うので、そこをお伺いしたいというのが２点目です。","respondent":"寺嶋木密整備推進課長","answer":"一定程度の地元への説明が終わった段階、７月から８月にかけて開催をする、この時期に説明会をやったと。原案説明会につきましては、２月以降の縦覧等につきましては、制度的には可能になっております。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"あわせてお伺いしたいのは、いわゆる消防活動困難地域というのですか、どこになるのかということをお伺いしたいと思います。補助第２９号線のところですけれども、これはどういう内容を考えているのか、予定をお伺いします。","respondent":"寺嶋木密整備推進課長","answer":"そちらの状況を踏まえた上での説明会、実際に説明会でも、お話ししています。今のところ区のほうの推計では旗の台四丁目に１カ所残るであろうと思われているのですけれども、基本的には解消されると考えております。","id":"exchange-029"}]},{"id":"topic-05","title":"の北品川五丁目第１地区再開発事業","agenda":"の北品川五丁目第１地区再開発事業","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"６棟の建物がありますけれども、あるいはテナントが埋まっているのか、現在の状況を教えてほしいと求めました。それぞれについてお伺いしたいと思います。","respondent":"溝口都市開発課長","answer":"その上、ブライトプラザにつきましては、もう既に商業施設が９月１１日からグランドオープンして、業務を開始しているという状況になってあります。ですから、今回つくった施設につきましては、全て業者が入る、または住民の入居が決まっているというのが現状です。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"どれぐらいの昼間人口になるのか、区としては今回のこの開発で、この開発区域内に住民がどれぐらい増えるというふうに考えているのでしょうか。それと労働者は何人ぐらいと考えているのか、それを改めて、ざっとでもいいのですけれども教えてほしいと求めました。","respondent":"溝口都市開発課長","answer":"ですから１,６００人から１,７００人ぐらいの住民が増えるような形といった想定をしながら、進めてきているものです。お互いに取り組んでいく、それぞれの役割分担でまちの運営に当たっていくというのが、大崎・五反田タウンマネージメントとの関係です。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"運営はこちらの１社ということだと思うのですけれども、実際どういうふうな運営形態になるのかというのが気になるところだと思います。それからこの施設は区のものだということなので、この施設の持ち主として区はどのような役割や責任を果たすのかというのをあわせて説明を求めました。","respondent":"溝口都市開発課長","answer":"品川区が手を貸すことによって、長い将来にわたって当施設を地域の施設として運営していくというのが、一つ大きな役割だと考えております。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"ですから、そこら辺の責任があると思うのですけれども、そちらはいかがでしょうか。現在あの歩行者デッキの状況、見通しなどはどうなっているのか、お伺いしたいと思います。","respondent":"溝口都市開発課長","answer":"本来の地域による管理に反するものにもなると思いますので、そこら辺はしっかり運営者側と協議しながら進めていきたいと考えております。現在大崎ニューシティともつなぐ部分について、権利者と組合とが接続に向けて協議を行っているというふうに聞いてあります。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"今のところですが、区としては何かやっていることはあるのか。それと大体いつごろまでにこれが完成するという予定、見通しを立てているのか、そこら辺もあればお伺いします。","respondent":"溝口都市開発課長","answer":"スムーズな動線が確保できるといった観点でいますが、少しでも早い時期に完成を目指すというのが、私どもの考えです。再開発の事業者である組合と、接続する側の大崎ニューシティとが今現在協議中ですので、まだ明確な時期というのは決まっているものでございません。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"これは北品川五丁目第１地区の周辺地域の人しか使えないのか、具体的に集会室という施設でどういう活動を行っていくのか、そのイメージを知っている範囲で教えてほしいと求めました。","respondent":"溝口都市開発課長","answer":"夜になりますがオフィスワーカーの方たちが仕事帰りに何か講習会とか、そういったものを開けるようなものを今、いろいろ企画しています。今後さまざまなニーズに対応した形で、より使ってもらえるような施設にしていきたいと考えているものです。","id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"意見","question":"この大崎・五反田タウンマネージメントの運営の形態ですけれど、これは委託して管理か、どういう形で運営していくのかとの意見を述べました。","respondent":"溝口都市開発課長","answer":"当施設は普通財産として品川区が所有するような形、それを一般社団法人に貸し付けるという形になります。ですから当然、貸し付ける賃料は相場に沿った形で取って、運営に当たっていただくという形で考えているものです。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問","question":"区の財産として貸し付けて管理していくのは、部署としては都市計画課なのですか。地域活動だとか産業振興、いろいろな絡みが出てくるのですけれど、どこが管理していく形になるのか尋ねました。","respondent":"溝口都市開発課長","answer":"区の中の仕切りといたしましては、普通財産を持てるのは経理課だけになりますので、所管としては経理課という形になります。具体のところについては、引き続き都市開発課のほうで、エリアマネジメント等と一体となってこの施設を運営していくという形で考えているものです。","id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"質問","question":"間違えていたらごめんなさい、このタウンマネージメントは産業振興と相当つながりがあるのでししょうか、そこら辺、まず絡みがあるのかどうか、ちょっと伺います。","respondent":"溝口都市開発課長","answer":"大崎ブライドコアのＣ１にＳＨＩＰという品川産業交流施設、どちらかが強いというと、産業系でいきますと品川ビジネスクラブが強い。お互い一緒になって、大崎地域または品川区の発展への取り組みはしていきたいと考えているものです。","id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"大分お話も出ていたので、うまく各課と調整していただいて、進めていってほしいと求めました。これは要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"９月１８日の２日目の筒井議員の一般質問で、周辺地域を含めて厳格な保護をするための行政指導をすべきだという質問がありました。保全についてどういう手法を考えているのか、そして今後考えられるのか、そういったところをさらに詳しくお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/557041?Template=document&Id=4148#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":35370,"voices":136}},{"id":"h27-20150924-9","meetingId":"h27-cm09","date":"2015年9月24日","dateIso":"2015-09-24","committee":"文教委員会","time":"午前１０時００分～午後 ３時０４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を95件整理しています。","topics":[{"id":"topic-01","title":"第６９号議案、品川区すまいるスクールの実施に関する条例","agenda":"第６９号議案、品川区すまいるスクールの実施に関する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今までは実施時間や参加費に変更なくやってきたけれども、そこの具体的なニーズを教えてほしいと求めました。それは週１回または週２回実施だったのが週１回実施になるけれども、中身としては変わるのか変わらないのか、ちょっと説明を求めました。","respondent":"伊崎子ども育成課長","answer":"３０分でも１時間でも延長してほしいというもの、おおむね８時１５分ごろということで、その時間を設定したものです。それから、勉強会ですが、内容については全く変更ございません。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"これが全体でどれだけあったのかを把握されているのか、ちょっと伺いたい。今まで午後６時までいても取られていなかったものが、プラスで取られてしまうという根拠、考え方を説明するよう求めました。","respondent":"伊崎子ども育成課長","answer":"利用料の午後６時までのご負担が増えるですが、先ほどご説明をいたしましたように、制度の発足後から全くご負担を変えてきておりません。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"午後５時までが月に２５０円、午後５時から午後６時までが月にプラス３,０００円になってしまうという、区はどのように考えていらっしゃるのか尋ねました。","respondent":"伊崎子ども育成課長","answer":"放課後児童健全育成事業の料金として考えまして、総額を考えまして、こちらの負担額を出したものです。なお、これから検討するところですけれども、一定の低所得世帯へのご負担の軽減は検討を考えているところです。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"コストに見合う額をいただくということでしたけれども、２５０円、３,０００円、４,０００円と、その金額の設定根拠はどこから来ているのか、考え方を伺いたいのと、職員体制のほうは、午後７時までということですけれども、変わっていくのかどうかちょっと伺いたいと思います。","respondent":"伊崎子ども育成課長","answer":"現行経費よりも７,５００万円強の増を、見込んでおりまして、この額を受益者でご負担いただくという考え方からも適切であると考えております。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"そしてそれを２５０円にした、そして３,０００円、４,０００円にしたという根拠をもうちょっと詳しく伺いたい。すまいるスクールが始まる時間からずっと同じ職員で午後７時までということになっていくのか、こういうふうにしましょうというものがあるのかどうか。","respondent":"伊崎子ども育成課長","answer":"今ご説明申し上げましたように、２５０円につきましては、以前にやっておりました学童保育クラブの額を参考として決めていったものです。","id":"exchange-005"},{"speaker":"鈴木（博）委員","kind":"質問","question":"これを拝見させていただいて、午後５時までが月２５０円ということだから、１年で３,０００円ですよね。例えばおやつとか、午後５時以降に延長することによってかかる費用というのは、どのぐらい上増しというのは考えられるのか尋ねました。","respondent":"伊崎子ども育成課長","answer":"１割アップといたしまして約６,０００万円、１,６００万円ほどを見込んでおりまして、あわせまして７,５００万円ほどを見込んでおります。委託料につきましては、１割のアップで今交渉を進めているところですが、結果的にはもう少し上がる可能性があるかと考えております。","id":"exchange-006"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、ざっくりで結構なのですけれども、例えば午後５時から午後７時まで月に４,０００円増えるということなのだけれども、実際そのうちでどのぐらい今言ったもろもろの経費というのは運用でこの中に含まれるのか尋ねました。","respondent":"伊崎子ども育成課長","answer":"現在の利用状況を見まして、１７時以降、１７時を超えてご利用される方を９００人程度と見込んでおります。その人数で非常に粗い計算ですけれども、コスト増の金額を割りますと、お一人１万円強ということで負担が上乗せをされるということが一つあります。","id":"exchange-007"},{"speaker":"鈴木（博）委員","kind":"意見","question":"ただその金額の設定がどうかということはやっぱり問題になると思うのですけれども、先ほどちらっと課長が触れられた同じような事業で、他区の状況というのはいかがなものかとの意見を述べました。","respondent":"伊崎子ども育成課長","answer":"今一番多いのが４,０００円から５,０００円、多いところでは月８,０００円、延長料金を含めて８,０００円というところもあります。４,０００円のところでも延長料金が二、おおむね５,０００円、延長を含めて５,０００円から１万円の間が他区の状況です。","id":"exchange-008"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、この金額というのはある程度、特に品川区だけが突出しているというわけではなくて、他区とのバランスも考えて、あと学童の金額も考えて設定したというふうに理解してよろしいのか尋ねました。","respondent":"伊崎子ども育成課長","answer":"委員ご指摘のとおりです。","id":"exchange-009"},{"speaker":"浅野委員","kind":"質問・要望","question":"１７時から１８時、そういうような個別の対応というのでしょうか、これで決めてしまうのかということについて一つ教えてほしいと求めました。今まで年額だったので１年間ということでしょうけれども、どのようなことをお考えなのか、そういうのもあるかと思うのですけれども。","respondent":"伊崎子ども育成課長","answer":"例えば前月の上旬の何日までに翌月の申込みをいただいて、月々での変更は可能という形をとらせていただければと考えています。２５０円の基本料金につきましては年２回程度、また毎月の延長利用料につきましては、月々ということで引き落としをさせていただこうと考えています。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問・要望","question":"年に２回の基本的な部分になるということで、この保険料は前ですと年間で６５０円、この件について教えていただきたい。今なかなか景気がいいか悪いかは別としまして、仕事をなくしてしまうと大変な状況になると思いますので、この点は再度お願いしたいと思います。","respondent":"伊崎子ども育成課長","answer":"保険料ですが、今のところ、本年度と同じ６５０円で来年度も対応していただけるという話を進めているところです。２点目の柔軟な対応ですが、やはり一定のルールは決めた上で図れる対応をさせていただきたいと考えています。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"新しい年度を迎える子どもたちもそうだと思いますけれども、どのような形で説明会、費用も変わるということを含めてやられるのかどうか。この２点、お願いします。","respondent":"伊崎子ども育成課長","answer":"２月以降に従来のすまいるスクール保護者会を行いますので、その中でお手続き等はご説明をさせていただこうと考えています。広報のほうでは、１１月２１日号ですまいるスクール事業変更のお知らせというのを載せて周知を図りたいと考えております。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問・要望","question":"遊びの天才ですから、この教室とか勉強会、子どもたちや親御さんのほうから要望は出ているのかどうかということをお伺いしたいと思います。すまいるスクール等に関しましても興味というのでしょうか、また今回の改正にあたって何か考えられていることがありましたら説明を求めました。","respondent":"伊崎子ども育成課長","answer":"全ての学校で実施をしておりますが、委員ご指摘のとおり学校によってやっております回数や特に教室の種目といいますか、には違いがあるのは事実です。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"何点か教えていただきたいのですが、１年生から３年生までの児童で、多子についての負担軽減というのがあるのか教えてほしいと求めました。おやつなのですが、おやつはどういうものがあるのか尋ねました。","respondent":"伊崎子ども育成課長","answer":"その中で、低所得層への一定の配慮をしていくことは考えておりますが、現在のところは多子世帯への軽減というところは考えておりません。委員ご指摘のとおり時間帯が午後５時以降の配食となりますので、夕食に差し障りのない程度のものをと考えているところです。","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問・要望","question":"食べ物について、その後に差し障りのないようなおやつというものはどういうものがあるか、ぜひいろいろ工夫をしてほしいと求めました。学童保育だと夜８時まで延長が認められていたというようなことを伺ったのですが、４月の条例施行に合わせてどうなっているのかを教えていただきたい。","respondent":"伊崎子ども育成課長","answer":"特別支援に関するお子さんにつきましても、学校への登校が可能であり、医療のケアが必要でないお子さんについては全てお預かりしております。それは変更する予定はございませんので、午後６時まで、あるいは３年生以下でしたら午後７時までお預かりしていこうと考えております。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど昨年と今年で６件、６件、具体的に調査というものが行われたのかどうか。登録率と利用率を学年別に教えていただきたいのと、１日平均何人ぐらいいるのか、その辺をちょっとお示しほしいと求めました。","respondent":"伊崎子ども育成課長","answer":"ただ、子どもに影響が出ないような運営をしていくというところが、私からも職員のほうに現場できちっと対応するようにということはやっておりますし。そういったことから、来年度９００人程度のご利用があると見込んで今試算をしています。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"私は自治体としてどこまでやるつもりなのかなというところもあわせて伺いたいのですが、どうすることが適切なのかなという判断が必要ではないか。私はここのところは慎重にやるべきではないかなと思っているのですけれども、いかがか尋ねました。","respondent":"伊崎子ども育成課長","answer":"子ども・子育て支援事業計画を策定いたしましたときに、７４.３％、複数回答ではありますが。保護者の方の安心感、あとは子どもの安全ということを第一に考えまして、今後さらに現場と本課とともに突き詰めていきたいと考えております。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"２０人に１人、最低２人、ここの体制は学童保育の機能をきちんと持っているという受けとめ方でいいのでしょうか。出張もありますし、そういった中での正規の資格を持った職員の位置づけというのがどういうふうになっているのか、そこをお尋ねしたいと思います。","respondent":"伊崎子ども育成課長","answer":"放課後児童支援員を置かなければならないということが定められておりまして、放課後児童支援員につきましては、あるいは保育士の免許を持っている。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今までの１,２００円の位置づけをもう一回お聞きしたいのと、これはお母さんにちょっとニーズのところで伺ったらびっくりしていたのですね。何で３,０００円も取るのですかという驚きの声を聞いたのですけれども、なぜここは有料にするのか、もう一回改めてお伺いしたいと思います。","respondent":"伊崎子ども育成課長","answer":"それから、保険料につきましては、先ほどもご説明いたしましたとおり、６５０円という額で残す予定です。これも先ほどご説明いたしましたが、ご家庭がご利用されるということで、全体のコストの中でご負担していただく額を定めさせていただいたものです。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今の最後のところなのですけれども、午後６時以降の負担は、受益者負担ということですよね。どれくらいの収入が見込まれるのか教えていただきたいのと、その辺は納得が得られると思っていらっしゃるのでしょうか、その辺をお伺いします。","respondent":"伊崎子ども育成課長","answer":"今の見込みで、委託料が１割アップと見越して計算をいたしますと、こちらの保護者の負担が約５％となっていくと見込んでおります。先ほど申し上げましたように、こちらにつきましては、現場を含めまして丁寧にご説明をさせていただこうと考えているところです。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこを教えていただきたいのですけれども、かかるものは全てそうやって負担を求めていくのか、その辺の基本的なところを教えていただきたい。","respondent":"伊崎子ども育成課長","answer":"延長料金等を見込みまして６,７００万円ほどになると、あくまでもこれは概算ですが、見込んでおります。本当に見込みですが、約１２億円、１１億７,３００万円程度になると見込んでおります。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１７時以降に希望する子にですかね、学童保育の機能をしっかり守ってほしいと要求したときに、引き続きおやつをぜひ提供してほしいと。もっともっと現場の人の声を聞いて練り上げていただきたいなと思うのですが、ちょっとおやつのことはどうか尋ねました。","respondent":"伊崎子ども育成課長","answer":"アレルギー対応につきましては、市販のおやつの提供といえども、学校の給食での対応は非常に厳密に厳格にやっていることは伺っております。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"質問のほうは、これまでは私はちょっと調べてわからなかったのですが、要綱だったのでしょうか。それをあえてここで条例にしたのはどういう意図があるのか尋ねました。","respondent":"伊崎子ども育成課長","answer":"すまいるスクールにつきましては、平成１３年度にモデル実施をいたしまして以降、すまいるスクールの実施要綱で対応してまいりました。","id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問","question":"そういうことで、目的等をきちっと明確に示して、事業として一つ確立させたということになったのだと思います。現行の品川区放課後児童健全育成事業の設備および運営の基準に関する条例とか、それの施行規則とかについては、今回変更する必要はないのか尋ねました。","respondent":"伊崎子ども育成課長","answer":"こちらは放課後児童健全育成事業の設備および運営の基準に関する条例ですので、すまいるスクールは放課後児童健全育成事業も包含してやっております。特に今回すまいるスクールを条例化するということで、先行する条例を改正するところはございません。","id":"exchange-024"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、こうやって条例化することによって、これまでの国庫補助の関係は変わっていくことがあるのか尋ねました。","respondent":"伊崎子ども育成課長","answer":"放課後児童健全育成事業につきましては、昨年度までは東京都が財調算入ということでございましたので、特に今年の交付金はいただいておりません。","id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、都の財調ということだったのですけれども、どういう感じで算入されているのか、私はわからないので、もしわかれば、後日でも結構なのですけれども、それと、一番有効な方法で請求していくというのはどんな感じなのか尋ねました。","respondent":"伊崎子ども育成課長","answer":"今手持ちがございませんので、財調は一般財源ですので、すまいるスクールに充てられるという考え方ではございません。交付金のほうはこれから算定される予定ですけれども、その９,０００人のご利用自体を、そこはよく研究してやっていきたいと思います。","id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"質問","question":"(1)のところで、それは第８条があったとしても、先ほどの変更しないということは変わりがないのか尋ねました。","respondent":"伊崎子ども育成課長","answer":"基本的にすまいるスクールでのお受けは極力努力しておりますし、ここ２年ですが、お断りをしたというケースはございません。ただ、そこは対応を考えする場合があるということで、第８条の条項を入れさせていただいたところです。","id":"exchange-027"},{"speaker":"伊藤副委員長","kind":"確認","question":"確認をまずお願いしたい。増加する予定なのでしょうか、説明を求めました。","respondent":"伊崎子ども育成課長","answer":"平成２６年度決算の委託料が５億９,０００万円ですので、こちらの１割アップということで、約５,９００万円のアップを見込んでいるところです。ですので、このまま委託料だけアップをいたしますと、区の持ち出し、負担額が増えるということになります。","id":"exchange-028"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"その金額を教えていただきたいのと、３,２５０円ですか、それぞれ引き上げる理由づけが非常に弱い感じがするのですよ。例えば３年後、５年後と計画の見直しをしながら適切な料金を考えていくなり、いかがか尋ねました。","respondent":"伊崎子ども育成課長","answer":"今、ここに至りましての金額の設定が非常に現在と対比しまして増加感が非常に高いというところは否定できないと考えております。その中で、双方兼ね合わせまして保護者の方のご理解をいただくようにご説明はしていきたいと考えているところです。","id":"exchange-029"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"増税することには誰でも反対するわけですから、やっぱりそれはきちんと品川区全体の課題として捉えていかないと、このことだけではないと思います。おやつを提供すると同時にエピペンの注射というのですか、それはぜひ担当の職員はやってほしいと求めましたが、いかがか尋ねました。","respondent":"伊崎子ども育成課長、金子子ども未来事業部長","answer":"国の基準も緩和をされまして、医療関係者でなくても生命の危機に陥ったときには打てるということを東京都のほうの基準で確認をしております。保育園でのエピペンの対応も参考にいたしまして、職員に研修をした上で対応ができるように。これをどうすれば実施できるかということ、子ども・子育て支援新制度がスタートするにあたり、今回提案させていただいた経過があります。","id":"exchange-030"},{"speaker":"伊藤副委員長","kind":"意見","question":"それから、今部長の答弁にもありましたように、これからこういうケースがたくさん出てくると思うのですよ。どうしても高齢化社会の進展に伴って社会保険料や税負担がどんどん増えていく、バランスをとって進めていっていただきますようにお願いしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"反対します。ちょっと意見を述べたいのですが、よろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に、子どもが安心して毎日通える学童保育の機能を取り戻してほしいといった意見もいっぱいこのところ出ていますので。不十分なので反対をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"保育料が変わっていくということですが、階層別の人数というのを伺いたいと思います。今までのを伺いたいのです。","respondent":"竹田保育課長","answer":"それからＤ１９、Ｄ２０と呼ばれる世帯収入１,０００万円から１,２００万円が８％、それからＤ２１からＤ２５と言われる１,４００万円以上の収入世帯が約１０％という現状です。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、今回Ｃ階層の第１階層がゼロ、無料になるということですけれども、これは大体これからどのぐらいの割合になっていくのかを伺いたいと思います。","respondent":"竹田保育課長","answer":"もともとその階層は生活保護受給者の方ですが、０歳から２歳が０.１％、３歳が０.５％、四、五歳がやはり０.５％です。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回所得税から住民税に大もとの計算が、割り出し方といいますかね、変わったということなのですけれども、これはなぜ所得税から住民税になっていったのか、具体的に教えてほしいと求めました。","respondent":"竹田保育課長","answer":"こちらは国から示されたものですが、国の資料によりますと、国の子ども・子育て会議において審議され、了承され、国から各自治体に示されたものです。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問","question":"何で、国が変えたからそのまま変える、国が何で変えたのかというのをちょっとお伺いしたいのですけれども、お願いします。","respondent":"竹田保育課長","answer":"国からは、明確な形で今回変えた理由というのは示されていないのですけれども、考えるところ、やはり保育は各自治体の責任において実施されている事業ですので、各自治体が責任を持って課税している住民税によるところが望ましいという考えによるものだと考えております。","id":"exchange-037"},{"speaker":"石田（ち）委員","kind":"質問","question":"今までＤ１階層だった人が住民税の計算によるとＤ１階層にそのままなるのか、これをそのまま横軸で見たらいいという表ではないと思うのです。これによって階層が変わって保育料が安くなる方、そして高くなる方というのはどれぐらいいるのかというのは出されているのか尋ねました。","respondent":"竹田保育課長","answer":"試算の結果ですが、所得税から住民税に変わることによって階層が下がり、保育料が下がる方が全体の約４６％、階層が上がる方が１５％、変わらない方が３９％と試算しております。","id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、一般的なケースでいいのですけれども、いかがでしょうか。出なければ、今後出していただけるのかどうか伺いたいと思います。","respondent":"竹田保育課長","answer":"例えば、Ｄ１８階層を例にご説明しますと、世帯収入が約１,０００万円です。今は１,０００万円の例をご説明しましたが、年少、１５歳以下のお子さんが２人いるという家庭をモデルにしております。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問","question":"１,０００万円の収入の方、８.９％ということですけれども、どこになるのですか。Ｄ１８の方は改定案ではどの階層になるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なかなか１,０００万円収入、８.９％ということだったので、もうちょっと低所得世帯でのモデルケースも出してほしいと求めました。小学校３年生までで第１子、第２子と拡大があってよかったということですけれども、なぜ３年生までなのかを伺いたいと思います。","respondent":"竹田保育課長","answer":"このことから、小学校３年生を上限としたものです。幼稚園の多子減額の制度が小学校３年生までの兄姉がいた場合は減額するという制度になっておりますので、その制度と同様の制度としたものです。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"それだけやっぱりカバーされる方が増えるというのはいいことだなというふうに私は思うのです。３年生までカバーすると１,７５８人に広がるということだったのですけれども、これで区の負担としてはどれぐらいかかることになるのか尋ねました。","respondent":"竹田保育課長","answer":"今回の第１子の児童年齢の上限を在園児５歳児から小学３年生まで引き上げることによって、区の歳入は約マイナス９％減ると試算しております。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"歳入がマイナス９％というのは幾らなのか教えていただきたいのですけれども、要はカバー仕切れるのかというのを伺いたいのです。ごめんなさい、では９％は幾らかということをお願いします。","respondent":"竹田保育課長","answer":"保護者の方にご負担いただく保育料の金額が、全体で約１９億円です。それの９％ですので、約１億７,０００万円の歳入減と試算しております。","id":"exchange-043"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今の課長のご答弁に関係してなのですけれども、多子軽減の要するに根拠というのは、保育料が上がったことによって子どもがたくさんいる家庭への負担が非常に大きくなるから、それを圧縮するというような考えでということでよろしいのか尋ねました。","respondent":"竹田保育課長","answer":"税法上、年少扶養控除というものがございまして、既に税法上廃止されていましたが、今まではそれがあったものとして保育料は算出されておりました。","id":"exchange-044"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、先ほど来のお話を聞いていると、保育料を上げることによって増収する分よりも、多子減額による歳入の減少のほうが大きいということでよろしいのか尋ねました。","respondent":"竹田保育課長","answer":"多子減額に伴いまして、区の歳入は９％減を試算しております。都合マイナス１１％と試算しておりますので、今回保育料を１０％引き上げたとしても、都合マイナス１％となる試算です。","id":"exchange-045"},{"speaker":"鈴木（博）委員","kind":"意見","question":"こういうことが必要で大事だから、こういうような措置を行うのだというようなことに関して、一言まとめてご答弁をお願いしたい。二言でもいいですがとの意見を述べました。","respondent":"竹田保育課長","answer":"多子世帯に対する影響が非常に大きいということを鑑みまして多子減額を拡充しました。喫緊の課題であります少子化社会に対応した保育料にしていかなければならないというのも重要な課題ですので。","id":"exchange-046"},{"speaker":"浅野委員","kind":"質問","question":"ちょっと基本的なことをお伺いしたいのですけれども、先ほど話がありました保育料１９億円程度という話があったかと思います。別にほかの区と比べてどうかということではないのですけれども、品川区のレベルがどの程度なのかを教えてほしいと求めました。","respondent":"竹田保育課長","answer":"ちなみになのですが、川崎市、横浜市等は国基準額に対しての保育料が約６０％、７０％です。品川区につきましては、現行で、改定前の段階で約５３％というところですので、そういった自治体と比べますと低くなっているです。","id":"exchange-047"},{"speaker":"浅野委員","kind":"質問","question":"品川区の負担が二つの例として出たところからすると低いと、そういうことだと思います。この中で、この内容というのはどういう内容なのかということと、品川区として補助しなければならないことがあったのかどうか説明を求めました。","respondent":"竹田保育課長","answer":"今回子ども・子育て支援制度施行令に上限額というのが持たれております。その上限額をご説明しますと、大きく下回っている保育料になっておりますので、国の基準額に何か制約されたというようなことはございません。","id":"exchange-048"},{"speaker":"浅野委員","kind":"意見","question":"川崎、横浜と比べても、そういう意味では品川区というのは子育てしやすい区なのだなということを改めて認識しなければならないなと考えています。そういう意味で、費用だけではなくして、当然サービスも提供するという観点からこれからも取り組んでほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"確認","question":"所得税から住民税への算定方式が変わったことで階層が変わるというのがまず確認されたのと、それと保育料が大体全部１０％上がるということと。年少扶養控除のところの３３万円とか３８万円とか、こう捉えてよろしいのでしょうか、そこのところを確認したい。","respondent":"竹田保育課長","answer":"先ほどもご説明したとおり、今回の保育料改定に伴いまして、上がる方、下がる方、あるいは変わらない方、それぞれいらっしゃいます。あるいは保育の制度が持続可能な制度となるように利用者の負担の適正化と、保育園を利用しない在宅子育ての方との負担の公平性を図ったものです。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"トリプル値上げになる人もいると捉えていいのでしょうかという質問なので、それぞれ影響が違いますというのでは、実態が見えないではないですか。Ｄの幾つなのか、平均階層を教えてほしいと求めました。","respondent":"竹田保育課長","answer":"いろいろなケースを全階層に基づきまして試算したところですが、おおむね３段階以内にほぼおさまっているというふうに試算しております。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"Ｄ１１階層がいろいろ変化はあると思うのですが、２歳と５歳の子どもがいた場合、ちょっとスタッフがいらっしゃるので計算していただけますか。実際にどう変化するのかを知りたいので、ぜひ計算をしてほしいと求めました。","respondent":"金子子ども未来事業部長","answer":"こういうふうな形で当然少子化社会に対応した対策を考えました。このとおりの計算にはならないかもしれませんけれども、今までの試算として区民全体の負担としては下がる方向で私どもは計算させていただきました。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なぜ１０％なのか、マイナス１１％になってしまうので、それを何とかしたいというので１０％なのですか。なぜ１０％値上げをするのか、その辺をお聞かせほしいと求めました。","respondent":"竹田保育課長","answer":"それから、全てを救うものではないということですが、新しく制度を考える上で、全ての方に適用する制度というのはなかなか難しいと考えております。それから、１０％のことですが、前回、平成１６年度にも９％の改正をしておりますので、ほぼ同規模の改正を今回したものです。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"意見","question":"Ｄ１１が新しい算定方式になると、０歳から２歳児の場合はＤ１１、従来は３万３,８００円ですよね。５歳児がＤ１１だと、１万９,６００円、これがそれぞれまず幾らになるのか、もう一回との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"意見","question":"シンプルに４人世帯で扶養の子どもが２人、共働きで子ども２人のケースだから、そんなに委員長がおっしゃるように複雑ではないのです。基本的なものは出るとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"とても難しい税制の中で基本的な三つのところを押さえて質問しているので、今回のこの保育料値上げの大もとのところは見えてこないのですよ。私だって住民にきちっと説明しなければいけないので、この場をおかりして一生懸命聞いているので、ぜひお答えをほしいと求めました。","respondent":"竹田保育課長","answer":"先ほどもご説明したとおり、全体で言いますと、階層が下がる、保育料が下がる方が４６％、階層が上がる方が１５％、変わらない方が３９％というふうに試算しておりますので、各階層におきましても、これも同様、あるいは近似値の数字になるというふうに考えております。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"すごく単純な求めをしているのですけれども、答えないで終わってしまうのでしょうか。Ｄ１１階層がどこの階層に変わるのかを言っていただけたら、何でこんな単純な質問が答えられないのか、なぜなのか尋ねました。","respondent":"竹田保育課長","answer":"Ｄ１１階層は、約３５０人いらっしゃるというふうに試算しておりますが、変わらない方が約１１０人、下がる方が１５０人、上がる方が９０人ですので、全体の傾向とほぼ同様の傾向だと考えております。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"具体的に幾らなのか教えていただきたいのと、多子減額がマイナス９％、これが１億７,０００万円、あと値上げ１０％の増収分をお伺いしたい。平均の値上げの額というのは幾らと計算できているのか、トータルマイナス１％、この金額は幾らなのか、ちょっと数字の面で説明を求めました。","respondent":"竹田保育課長","answer":"多子減額がマイナス９％ですので、所得税から住民税に変わるのが２％ですので約３,８００万円で、あわせて２億８００万円。約１億９,０００万円ということで、その差分が歳入として減るというふうに考えております。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"意見","question":"年少扶養控除の配慮はさっき行っている自治体があると言ったのですけれども、２０１０年以来、品川区は今度の改定の前はみなしでやっていたのか、やっていないのか、これをやることでの負担をどう考えているのか、ちょっと聞かせてくださいとの意見を述べました。","respondent":"竹田保育課長","answer":"現行までは年少扶養控除は廃止されておりましたが、みなしで現在も年少扶養控除を行っております。今後につきましては、年少扶養控除ではなく、より手厚い多子減額制度に移行していきたいと考えております。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回の改定に伴って問題は、国の設定する保育料徴収基準が高すぎていること、あと新制度実施による新たな保護者負担はやめるべきであると思います。プラスの面もしっかり考えて捉えていただきたい、受益は親が負担すべきだという考え方は間違いだと思っていますので反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"}]},{"id":"topic-02","title":"第６７号議案、平成２７年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第６７号議案、平成２７年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっとその辺を教えていただきたいのと、国の支出金と一般会計のところというのはどういうふうに違うのか、国のところがありますよね。国支出金と一般財源、この出どころの違いというのはどういう項目が違って、そういうものになっているのか、ちょっとそこのところを説明するよう求めました。","respondent":"竹田保育課長","answer":"例えば３歳児にかかる保育士の配置基準を実施する施設に加算する３歳児配置改善加算とか、それから自治体が認める第三者機関による評価を受信し。歳入につきましては、公定価格につきましては、国庫支出金よりの歳入となっております。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"確認","question":"すまいるスクールの運営費追加分というのは、午前中の条例のところとかかわってくるシステム改修というか、新しいところですね。ちょっと確認をしたい。","respondent":"伊崎子ども育成課長","answer":"今回の利用料の改定に伴う、徴収に伴うシステム改修です。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"小学校２９校、平成２８年度導入ということで先行して行っていくのですけれども、どういうところを変えながら先行してやっていくのかという中身をちょっと教えてほしいと求めました。","respondent":"村尾教育総合支援センター長","answer":"いわゆる拠点校と呼ばれている通級学級を現在設置している４校と、いわゆる３７校、全小学校で実施をする予定になっております。教室の間仕切りであったり、また壁の塗り替え等の工事費、４月からは無事全ての学校で特別支援教室が運営できるような準備を今進めているところです。","id":"exchange-063"},{"speaker":"浅野委員","kind":"質問","question":"２２ページの、あとやっぱりシステムですから、そこら辺の概略日程と無事にスタートするための手順などを簡単に教えてほしいと求めました。","respondent":"伊崎子ども育成課長","answer":"それにつきまして、業者のほうに正式に契約をするということから、システムの開発をしていただくようになります。テストに入りまして、職員の研修も含めて２月からはでき上がるような形にもっていくということが今の予定です。","id":"exchange-064"},{"speaker":"浅野委員","kind":"確認","question":"必ずバグというものは発生すると思うので、ソフトのほうまで確認をするということで、スタート時にエラーのないようにしてほしいと求めました。具体的にどういう形で教室というのは、イメージとしてどういう教室なのかというのをわかりやすく教えてほしいと求めました。","respondent":"村尾教育総合支援センター長","answer":"基本的な考え方については、まさに個別対応というのがまず基本的になります。１対１対応ということで、教員がその子どもに対して学習を進めていく、基本的にはそういう形でできるような教室整備を今進めているところです。","id":"exchange-065"},{"speaker":"浅野委員","kind":"質問","question":"そういうものが出てくると子どもたちに対してどうなのかなというのがちょっと気になったもので、広さというのでしょうか、新しく整備する場所を子どもたちが快適に使っていただけるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"高橋（し）委員","kind":"確認","question":"２２ページの確認で、現状でも認証保育所運営費等助成は１億円ですか、都のほうのそういった手当みたいなものがあるのでしょうか。逆に認証保育所がこうして一般財源をこれだけ投入して保育の需要に応えているということをご理解いただくためにも教えてほしいと求めました。","respondent":"竹田保育課長","answer":"認証保育所については、財調の中で算定されるというふうに聞いておりますので、今回の補正には歳入としては載せておりません。","id":"exchange-067"},{"speaker":"伊藤副委員長","kind":"質問","question":"それに対して、例えばどうしても物理的な制限で間仕切りをやらざるを得ないところもあるでしょう。そういうところにさえ入らない子どももいらっしゃる可能性もあるわけですから、一概に子どもにとって、改めていかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"子どもたちにとってはさまざまなやり方ができるようにということで、本区では巡回相談員というカウンセラーをまず配置しております。形態、場所がいいのかということも十分考えながら、その子に応じた方法を進めていこうと考えているところです。","id":"exchange-068"},{"speaker":"伊藤副委員長","kind":"質問","question":"いろいろなタイプのお子さんがいらっしゃる中で、要するにこの学校では、場合によっては間仕切りをせざるを得ないことがあるわけではないですか。そういうときにどうするかということが実はとても大きな課題ではないかと思うので、もう一言お話をほしいと求めました。","respondent":"村尾教育総合支援センター長","answer":"まさに間仕切りといっても、固定型では当然考えていません。隅っこでやりたいという子どももいますので、その辺は可動性のものを十分考えて、教室の整備を進めているところです。","id":"exchange-069"}]},{"id":"topic-03","title":"平成２７年請願第２６号、認可保育園の更なる増設で、来年４月の待機児ゼロを求める請願","agenda":"平成２７年請願第２６号、認可保育園の更なる増設で、来年４月の待機児ゼロを求める請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回一般質問等でも触れられていたのですけれども、改めて申込み、申請について伺いたいのですが、昨年は何人申し込まれて、そのうち何人が０歳から２歳児かという数字を教えてほしいと求めました。","respondent":"今井待機児童対策担当課長","answer":"今年度の４月１日現在ですが、申込者数が０歳から５歳までで２,７９９人、１,０１５人です。入園の申込者数ですけれども、２,７９９人のうち、０歳から２歳の申込者数の総計が２,４１１人です。","id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問","question":"やっぱり０歳から２歳の申し込みがほとんどだなという状況ですけれども、一般質問等でも昨年同月の９月現在の数を伺いました。お母さんの点数を両方あわせると４０点、いろいろ加点を含めて４２点でも４３点でも入れないと、そこら辺の考え方を伺いたいと思います。","respondent":"竹田保育課長","answer":"保育園入所を必要とする世帯は、実情は千差万別でありまして、社会通年上合理的というふうに解釈される範囲内で基準を定めているところです。基準につきましては、随時、社会情勢に合うように見直しを行っているところです。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問","question":"でも１点を争う今の状況のもとで、認証の設備は認可よりも整っているというのを知っていても１点高い認可がいい、こうこういう状況を伺いました。それで、やはり、こういった状況をしっかりパパ、ママたちにも伝えていくべきだと思うのですけれども、いかがか尋ねました。","respondent":"竹田保育課長","answer":"利用調整の判断基準ですけれども、申込者数が入園予定者数を上回った場合に優先順位をつける必要があります。いろいろなご意見があることは承知しておりますので、随時、時代に合うように見直しを行っているところです。","id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"あなたのところは１点高い、ではうちはどうやって１点高くしようと、こういう状況で本当に健全な子育てが進むのだろうかということで心配になります。そして、どうやったらでは入れるのだろうかというお母さんたちの疑問、その辺はいかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"前回の委員会でもご報告させていただきましたとおり、今回開設の予定や計画について早目に保護者の方に周知するために報告しています。","id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"保育関係者の方から伺いましたけれども、近くの公園をどのように利用しているかというアンケートをとっているというふうに伺いました。何の目的で、そして保育施設全園に対してされているのか、認可だけなのか、そういったところをちょっと伺いたいと思います。","respondent":"今井待機児童対策担当課長","answer":"公園、児童遊園等における保育所の設置が国家戦略特区で認められたこともあり、補正予算でその検討を進めるということは申し上げました。このアンケートの調査につきましては、区内の認可外も含めて全ての保育・教育施設にお願いをしています。","id":"exchange-074"},{"speaker":"石田（ち）委員","kind":"質問","question":"場所とりのために９時半から公園に職員が行くという状況を伺ってびっくりしたのですけれども、それだけの状況、そこでは小さい子たちは遊べない。そして、増設をしていくという願いは、本当に保育園を運営している側も待っているのではないかなというふうに思うのですけれども、いかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"以前からご説明申し上げていますように、これは代替の場所が認められているものですので、今後も開設の際の必置条件にする考えはございません。それぞれの目的、または年齢に応じて活用していただいて、適切に保育が行われているものと考えております。","id":"exchange-075"},{"speaker":"浅野委員","kind":"質問","question":"認可保育園の増設、そしてまた園庭の件の請願だと思います。来年の４月はどのぐらいの想定数になっているのか、あと平成２８年度以降について、または想定があれば説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"先ほどご説明しました７１１人のうち、認可保育園が広町の大規模保育施設も含めまして今６園全部で６７１人、認可保育園で開設する予定です。","id":"exchange-076"},{"speaker":"浅野委員","kind":"質問・要望","question":"今後の、長期的というのは半長期的でしょうか、その狭間の中でこれからもいろいろと検討しながら努力をしていってほしいと求めました。住民の方の意見というのは非常に重要だと思いますけれども、反対される理由などを教えてほしいと求めました。","respondent":"今井待機児童対策担当課長","answer":"２年ほど前から池田山の地区で開設を進めていた事業者、昨年の２月でございましたけれども、企画提案を取り下げるということがございました。やはりゼロベースで建ててまいりますので、近隣の方へのご説明というのは大分事業者のほうも複数回説明するようにしています。","id":"exchange-077"},{"speaker":"浅野委員","kind":"質問・要望","question":"隣接しているというのでしょうか、園庭がある園というのは、どのぐらいあるのかというのを一つ教えてほしいと求めました。それとあと、近くの公園とか、そういうところを利用しているところが何か所ぐらいあるのか教えてほしいと求めました。","respondent":"今井待機児童対策担当課長","answer":"３１園中の２３園が敷地内のみでの屋外遊戯場の面積を満たしておりません。以上が私立保育園の状況です。","id":"exchange-078"},{"speaker":"浅野委員","kind":"質問・要望","question":"いいところがあって、例えば１０年でも貸してもらえるとか、そういうところなども探してみてはどうかと思うのです。さまざまな努力をしながら、これからも区民の親御さんの要望に応えられるような努力をまたぜひともしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問","question":"来年４月に３００人を超す申請がありそうだということで、あと何人分つくったらとりあえず来年４月に向けて入り切るようになるのか、今一生懸命やられているのか説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"先ほどご説明申しましたとおり、認証保育所１園ということで、あわせて７１１人の受入枠の拡大を考えております。先ほど委員ご指摘のとおり、やはり０歳から２歳のところが今後入園の申込みの大半を占めますので、まだ数等の算出はしておりません。","id":"exchange-080"},{"speaker":"飯沼委員","kind":"質問・要望","question":"仕方がないと考えているのか、諦めていただきたいと思っているのか、申しわけないと考えているのか、その辺は率直にどうなのですか。これでは請願を苦労して出されている方は、とても納得がいかないと思うのですがいかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"冒頭に請願項目のご説明でも申し上げましたとおり、子ども・子育て支援事業計画、一定平成２８年末には待機児童が解消するという推計を出しました。","id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いない状況をどう考えているのですか。これから数年間、一生懸命やっていますが、どんどん増えているので間に合わないのですということで乗り切るおつもりなのか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"それから認証が２園という形で進めておりましたので、保育の受入枠は４月当初は満たせなかったというのが今年度の待機児童数の増加の大きな要因です。","id":"exchange-082"},{"speaker":"飯沼委員","kind":"質問・要望","question":"このままいくのでしょうか。でも、間に合わないのですという姿勢でずっといくのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ご意見を伺いたいと思います。いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"伊藤副委員長","kind":"意見","question":"合計４,４９７人、なぜこの数字を出してきたかといいますと、わかりますか。わからなければわからないでいいです、急な話だからとの意見を述べました。","respondent":"今井待機児童対策担当課長","answer":"いわゆる平成２７年４月から子ども・子育て支援制度で保育の認定とともに入園申請を同時にやっていただいておりますので、２,７９９人がいわゆる保育認定を受けられる子、保育サービスの認定を利用できるというふうに区も確認した数です。","id":"exchange-085"},{"speaker":"伊藤副委員長","kind":"質問","question":"ここから先の展開ですけれども、ではこの４,４００人を受け入れるための保育園をつくらなければいけないことになる。これが仮に４４カ所増えた場合には、毎年どれだけのお子さんが入りますかということをわかれば説明を求めました。","respondent":"今井待機児童対策担当課長","answer":"２,７９９人の申込みのうち、バランスよく開設していくということが今後の人数が減ったときの対応も含めて大切なことだというふうに思っております。副委員長ご指摘の開設だけではなく、運営費の面も含めまして今後検討していく大きな課題だというふうに認識しております。","id":"exchange-086"},{"speaker":"伊藤副委員長","kind":"質問","question":"それを建設するコストと土地代と建物代、それからその後の５年、１０年、２０年先のコストをどう考えているのか。財政負担からすると、それから将来の財政負担も少なくなっていくと思うのだけれども、その点の考え方はいかがか尋ねました。","respondent":"今井待機児童対策担当課長","answer":"やはり、０歳児が、１００人あけても、０歳児はやはり６人か、７人、８人ぐらいしか預かることは難しいです。５歳児というのは、一定バランスよく小規模と認証を開設することで認可保育園の受け皿というのはきちんと配置できるというふうに考えております。","id":"exchange-087"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"やっぱり、先ほど来出ているけれども、都心部で土地を求めるというのは大変なことなのですよ。一般財源の投入ですから、ぜひ理解していただきたいのは、その恩恵があるからこそ保育園は見かけ上安くなっているわけなのです。","respondent":"金子子ども未来事業部長","answer":"そういう意味では、私どもは総合的に待機児童対策を進め、認可保育園、またその他の保育施設をつくって、待機児童ゼロは目指してまいります。","id":"exchange-088"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"多彩な待機児童ゼロを目指す施策というものを私たちは非常に強く求めておりますので、園庭に関しては、園庭はあるにこしたことはないのですが。よって、今回の請願に関しては不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"浅野委員","kind":"質問・要望","question":"やはり今の品川区の土地の利用状況からすると、かなり厳しい部分はありますけれども、これについても努力は継続して行ってほしいと求めました。そういう意味からいたしまして、願意に沿いがたいということで不採択をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地域に公園をつくることだって、誰がそんなに阻むのですか。お金が足りないのですか、現状では十分あると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"大倉委員","kind":"質問・要望","question":"そうした中で、さまざまなそうした多くの制度を活用して、待機児童ゼロになるようにこれからも努力していただきたいと考えています。そういった意味でも、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ゼロにはなっていませんが、さらに総合的に現在も進めているということですから、認可保育園に限らず総合的に進めていっていただきたいという形です。そういう意味において、この請願に関しては１、２とも願意に沿いがたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"}]},{"id":"topic-04","title":"を行います。 (1)専決処分の報告","agenda":"を行います。 (1)専決処分の報告","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"報告第２５号なのですが、本人が住んでいないということで、ちょっと聞き漏らしてしまったのですが、不現住、この言葉の説明をしていただきたい。","respondent":"廣田子ども家庭支援課長","answer":"私が責任を持ってお支払いをしますということで、連帯保証人と和解が成立したので、お支払いいただくということで和解に至りました。","id":"exchange-094"},{"speaker":"飯沼委員","kind":"質問","question":"手を尽くしたというところなのですけれども、行ってみたら、本人ではなくて、さっきの母親がはっきりしないと、母親が借りていて、保証人ですよね、いながら、本人が後から返すというか、第２６号ですか、こういうのはどういうことなのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"借りている認識がなく、大人になってから事情を話すとおっしゃるとおりということで、払える能力があれば説明して納得していただいて和解をするということも多くあるケースです。","id":"exchange-095"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/184577?Template=document&Id=4864#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":68383,"voices":247}},{"id":"h27-20150924-5","meetingId":"h27-cm09","date":"2015年9月24日","dateIso":"2015-09-24","committee":"総務委員会","time":"午前１０時００分～午後 ２時１８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件整理しています。","topics":[{"id":"topic-01","title":"では、(1)の第６８号議案からの審査でありますが、会議の運営上、審査の順番を入れ替えます。 まず、(6)第８１号議案 しながわ中央公園拡張整備工事請負契約","agenda":"では、(1)の第６８号議案からの審査でありますが、会議の運営上、審査の順番を入れ替えます。 まず、(6)第８１号議案 しながわ中央公園拡張整備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"ヘリポートのところが相当なトン数に耐えられるという透水性アスファルト舗装工でやっているのですが、その周りは草地ですよね。あくまでここのアスファルト舗装にしているところだけが頑丈だというのは、それでいいのかなという疑問を感じたのですが、それだけ説明を求めました。","respondent":"多並公園課長","answer":"それをもとに、今回草地とアスファルトで構成してつくったところです。特にこのアスファルトでつくったところの考え方としては、円滑に動線が図れるだろうところを中心に、このような感じとご理解いただければと思います。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"そういうときに、重機、それからトラック等いろいろ運ぶようなときもあるのかなとちょっと思ったもので、質問をさせていただきました。中身はわかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問","question":"この１９ページの平面図を見ますと、図面ですから北側のマークがあるのですけれども、それをちょっとお聞きしたい。こことあわせて、今回はそれが入っていないのか、その辺について説明を求めました。","respondent":"多並公園課長","answer":"１点目の方向のお話からですけれども、そういうところが一番大きいのかなと、方向としてはそういうのを気にしたところです。関連課といろいろ協議しまして、来年度の予算を整理する中でそういう形にさせていただきたいというのが、今のところの考え方です。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"お手洗いが３基と、それから災害用トイレ穴が４穴とあるんですけれども、災害の際においてはヘリポート等々も言われています。トイレをもう少し多くつくることはできないのかなと感じるのですが、なぜこの数字で、もう少し増やせないものなのか尋ねました。","respondent":"多並公園課長","answer":"災害時も含めると、バックアップもそこの中でできるのではないかということで、そこの中で必要最低限という形で今回３基と。もし仮設住宅ができた際を想定して計算をしたところ、現在のところその４穴でいいのではないかということで、計算上出てきた数字です。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問・要望","question":"一点教えていただきたいのですが、ちょっと地図でよくわからないのですけれども、この北側の接道はどのようになっているのでしょうか。北のほうからもこの公園に入ることはできるようなつくりになっているのか尋ねました。","respondent":"多並公園課長","answer":"出入口につきましては、工事ではこの北の一番端っこのところに階段を設ける予定になってあります。そのほかは、今の北側のところから西のほうへかけて区有通路２.７ｍというものがございまして、三方向から入れるような形でつくっているところです。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"厳密的に公園は、ここの中小企業センターを挟んだ右と左の公園はどのような違いが出てくるのか、あるいは同じ扱いなのか。あるいは何か非常時の場合、公園の用途の違いがあったがために不都合が生じることがないのかどうか、そこのところを説明するよう求めました。","respondent":"多並公園課長","answer":"災害時はもちろん連携する形と考えておりまして、やはりヘリコプターが降りるときには、人が立ち入るのは非常に危険なところもあります。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"厳密的にやはり工事をやるときは、何か用途の許可を出すのではないですか。何かあったときにその許可の範疇が違うがために使えなかったり、使えたり、そういう事態が起きないのでしょうかということなのです。","respondent":"多並公園課長","answer":"防災公園の届け出はありませんので、利用上は大きな障害になるような位置づけ、許可等はないと考えています。ただ、また防災上の安全等を考えながら管理をして、運営上の必要性については公園管理者としては考えていかなくてはいけないと考えているところです。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"これはもうごっちゃになってしまうという解釈でいいのですか。ここのところだけどうもいろいろな名称とか、そこのところはちゃんと整理できているからやっているのでしょうけれども、ちょっと説明をお願いします。","respondent":"多並公園課長","answer":"その防災時の考え方というのはその時々でなるものであって、いわゆる一般の公園としての位置づけというお話をさせていただきました。","id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"そのゾーンがあることによって、本来公園としての機能の、例えばこっちはいいけれどもこっちはだめだよということは生じてこないということで理解をしていいのか尋ねました。","respondent":"多並公園課長","answer":"今の委員のご指摘のとおり、おっしゃるとおりです。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"電源というのは、この計画ではどういうふうに確保されているのか、いないのかを伺いたいです。ある意味そこから逆算したこういう図面とか配置になっているのか、災害時の運営プランがどうなっているのか等も伺いたいと思います。","respondent":"多並公園課長","answer":"１点目の電源の件ですけれども、非常用の電源がとれる場所ということで、２カ所設ける予定にしています。そのときにその事態事態でどのような形でも対応できるようにということで、そういう事態を想定して、今回の整備内容としたものです。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり一定の段取りを示す中でないとうまくないと思うのですけれども、その辺についてはどのようにお考えなのか伺いたいと思います。災害用トイレはマンホール直結型というのは先ほど伺ったのですけれども、これは例えば水が断水したときでも、そこをご説明ほしいと求めました。","respondent":"多並公園課長","answer":"そちらのほうに今回２カ所を配置していくような形で考えているので、区で何かあったときに使えるような形ということで設置しているものです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"確認","question":"停電が起きたときの電源の確保として２カ所あるという前提で先ほどお話があったのか、そうではないのか、そこで大きく前提が崩れてしまうので。そういう意味での２カ所の電源ということだったのか、そこだけちょっと確認したいと求めました。","respondent":"多並公園課長","answer":"やはり災害時に使うことを想定して、先ほど私がイベントと言ったのは通常時の話であって、災害時はもちろんです。もう一つが、非常用電源も倉庫の中に配備して、あらゆる形で電源をとるような形の備えはしています。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問・要望","question":"今の電源の話がよくわからなくなってしまったので確認させていただきたいのですが、町の中としては停電しているかもしれないわけですよね。街中は停電してもそのライトはつきますよとか、そのような形になっているかどうか、お伺いします。","respondent":"多並公園課長","answer":"先ほどちょっと現地でもご説明したのですけれども、ライトは通常の電気のものと、スポットライト式というのは本当に限った形でつけてあります。スポットライト式のほうが災害用ということでつけているものですので、つくという形の考え方で設計しているものです。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"先ほどちょっと現地でもお話しさせていただいたのですけれども、トイレの話ばかりですみません。契約の金額が決まっている中で、そういうこともこれから検討が可能なのかどうか、ちょっと説明を求めました。","respondent":"多並公園課長","answer":"今の内容ですと、ベビーシートやベビーチェアについては設置する形になっておりますが、現在のこの中では想定していない形になってあります。そういういろいろなタイミングを見ながら、そういうご意見をお伺いしましたので、整備については考えていきたいと思っているものです。","id":"exchange-014"},{"speaker":"吉田委員","kind":"意見","question":"意見です。契約金額がちょっとどうしても高くなるということはあると思うのですけれども、考えていただけるといいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり災害時のこの公園の運営について、事前に計画を立てて区民に知らせて、しっかり利用できるようにするしくみが大切だと思いますので、その点については改めて要望して、公園整備については賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-02","title":"に戻りまして、第６８号議案 品川区行政委員会の委員の報酬および費用弁償に関する条例および品川区監査委員の給与等に関する条例の一部を改正する条例","agenda":"に戻りまして、第６８号議案 品川区行政委員会の委員の報酬および費用弁償に関する条例および品川区監査委員の給与等に関する条例の一部を改正する条例","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"現に実費相当額もいただかないという議員もいるわけですから、その辺も考えて、今後の課題、やはり検討はするべきだと思います。このたびの条例案については賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"実費相当額というのが具体的にどのように運用されるのか伺いたいのですけれども、ここで言っているいわゆる実費相当額というのはどういう計算方式になるのか、そこを伺いたいと思います。","respondent":"江部総務課長","answer":"３委員会のことですので、基本的には区議会議員の条例の運用を尊重しながら、いわゆる交通費という考え方をベースに進められていくと。まだ確定ではないと思いますが、それぞれの委員会の中で考えていくものと思います。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"単純にわからなかったのでそこのしくみを教えていただきたいのと、考え方としては、議会の運用に準ずると思っているということなのでしょうか。今回は委員が区内を、旅行をする場合の費用を弁償するという、ちょっと文言が変わったところの理由をご説明ほしいと求めました。","respondent":"江部総務課長","answer":"これを受けまして、それぞれの委員会が規則を持ってありますので、それは各委員会で規則を変えていくという形となります。今回２,０００円から実費相当額に変わるものでございまして、区議会議員同様３,０００円ということで、出張手当は同じようにという形です。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"先ほど現地でも少し伺ったのですけれども、地域交流スペースということになっているのですが、防災拠点型ということについて、そこの設備を大きくすればまた契約の中身が変わってきてしまうと思うのですけれども、具体的に契約上はどの辺までの設備がその契約に入っているのか伺いたいと思います。","respondent":"立川経理課長","answer":"車いすに対応した専用のものを設けるだとか、またトイレの仕様がいわゆる要援護者が使いやすいようなトイレを設けるといったような基準がございまして、この地域交流スペースをつくると聞いているところです。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"車いすが対応できる仕様というのは、具体的に言うといわゆるバリアフリーというか、車いすでできるということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"吉田委員","kind":"質問","question":"先ほどの午前中からの流れでトイレのことが気になってしまうのですけれども、防災拠点にするという以上は、その辺のトイレについてもだれでもトイレはもちろんのこと、何かそういう被養護の、介護とかを必要とされる方が使い勝手の良いことになっていると理解していいのか尋ねました。","respondent":"小林施設整備課長","answer":"はい、そのとおりです。バリアフリーのだれでもトイレも地下に持っておりますので、そのとおりです。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"今日現地を視察しまして、外構工事で、全部ではないのですが、コンクリートパネルで埋めて壁をつくっていたところが見えたのですが、一般論から言うとコンクリート打設の工事で持っていくと思うのですけれども、あれはどういう理由からなっていたのか尋ねました。","respondent":"小林施設整備課長","answer":"これはすべてに該当するかというと、敷地の条件によって選定ができるものとできないものがあります。あそこについては、ちょっと前面道路の目黒通りからストレートに入ってこられるというメリットがあって、そういう工法を採用しております。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"近隣の方からすれば、そこに新たに大きいビルが建つようなものですから、近隣とも仲良くやっていってほしいと求めました。この施設はやはり品川区としては特に重要で、国民、特に区民にとっても大切な施設だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"工期が平成２９年３月３１日ということですけれども、そこをご説明いただきたいのと、そこの今の見通しを伺いたいと思います。少し時間がかかっているようにも思うのですけれども、その辺がちょっとどういう状況か、ご説明ほしいと求めました。","respondent":"小林施設整備課長、立川経理課長","answer":"適正な工法をもとに適正な工期を算出して、今回、平成２９年３月いっぱいということになっております。それと、開所につきましては、平成２９年７月を予定していると聞いております。 土地の取得から開設まで、概ね予定どおりです。","id":"exchange-025"},{"speaker":"大沢委員","kind":"質問・要望","question":"３ページの（仮称）上大崎三丁目高齢者福祉施設等新築工事のところでの辞退、設備等々に関しては入札が行われているけれども、ここのところの全体的なもので、これが辞退になった原因というのがもしありますれば、ちょっと教えてほしいと求めました。","respondent":"立川経理課長","answer":"辞退理由につきましては各社それぞれありますけれども、いわゆる配置技術者の手配がつかない、また積算が合わない、そういった各企業の事情です。","id":"exchange-026"},{"speaker":"大沢委員","kind":"質問","question":"契約の不調が続いている話を聞いている中で、このところは各企業の台所、いわゆる作業上の理由かと思いますけれども、そこらに関して、ここのところでは人件費の高騰、材料費の高騰、いろいろな要因があるので、これに関してはそれは当てはまっていないような考え方でいいのか尋ねました。","respondent":"小林施設整備課長","answer":"今回、この積算についても十分検討しておりまして、直近の単価表をもとに積算をしておりますので、委員ご心配の不調関係につきましては、今回１社の落札があったということで、ほっとしています。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問","question":"強度やコストの面では何か違いがあるのかということを教えてほしいと求めました、それが１点です。平成２９年７月開所予定ということだったのですけれども、その間のざっくりしたスケジュール、そういったことも含めて教えてほしいと求めました。","respondent":"小林施設整備課長","answer":"大きなところを説明しますと、一番最初は平成２６年６月３日から計画説明会を行いまして、５回ばかり事業計画説明会は行っております。今回の擁壁の工事につきましては工事説明会、これは今年の５月の連休を挟みまして２回行っております。","id":"exchange-028"},{"speaker":"あべ委員","kind":"質問・要望","question":"少しずつその工期ですとか単価水準とかが変わってくるとは思いますが、これは要望です。もう一つ伺いたいのは、障害者も加えて考えていらっしゃるのかどうか、それをお伺いしたいと思います。","respondent":"小林施設整備課長","answer":"こちらの建物は福祉避難所という位置づけになっておりまして、避難所および二次避難所の避難者と避難生活を送ることが困難な要介護者を保護する施設という位置づけになっておりますので、そちらのほうに当てはまればよろしいかなと思います。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問・要望","question":"一つ一つ細かく確認することはしませんけれども、今のご答弁からはするわけですけれども、それはご答弁いただけますでしょうか。もしそうでなければ、今からでもできるだけのしつらえはしてほしいと求めました。","respondent":"小林施設整備課長","answer":"間違っていたら申し訳ないのですけれども、ここら辺について詳しく私のほうはわかりませんけれども、福祉避難所というのは要介護者を保護する施設というもので聞いております。","id":"exchange-030"},{"speaker":"あべ委員","kind":"質問・要望","question":"それに基づいて、今後いろいろな内容を見たときに要望していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"はっきりと拝見させていただいたことがなかったものですから、大変よくわかりやすくて、最新の工法も教えていただいてありがとうございました。今回４議案一括議題ということでまとめて伺いたいのですけれども、例えば、そういうのは最近はもうだいぶ落ち着いたという感触なのか尋ねました。","respondent":"小林施設整備課長","answer":"今の質問でお答えしますと、業者とちょっとコミュニケーションしていますと、やはりかなりまだまだという感じだと思います。職員についてはいろいろと大変なところはあるのですけれども、そういう配慮をしながら、一つ一つ落札してもらうような入札の努力をしています。","id":"exchange-032"},{"speaker":"あくつ副委員長","kind":"質問","question":"積算が合わないとか技術者の配置が間に合わないとかということもあるのではないでしょうかというような、先ほど施設整備課長も１社が落札してくれてほっとしたというのは本当の心情、今後も機動的に対応されるということでよろしいのか尋ねました。","respondent":"立川経理課長","answer":"スライド条項の適用に関しましては、国・東京都等の動向を見まして、適用するときは適用するです。","id":"exchange-033"},{"speaker":"吉田委員","kind":"意見","question":"それから防災拠点が本当に要介護の方たちに有効な形になるように、だれでもトイレも含めて検討していただくことを前提として、賛成いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"}]},{"id":"topic-03","title":"第８２号議案 土地の売払い","agenda":"第８２号議案 土地の売払い","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"この土地はようやく売却ができたというのはほっといたしました。ちょっと参考までに教えていただきたいのですけれども、この購入された相手方というのは、ここは何かを建てられるのか尋ねました。","respondent":"立川経理課長","answer":"こちらは森ビル、森トラストグループの会社でございまして、事業としましてはコンサルティング事業を行っているということです。取得後はグループ会社の保養所兼ゲストハウスを現在のところ予定していると伺っております。","id":"exchange-035"},{"speaker":"あべ委員","kind":"確認","question":"確認なのですけれども、そういう個人的に自らのものを建てるのは構わないというような括りだったのですか。営業はだめということには適合しているから、売却できたという理解でよろしいか尋ねました。","respondent":"立川経理課長","answer":"ただいま委員からお話がありましたとおり、いわゆる営利目的以外の利用ということで、一応こちらはいわゆる別荘地内にありますので、東急不動産のほうでその辺、各所有者と覚書を交わしまして、いわゆる営利事業を禁止しているという土地です。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"今の時点でどのように思っているのかというところを伺いたいのですけれども、その辺、今振り返ってどうなのかというのを一言伺いたいと思います。","respondent":"立川経理課長","answer":"この考え方というのは、需給の状況等を考慮して、不動産鑑定士による鑑定評価額を２０％の範囲内で修正することができるという国の規定があります。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問・要望","question":"それで、今後品川区として、また何か区の外に不動産を求めていくような考えがあるのかどうか、そういう可能性はあるのかどうか。そしてそういうことがもし行われる場合には、ちょっと整理していただきたいなと思っているのですが、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"今、今もこういった保養所の関係も難しい現実があるというのは認識をしているところです。そういったところを検討しながら、どういう方向に持っていくか、いろいろなものを検討しながら検討を進めなくてはいけないのだろうと思います。","id":"exchange-038"},{"speaker":"あべ委員","kind":"質問・要望","question":"不動産に関しては、それがなかなか動かせずに何十年も区の財政にマイナスを与えてしまうことも多々ありますので、ぜひ慎重に今後も検討していただく。もしすることがあっても、慎重になっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]},{"id":"topic-04","title":"平成２７年請願第２２号 固定資産税及び都市計画税の軽減措置の継続","agenda":"平成２７年請願第２２号 固定資産税及び都市計画税の軽減措置の継続","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"昭和６３年から３０年近くずっとこういう形で、請願は１年ごとの延長ということになっているということ自体が、今もないままなのか尋ねました。","respondent":"黒田税務課長","answer":"全国的な状況が必要であろうと考えておりますので、現時点においては毎年度都の条例の中で定められているというのが現状でございまして、この件について税制が改正されるというふうには伺っていないものです。","id":"exchange-040"},{"speaker":"あべ委員","kind":"質問","question":"では、例えばその条例のほうで、１年ごとではなく３年とか、そういう話も全く出ていないのか尋ねました。","respondent":"黒田税務課長","answer":"都道府県なり市町村なりがその税制改正の影響を見込んで、どのように改正するかというようなことがあろうかと思いますので、現状では１年ごとにそういった国の制度改正をにらみながらというところではないかなと考えています。","id":"exchange-041"},{"speaker":"大沢委員","kind":"質問・要望","question":"質問というか、ちょっと教えていただきたいところで、固定資産税、これは議会でも意見書を出しましたけれども、地方税の一部国税化という話と、この固定資産税の軽減措置には、相関性か何かがあるのかないのか。","respondent":"黒田税務課長","answer":"税制改正が検討されるですので、いわゆる地方の歳入全体という大きな意味では、関連するかなと考えております。","id":"exchange-042"},{"speaker":"本多委員","kind":"意見","question":"結論を出すべきだと思います。内容につきましては、採択を主張しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"中塚委員","kind":"意見","question":"請願第２２号、請願第２３号ともに結論を出すべきということと、内容は理解できますので、採択するということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"}]},{"id":"topic-05","title":"平成２７年請願第２５号 外国人の人権が十分尊重されることを求める意見書の提出に関する請願","agenda":"平成２７年請願第２５号 外国人の人権が十分尊重されることを求める意見書の提出に関する請願","exchanges":[{"speaker":"あべ委員","kind":"意見","question":"あるいは差別を扇動するというようなより積極的な害悪をもたらすものとして、これは絶対にやはりこの日本の中で行われるべきことではない。そういった意味からも、後ほどまた改めて聞かれるとは思いますけれども、この趣旨を理解し賛同したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"この請願に既に５つの会派の区議会議員が紹介議員になっておりますけれども、採択できることを強く望みたいと思います。具体的にはどういう取組みがあるのか、そこだけ伺いたいと思うのですけれども、区の現状の取組みや今後の取組みを少し具体的に伺いたいと思います。","respondent":"提坂人権啓発課長","answer":"区でもそれに沿った形で、積極的に進めたいと考えています。外国人の方の人権課題を含んだ啓発ＤＶＤやビデオの貸出しを行っております。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"これは当然貫いていただきたいと思うのですけれども、こういう請願が寄せられているわけですから、今後区としても取組みの具体化を強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"先ほど、人権啓発課長からも区の取組みということで伺いました。例えば法による規制を行うなど、適切な対処に取り組むことを強く求める勧告を行っているという中で、地方から声を挙げていかなければいけないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"吉田委員","kind":"意見","question":"ですので、それは格好悪いんだというような意識を醸成するように、私たちも区議会議員として取組みを一緒にやっていきたいと思います。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"本多委員","kind":"質問・要望","question":"本日結論を出してほしいと求めました。考え方につきましては、こういう事態に対しましてこの総務委員会で採択をし、国に意見書を出す必要があると考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"意見","question":"今日、これはやはり地方から声を挙げていくべきだということで、賛成です。結論を出すということで、採択を主張いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"中塚委員","kind":"意見","question":"あわせて私が大事だと思うのは、１９５２年に選択権を認めることもなく、日本政府が一斉に剥奪した歴史があります。我々政治家、議会が果たすべき役割・責任はとても重いと思いますので、採択ということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問・要望","question":"むしろ社会にとって活性化につながるという、活力の源であるという積極的な価値観というのも、ぜひ地域の中で発信していただきたいなと考えています。ただその外国人の人権を侵害してはいけないという以上に、あわせて地域の中で発信していただきたいということをつけ加えたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"須貝委員","kind":"質問・要望","question":"国でこういう大事なことが今回審議未了になったということは、やはり残念なことです。前向きでなおかつ素早くやるように実行していただきたいと私は強く言いたい、それだけは言いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"吉田委員","kind":"質問・要望","question":"ヘイトスピーチなのですけれども、今は外国人だけでなく、いろいろな弱い立場の人に向かってヘイトスピーチが行われているようにも聞いています。やはりヘイトスピーチということ自体が本来あってはならないものであるということをぜひ啓発していただけるように要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"}]},{"id":"topic-06","title":"「その他」を行います。 まず、今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会に係る項目","agenda":"「その他」を行います。 まず、今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会に係る項目","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"私のほうからは１点だけなのですけれども、具体的にどういうことが今検討されているのか、そのスケジュール観も含めて伺いたいと思います。なので、区の施設のあり方を検討するということはどういうことか、スケジュール観も含めてご説明ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858739?Template=document&Id=2026#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":36495,"voices":178}},{"id":"h27-20150925-6","meetingId":"h27-cm09","date":"2015年9月25日","dateIso":"2015-09-25","committee":"区民委員会","time":"午前１０時００分～午後 １時５５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件整理しています。","topics":[{"id":"topic-01","title":"町会・自治会の活動活性化のための支援制度の再構築","agenda":"町会・自治会の活動活性化のための支援制度の再構築","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"どういう角度で見直しをしているのかというところを、もう一度、しっかり伺いたいと思います。こういうものにはそぐわない、なじまないかなとちょっと思ったので、そのあたりを確認したいと思います。","respondent":"久保田地域活動課長","answer":"町会・自治会に説明があったときには加入しますといういい返事をもらえるのですけれども、そういったものは守られないといった状況があります。一般的なマンションの加入等の対応、役割として、そういうことをきちんとやりましょうということを促していきたいという考えです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"なぜ、説明を伺っても、まだよくわからないのです。そこを条例化することの意味というのがよくわからないから、もう一度、そこは伺っておきたいと思います。","respondent":"久保田地域活動課長","answer":"ともに品川のまちをつくっていきましょうということを明確にしたいということを考えてございまして、今回、条例化をしていくというものです。なぜ町会・自治会を支援するのかということを明確にしていきたいという意味もありまして、条例化を進めていきたいと考えているものです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"条例化されたとしても、そこは自由にしておくべきだと私は思っているのですけれども、そのあたりのことをどういうふうに考えているのかを聞きたい。私はそう思うのですが、区としてはどういうふうに思っていられるのか、そのあたりの見解を伺って、終わりにしておきたいと思います。","respondent":"久保田地域活動課長","answer":"私どもも、条例をつくればコミュニティが高まるなんていうふうには思ってございません。これとあわせて、一緒に町会・自治会の活動を支える各種支援制度もつくっていくですので、セットで活動を支えていきたいと考えています。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"最後に１点だけ述べて。そういうふうな危惧をすごく感じるので、そこのところは、少なくとも大事にしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問","question":"それから、２３区、もしくは他自治体でもいいのですけれども、こういう条例をつくっていらっしゃる自治体があるかどうかということ。その４点、お聞きします。","respondent":"久保田地域活動課長","answer":"具体的に考えているのですが、例えば自主的な活動を支えるような支援、仕組み。包括的に世帯割とか人口割で、町会・自治会の年間の活動を支援するために補助金を出していますけれども、それに加えて。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問・要望","question":"非常に一生懸命取り組んでいるということは確認していただいた中で、しっかりと区としても支援をしていくということは非常にいいことだと思うのです。一方で、我々としては町会に入っていただきたいのですけれども、さまざまな事情で入っていない方も４割いるわけですね。","respondent":"久保田地域活動課長","answer":"１点目ですけれども、そういった町会には、違う面での活動を支えるような支援をしていきたいというふうに考えてあります。町会・自治会長会議の説明についてですが、日程がございまして、もう既に４つの町会・自治会長会議でご説明をさせていただいたということです。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"４つの町会・自治会で話したところ、言えなくないですか、言いづらいですね。アンケートを配ったということだったのですけれども、そのアンケートというのはいつごろ配ったり、掲載したり、私、知らなくて、伺ってもいいか尋ねました。","respondent":"久保田地域活動課長","answer":"条例の中身はこれから検討しますけれども、品川区も活性化のための条例を制定しますとご説明したところ、そういったお答えをいただいたです。アンケートの実施ですが、平成２６年の秋、たしか９月から１１月ぐらいにアンケートを行ったというものです。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"その加入促進のパンフレットの作成は、確実に町会の方に渡すというわけではなくて、希望の町会の方にしか渡さないのですか。空き家などを活用した会館はまだないということなのですけれども、空き家の活用はそんなに簡単にできるものか尋ねました。","respondent":"久保田地域活動課長","answer":"平成２６年度に空き家の実態調査を行いまして、私どものほうで活用をするのですが、町会会館が欲しい町会の区域内に空き家があるかどうか。","id":"exchange-008"},{"speaker":"松永委員","kind":"質問","question":"１点、私は見たことがないのでお聞きしたいのが、「あなたは何丁目の町会員になります」みたいに書かれているのか。ぜひお願いしたいと思いますが、まず、どこ宛てに送られることになっているのか説明を求めました。","respondent":"久保田地域活動課長","answer":"わからないので、まずは一旦、私どものところに加入をしたい方は送っていただきます。両者でアポイントをとってもらって加入をしていくというような仕組みで、加入促進のはがきを活用しています。","id":"exchange-009"},{"speaker":"松永委員","kind":"質問・要望","question":"それはいつから始められたのか。教えてほしいと求めました。","respondent":"久保田地域活動課長","answer":"加入促進のはがきは平成２５年度ぐらいから始めていると思います。数は少ないかもしれませんけれども、２０件は来ているということで、それなりに少しずつは成果が上がってきているのかなと思っているところです。","id":"exchange-010"},{"speaker":"松永委員","kind":"質問・要望","question":"マンションを管理している偉い人がなかなか教えてくれない部分もあるのですけれども、マンションの加入促進について、何か案とかはあるのでしょうか。以前も、行事参加カードということで、そのほかに何かそういったものがあれば教えてほしいと求めました。","respondent":"久保田地域活動課長","answer":"分け隔てなく対応はしているのですが、そういったことに対して、これは町会がやっているのだと。ボランティアとして活動していること自体をなかなか認識してもらえないということもあるのかなというふうに思ってあります。","id":"exchange-011"},{"speaker":"松永委員","kind":"質問","question":"わかりました。お祭り等がある中で、できないとは思うのですが、町会に加入しませんかみたいなブースというのはつくれないのか尋ねました。","respondent":"久保田地域活動課長","answer":"そうですね。お祭りのことばかり考えていますので、今後、検討させていただきたいと思います。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"受け取った側としては、ああ、もういろいろ決まってしまっているのだなと思ってしまうと思うのです。きっとそういう少しの言葉のあれでコミュニケーションがとれなくなってしまったりとかすると思ったのですけれども、どうか尋ねました。","respondent":"久保田地域活動課長","answer":"私の説明が不足したのですけれども、実は４月にもアンケート等を持って、１３地区を回って説明をしています。もう２回ぐらいは来てくれるのだよねということをおっしゃってくれる地域もありますので、きちんと意見を聞いていきたいというふうに思ってあります。","id":"exchange-013"},{"speaker":"渡辺委員","kind":"質問・要望","question":"これももちろん項目ではあるので、その辺どうお考えかというか、その辺の支援の仕方というのを伺いたいと思います。これもやはりＰＲのところの評価に反映させるべきと思うのですが、その辺の考え方を３つ目として伺いたいと思います。","respondent":"久保田地域活動課長","answer":"いろいろな制度がありますが、小規模町会への支援ということも視野に入れながら、再構築の検討を進めていきたいと思ってあります。何か挑戦をしたいのだという気持ちを大切にするような支援制度も、今後、検討はしていきたいと思ってあります。","id":"exchange-014"},{"speaker":"渡辺委員","kind":"質問・要望","question":"スペシャリストというのですか、またその支援員の制度があるべきかな、必要が出てくるのかなという気がしています。全体会に行くのは結構だけれども、やはり自分の村といいますか、自分の町会だけの空間に来ていただくというのを求めると思う。","respondent":"久保田地域活動課長","answer":"丁寧に対応されているというふうに私どもは伺ってございまして、いろいろなお困りごととか悩みごとがあるというふうには考えているところです。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"うちは鹿嶋神社ですから、１０月にお祭りがあるのですけれども、町会にこんな方がいらっしゃったのですねという方が数多く出てくる。準備を入れて４日、５日しかないですけれども、答弁は一緒ではないか尋ねました。","respondent":"久保田地域活動課長","answer":"町会の中にはいろいろな宗教、考え方をお持ちの方もいますので、そこは町会の活動と祭礼行事を分離した形でやられているというのが現実だと思います。特定の宗教のほうに支援をするということは、ご支援、ご協力はしていきたいと思ってあります。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問・要望","question":"それはどういう法律なのか、わかれば教えていただきたい。憲法に出ていますとか、そういうのでいいのです。","respondent":"久保田地域活動課長","answer":"憲法のほうに規定をされているです。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"公務員の皆様は、憲法に準するとなっているのですから。憲法に出ている以上は、ちょっとその辺もこれから考えていっていただきたいという思いもあるのですけれども、いかがか尋ねました。","respondent":"久保田地域活動課長","answer":"私どもも、伝統的な文化行事という認識は一面には持ってありますので、できる範囲の中でご協力はさせていただいているです。憲法上の規定とかからも難しいというふうに考えてありますので、品川区としてできる範囲の中で、ご協力をさせていただいているです。","id":"exchange-018"},{"speaker":"藤原委員","kind":"確認","question":"その法の解釈をいろいろ考えても、今の時点ではできないということを確認させていただいて、すっきりした気持ちで質問を終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"渡部副委員長","kind":"質問","question":"たしか１００％の回答には至っていないのかなとは思ったのですが、だんだん書いているうちに、たくさんのことが記載されていたと思うのです。何かその辺、教えていただけるところがあれば、一言、説明を求めました。","respondent":"久保田地域活動課長","answer":"今、１３地区に回って意見を聞いているのですけれども、そういった中でいろいろなご意見やアイデアをいただければというふうに考えているところです。","id":"exchange-020"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"タウンマネジャーなのでしょうか、コーディネーターなのでしょうか、そういう方々の配置というのもあるかなと。地域センターの役割というのをどのようにお考えになっているのか、この時点であれば、教えていただきたい。","respondent":"久保田地域活動課長","answer":"今のところ予定はしてございませんけれども、こうした取組みの支援をしていく中で、地域センターのあるべき姿というものも考えながら。","id":"exchange-021"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"町会からの要望を地域センターである程度、時間もとらせずにというぐらい、地域センターで役割を持っていただきたいというような要望。第１回定例会で出てくるときに、また何か動きがありましたら、報告をいただきたいというふうにお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"ですから、加入をして、そこのところはきちんと整理をしていくべきだと私は思っているのです。政治団体ですから、個人のものですのであれですけど、その辺についての認識はどうなのかというのをちょっと聞いておきたいと思いました。","respondent":"久保田地域活動課長","answer":"私どもは、町会・自治会の活動を支えるですので、町会長、自治会長が個人の意思で活動されているということに関しては、私どもが意見等を言う立場にはないと考えています。","id":"exchange-023"},{"speaker":"南委員","kind":"意見","question":"どういうふうにするのか、区としては、少なくとも同一人物がかからないという角度で捉えていく必要はあるのではないかというふうに思うのです。言うべきことは言う、守るべきことは守るというふうにしていったほうがいいのではないかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-02","title":"秋季プレミアム付区内共通商品券発行事業への助成","agenda":"秋季プレミアム付区内共通商品券発行事業への助成","exchanges":[{"speaker":"南委員","kind":"質問","question":"品川区の問題として、もしあれば、そこは率直に伺いたいと思うのです。それがどういうところなのかというのを伺いたいのと、あと、たまたま３０％ぐらいとっているところも幾つかあるという状況なのです。","respondent":"山崎商業・ものづくり課長","answer":"この事業の交付金を国のほうが検討する際も、実は、プレミアムのほうの施策を練る一助になったというようなことで自負をしております。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"それなりに財政を投入してやってほしいというふうには思っているのですが、準備がもう進んでいるのですか、プレミアム率を２０％に。ゆとりのある財政状況もあるので、やはりやっていっていただきたいということを要望としてお伝えをしておきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"田中委員","kind":"意見","question":"１人の上限は幾らかということと、あと、販売方法がこの３つの場所で同じかということと、さっき南委員からも出たのですけれども、問題は本当になかったのかということを聞かせてくださいとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"これまで品川区も通常は年度で、春に３億円、秋に３億円というようなボリュームでやってきました。相当、いろいろ初日の対応だとかというのは必要だろうということで、ここでご報告する問題点というものは発生してございません。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問","question":"その販売方法が同じかというのをなぜ聞いたかというと、名前、住所を記入していれば、そういったことはきっと起きなかったではないですか。でも、他区の方でも買えてしまったそうなのですけれども、それは問題ではないのか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"裏面に住所などの基本情報を書いていただくということをもって、お買い求めいただいていますので、委員ご案内のようなことはなかったと。商店街振興の意味合いがありますので、品川区外の方でもお買い求めできるというようなことで、制度のほうは設計しております。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問","question":"書いている人は１人なのですけれども、それでも大丈夫なのですか。知り合いの名前とかをがーっと書いてしまって、１人の人がそれで買えてしまったことがあったのです。","respondent":"山崎商業・ものづくり課長","answer":"基本的には、買いに来られた方が申請書を書いて、お買い求めいただくというのが基本です。お買い求めをいただいた方のみが買えるといったような縛りがなく、柔軟に対応するような形で、窓口のほうは対応をしています。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問","question":"同居している方ではなくても、家族ではなくても買えてしまっていたわけではないですか。だから、販売方法とかをちょっと考えてみるべきだと思いますし、ちょっとそこら辺は考えていかなければいけないのではないかと思います。","respondent":"山崎商業・ものづくり課長","answer":"販売制限１人４万円まで、それから、代理購入の方ということだと思うのです。一つの検討事項かなというふうにも思ってありますので、今回は検討事項、制度のほうは考えていきたいと思います。","id":"exchange-030"}]},{"id":"topic-03","title":"区立総合区民会館・区立荏原平塚総合区民会館および区立体育館における指定管理者のモニタリング・評価結果","agenda":"区立総合区民会館・区立荏原平塚総合区民会館および区立体育館における指定管理者のモニタリング・評価結果","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"１点だけ。どういうプロセスでやっていくのかというところがもしあれば、教えていただきたい、改修していただきたいということです。","respondent":"間部文化観光課長","answer":"先ほどもご説明をさせていただきましたけれども、１階にはスーパーが入っておりまして、複合ビルになっております。今後も、工事をする際に、メニューとしてこちらから提案をしていくという形で対応してまいりたいというように考えてあります。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"できるだけ早く、そういう対応で、来年度中には、その工事が入っていければいいかなと考えていますので、そのことも含めて対応していただきたいとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"きゅりあんのことなのですけれども、大ホールの授乳室というのは、母子室のことですか。それとも、また別なのか尋ねました。","respondent":"間部文化観光課長","answer":"母子室は別に……。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問","question":"２番で、区からの指定管理料の返還につながったとなっているので、ここは利用料金制みたいな感じになっているのですか。それと、それに合わせて予算を、またもうちょっとハードルを上げるのかななんて思うのですけれども、その辺の考え方を説明するよう求めました。","respondent":"間部文化観光課長","answer":"大体、その分、返還金が当初予定より１,５００万円ぐらい多く返ってきたというようなことがございました。先ほど来、説明の中でもあったのですが、旧来、どうしても、例えばきゅりあんの大ホールで見ると、昼間に使われた場合、朝と夜と空くわけです。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"きゅりあんについてお伺いするのですけれども、２３区の各区においても、何か例があったら教えていただけますか。","respondent":"間部文化観光課長","answer":"２３区の利用率ですけれども、聞き及んでいる範囲におきますと、きゅりあんの日別での９割というのは非常に高いという評価をいただいております。立地もあるのですが、通常の区立の会館におきますと、大体６割程度だというふうにお聞きしています。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"その数字を今伺っても、高いですね。こういう利用率を維持していく館長は一体どういう経歴、どういうことをやってこられた方なのか、教えていただけますか。","respondent":"間部文化観光課長","answer":"我々、指定管理が入ってからになりますけれども、きゅりあんの管理課長がきゅりあんの館長ということです。今現在の館長も、先代の館長につきましても、区の管理職のＯＢです。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"指定管理ですから、課も部もあるのですけれども、そういうのはやはりＯＢの方たちを活用していく。ご本人の意思とかはいろいろあると思うのですけれども、これは大事なことだと思うのですが、その辺についてはいかがか尋ねました。","respondent":"間部文化観光課長","answer":"これはいろいろな考え方があると思うのですが、例えば福祉部門で管理職を務めた者が社会福祉法人のほうに行って活躍されているという例もあります。","id":"exchange-037"},{"speaker":"渡辺委員","kind":"質問","question":"その点は今、どう課題として捉えられているのかどうか。特に全区的なこの３施設、工夫が必要ではないかと思うのですが、いかがか尋ねました。","respondent":"池田スポーツ推進課長、間部文化観光課長","answer":"ということで、ソフト的な部分については、ここ何年もスポーツ協会、そして総合体育館という存在をＰＲするように努めてあります。委員のおっしゃいました看板ということにつきましては、これはどのようにやっていいかということで… スクエア荏原につきましては、今年度、３年目ということで、３年目にしては、私自身としては、知名度は上がっているかなという認識があります。","id":"exchange-038"},{"speaker":"渡辺委員","kind":"質問","question":"ですから、その場にお客様を運ばなくても、表示があれば意識の中で深まっていくと思うのです。ぜひご検討をほしいと求めましたが、もう一度、ご答弁をいただいて終わりにしたいと思います。","respondent":"池田スポーツ推進課長","answer":"委員のご意見は確かにそのとおりです。２つの駅が利用できるわけですけれども、歩いて１０分圏内ということですけれども、要請をしていきたいと思います。","id":"exchange-039"},{"speaker":"松永委員","kind":"質問・要望","question":"総合体育館は大体これぐらいということで教えていただきたいのと、どういったものが縮小されて、廃止になるのか。そしてまた、利用されている方の理解というのは、どういうふうに周知していくのかを教えてほしいと求めました。","respondent":"池田スポーツ推進課長","answer":"実際のところ、今年度は１回中止ということにさせていただきまして、また時期をうかがって再開というような形をとらせていただいてあります。実際に来られた人数が１桁、それも５人以内の少ない人数でございましたので、その場でお話はさせていただいてあります。","id":"exchange-040"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"最初の岡山市なのですけれども、もうちょっと勉強しなければいけなかったのですが、例えば、品川区でこのカウンターをやろうと思ったら、品川区の判断だけでできるというふうに思っていていいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"渡部副委員長","kind":"提案","question":"これは、僕、興味があると思って、委員長と提案させていただいたのですけれども、実は、ヤマダ電機がこの制度を使っていると考えられます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"藤原委員","kind":"質問","question":"品川区にどうやって活かして、視察に行ってからなのですけれども、同じ質問だったのです。そのための視察ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"藤原委員","kind":"質問","question":"だから、こうやってお答えできるわけではないですか。直接の質問ではないのですけれども、今の場面を見ていて、やはり区民委員会は時間を短くではなくて、こんな長くなる委員会なのだと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/878133?Template=document&Id=2734#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":56582,"voices":146}},{"id":"h27-20150925-7","meetingId":"h27-cm09","date":"2015年9月25日","dateIso":"2015-09-25","committee":"厚生委員会","time":"午前１０時００分～午後 ２時３０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)、平成２６年度 指定管理者の管理に対するモニタリング・評価の結果","agenda":"はじめに、(1)、平成２６年度 指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"ちょっとまずは何点かお伺いしていく中で、根本的なことをお伺いしたいのですが、それが１点と。では稼働率を達成したとかと書いてあるのですが、この利用率と稼働率の相関性についてという、その辺でお伺いします。","respondent":"永尾高齢者福祉課長","answer":"５月末までに指定管理者はモニタリングの報告書を区のほうに提出をして説明があり、それで経営会議を行って、本日の議会報告というふうになります。今度、その後なのですけれども、１０月末までに上半期の執行の状況というのを説明を区が指定管理のほうに求めます。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"その施設はサービスが向上されたということが目に見えてわかりますので、必要ではないかなと思うのですが、その辺についてお伺いします。下では稼働率が達成したと書いてあると、どういう意味なのかなと思ってしまうので、その辺は統一をしっかりしてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"それで、あと、満足度というのは実は本当は難しいことかなというふうに思います。ただ、このモニタリングの中で、それでこの項目を設定しているという状況になっています。","id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問・要望","question":"時代の流れに沿ったサービスを提供していく。あり余るサービスという言い方が妥当かどうかは別にしても、行政として見てほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"これをちょっと教えてほしいと求めました。区としてはどういったところを目指しているのか、考えがあったら、説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"年によって上下あるというのは一番変更があるのは単発的な工事があったときは多くなるし、それがないときには少ないというようなことになります。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"八潮南認知症高齢者グループホームは管理運営委託料というのが０円になっているのですが、なぜ０円なのかということを教えてほしいと求めました。この区としてのこの８割でもさらなる育成とあるということは、１００％を目指しているのか、その区の考えをちょっとお聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"例えば入院した期間が１カ月とかあった場合に、期間がはっきりしていると、そういう形でベッドを埋めていたりしています。ですので、区の目標としては、そういう工夫もしながら、空きベッドがないような状態にしてほしいということになります。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"把握されているのであれば、そういった指導とか、どういった形でやっていかれるのか説明を求めました。","respondent":"永尾高齢者福祉課長","answer":"虐待の対策になりますけれども、なかなか難しいところがあるとは思います。事業者への虐待というのはこういう中の取り組みをしていますけれども、そういうものの報告等も事業者からきちんと受けて対応しているところです。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、これまで品川でどのくらい件数があったのか、もしわかれば、教えてほしいと求めました。職員の離職率等なのですけれども、区としてはどう考えているのか、どう指導していくつもりなのか教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"児童虐待に対しての対応を緊急一時の保護等を行っておりますけれども、平成２５年度の数学でいきますと、高齢者が２２件になっています。障害者はたしか８件というふうに聞いています。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"区としてそういった給与ですとか収入の加算とか、そういった補助をするという考えがあるのか、そういう点を１つお聞きしたいと思います。どういったお考えなのか、大規模修繕してこのまま維持していくのか、そのお考えをお聞きしたいと思います。","respondent":"中山障害者福祉課長、松山高齢者地域支援課長","answer":"制度の全体の中でもやはり職員の処遇を上げていく必要はあるということで、それは制度の中身として今対応しています。多様な選択肢をどのようにその状況に合ったその方にふさわしい選択肢を選びながら対応していくかというのは大きな課… 高齢者住宅の老朽化への対応についてですけれども、現在、確かにどの施設も老朽化しつつはあります。細かな修繕をしつつ、あるいは、管理者による中長期計画に基づきまして、施設整備の所管と協議しながら検討をしている最中です。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"高齢者住宅の施設整備課と調整しているということですけれども、今もうちょっと具体的にお話しできる点があれば、教えてほしいと求めました。","respondent":"松山高齢者地域支援課長","answer":"高齢者住宅のもう少し具体的なところをですけれども、まだ個々のその住宅の建築や設備におきまして、かなり老朽化の度合いも異なっておりますので、具体的にちょっと今現在お話しできる状況にはございません。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"すみません。これは区立の施設ですけれども、区立でないところへの支援というのはどうなっているのかということもちょっと教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"その分の２分の１は自分の事業者のほうで持ってほしいとか、そういう細かい規定がありまして、その規定に基づいて払っているということです。人件費の助成を行うとか、収支をきちんと見た上で、区のほうで助成をするものも中にはあります。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところに対してのこの支援というのがちょっとどうなっているのかということを教えていただきたいのと。社会福祉法人それぞれにその虐待に対しての研修というのも全てされているのかということについてもちょっとお聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長","answer":"そういう社会福祉法人の原点に返ったサービスがきちんとできるかどうかという視点で区のほうでも指導をしていきたいなというふうに思います。健康管理のこと等も全てチェックしていますので… その障害の理解をした上で、適正な対応ができるかどうか、そこが多分一番職員にとっても苦しいところなのではないかと考えています。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今、原点に立ち返ってというふうなところで言われた、そのおりだと思いますので、ぜひよろしくお願いしたいと思います。そういうところで、ほかの社会福祉法人ではどうなっているのかということと、その点についてもちょっとお聞かせほしいと求めました。","respondent":"中山障害者福祉課長","answer":"先ほどちょっと力を入れて福栄会の話をしてまったのですけれども、もちろんほかの法人でも研修のほうは実施されています。こういう法人同士のこういういい取り組みがありますということを紹介する中で、そういった場をつくっていければいいかなというふうに思っております。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"すみません、よりよいものに変えていくみたいな、そういうふうなものというのはあるのかどうなのかということを１つ教えていただきたいのと。この中でも介護福祉士を１００％採ったとか、そういうときに、あったらどんなものがあるのかということもちょっと教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"試験を受けられなくなるように制度が変わる予定になっておりまして、今、介護福祉専門学校のほうで準備をしているところになります。ですので、来年度はもし予定どおりその実務者研修が必要になるというふうに決定になれば、その部分では区が助成をしているということになります。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"さらなるサービスの向上というふうなところにもつながっていくといいなというふうに思っていますので、そういうところも含めて、今後取り組んでいただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"石田委員","kind":"質問・要望","question":"健康センターは変わったりもしているけれども、このまま品川の福祉を担っていただく社福なわけではないですか。相手もこういうふうにいろいろ考えるという、改めてそこの指定管理とは、というところを教えていただきたい。","respondent":"永尾高齢者福祉課長","answer":"工夫、なかなか迅速な対応というのはできなくなってしまうということもあり、やはり区が直営というのはなかなか難しいのかなというふうに思います。","id":"exchange-015"},{"speaker":"石田委員","kind":"質問・要望","question":"区の意向が、例えば光熱水費のコスト意識を高めてＣＯ２削減を図ったとかいうのは、そういう意向があるわけではないですか。その１行を書き足して、その各施設でそれに向けてどういうふうにしているのだという項目を足すだけで、それは意識づけになるわけではないか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"項目につきましては、この帳票自体が区がもともとつくっているもので、項目につきましては企画の部門も含めて全体で検討は毎年しているところです。","id":"exchange-016"},{"speaker":"石田委員","kind":"質問","question":"これは区だからそういうことができたのだけれども、そういう部分はどう対応されているのかなとちょっと思うので。そういうことがあったときに、どういうほかの部分のところのフォローをされているのか、そこら辺のちょっと考え方を改めて伺いたいと思います。","respondent":"松山高齢者地域支援課長","answer":"本当に一般の方が対応してくださっていますので、やはり認知症の方への対応ですとか、そういう場合はどう対応するかというところですけれども。","id":"exchange-017"},{"speaker":"石田委員","kind":"質問・要望","question":"どうやって手立てがあるのかなと、どんどん多分これ、厳しくなっていくのだろうと思います。いろいろな事業者の方とも話していただいて、ともにそこの部分は一緒にやっていただければなと、これは要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"横山委員","kind":"質問","question":"そちらを区としてどういうふうに情報を管理して、どのようにお考えになっているのか、お聞かせください。２点目なのですけれども、評価に関する部分、ちょっとお聞かせいただけたらと思います。","respondent":"永尾高齢者福祉課長","answer":"これを受けて検討を行いまして、それがその結果が予算のほうに反映していくというような流れになります。それも検討する中で、またお金ではなくて、何か別の方法で何かしらインセンティブを与えられることを考えていきたいなというふうに思っております。","id":"exchange-019"},{"speaker":"横山委員","kind":"質問","question":"先ほどのほかの委員の方からもちょっとお話があったのですけれども、情報の共有の場というところですかね。今出ている課題を見ますと、横断的な視点を持った方が何かアドバイスであったり、ちょっとその辺ももう少し詳しく教えていただけないか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"区のワーカーも含み、ときには民生委員も含みというところの中で、解決に向けて取り組んでいっているところです。大体２カ月に１回、顔を合わせて、その中での情報共有を進めているところです。","id":"exchange-020"},{"speaker":"横山委員","kind":"質問","question":"別の質問になってしまうのですけれども、検討していらっしゃる段階かと思うのですけれども、その辺の見通しも詳しくお聞かせいただけたらなと思います。","respondent":"中山障害者福祉課長","answer":"ただ、実際には、６５歳になったからということでスムーズに移行ができるかというと、そこは難しいというような問題があります。高齢の部門も持っておりますので、そういった場を持つことで、徐々に進めていければいいかなというふうに今は考えているところです。","id":"exchange-021"}]},{"id":"topic-02","title":"後期高齢者医療制度保険料","agenda":"後期高齢者医療制度保険料","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"（９）の財政安定化基金の活用について、これは国が決めないと、区として活用できないのかということをちょっと確認したいと思います。（１０）のところで、このままやっていく考えなのか、お聞きしたいと思います。","respondent":"高森国保医療年金課長","answer":"２つございまして、その実施に当たりましては、低所得者に対する介護保険料軽減の拡充や年金生活者支援給付金の支給とあわせて実施することにより。今後検討し、結論を得るという形になっておりますので、現在不明ということで申し上げたものです。","id":"exchange-022"},{"speaker":"のだて委員","kind":"確認","question":"２ページ目のところで、１８億円とか２０億円、この今残っている金額ですね。ここに６６億円とありますが、そのまま変わってないのかという確認をお願いします。","respondent":"高森国保医療年金課長","answer":"実際には来年の１月が議会になりますので、例えば１０月とか１１月になったときに、４月か９月分の。平成２８年度、平成２９年度の保険料率を算定していくわけなので、この辺のところをご理解いただければというふうに思います。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり軽減していくためにも、この拠出というのは必要になってくると思いますので、ぜひこの広域連合でもそういった意見を伝えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"それで、そのときの平成２６年、平成２７年のときの財政安定化基金の拠出金というのはゼロになっているわけですよね。残りの１４５億円を保険料引き下げに使ったということなのですが、今は６６億円しかないとなれば、そのことをちょっと説明を求めました。","respondent":"高森国保医療年金課長","answer":"財政の安定化に資するために都道府県に設置されたということで、現在、平成２７年度で留保されている形にはなっているという意味です。それが足らないという判断になれば、積み立てということが行われるというふうに、そういうふうな考えでおります。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"でも、これはもうその中に入ってしまうわけだから、それ以上に取り崩すという財政安定化基金はあるのですか。私は前回も０円ではなくて、本来であれば、その点についてもちょっとその仕組みのところについてもお聞かせいただきたい。","respondent":"高森国保医療年金課長","answer":"それが４７都道府県それぞれに広域連合がありますので、それに対しての同額を拠出するというふうな形で対応していくというふうに、そういう理解でおります。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"その平成２８年度、平成２９年度の保険料を引き下げるために充てる財政安定化基金というのは、あるのかどうなのかということについてちょっとお聞かせいただけますか尋ねました。","respondent":"高森国保医療年金課長","answer":"申しわけございません。財政安定化基金に拠出する１１億円については、積み増しをするというふうな見込みで立てているというふうに聞いてあります。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"理解しました。その６６億円を確保するとしたら、３３億円分だけが保険料引き下げに、充当できるということで考えていいのか尋ねました。","respondent":"高森国保医療年金課長","answer":"９９億円が取り崩し可能額になりますけれども、議会がたしか来年の１月の末だというふうに聞いておりますので、また改めて決定した段階で議会のほうにも報告をするというような形になってくるというふうに理解しています。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"やめてほしいということで、区のほうからも強力に声を上げていただきたいと思うのですけれども、１点お聞かせいただきたいのと。これをやめてほしいということで、ぜひとも出していただきたいと思うのですけれども、その点についても説明を求めました。","respondent":"高森国保医療年金課長","answer":"軽減の人数は今、資料は持ち合わせておりません。平成２９年度から本当にこれが実施されてくると、平成２９年度ということで、方針についても国のほうが示していただいて。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"５倍、１０倍、ぜひ大きく声を上げていってほしいと求めました。いかがか尋ねました。","respondent":"高森国保医療年金課長","answer":"東京都に対しても軽減は継続するというふうな形で今、検討案が出ておりますので、国がそういう形でもってさまざまな変更があると。","id":"exchange-030"},{"speaker":"石田委員","kind":"確認","question":"１つだけ教えてください。特別対策というのは、もちろんできる既定だと思うのだけれども、それの確認だけ説明を求めました。","respondent":"高森国保医療年金課長","answer":"ほかの４６道府県はやっておりませんで、東京都だけが行っているということで、できる既定です。","id":"exchange-031"},{"speaker":"石田委員","kind":"質問・要望","question":"そういう形の中で、全てについて私はやはり手を入れていくべきだろうと思っているので、政令どおりやっていくというのがまず先決かなと思っています。そういう意見もあるということを必ず伝えてほしいと求めました。","respondent":"高森国保医療年金課長","answer":"継続というふうな形で要望していこうというふうな流れになっているのですけれども、市区町村は市区町村のまた考え方もありますから、ご意見として承っておきます。","id":"exchange-032"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"いながわ委員","kind":"意見","question":"たまたま１０月２７日が第１回目ということで、おそらく、どういう形でやられているかとかというのは。僕も気になっていますからとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/841532?Template=document&Id=3428#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":70340,"voices":99}}]);
